MP = {"WHEAT": (25, 400, "sqrt", 0.80, "log", 0.20), "CARROT": (35, 450, "hinge", 1.00, "sqrt", 0.70), "TOMATO": (60, 200, "hinge", 0.40, "sqrt", 0.60),
      "STRAWBERRY": (120, 100, "sqrt", 0.70, "linear", 1.60), "MELON": (250, 300, "log", 0.20, "sq", 3.60), "EGG": (50, 332, "hinge", 0.40, "log", 0.20),
      "MILK": (160, 122, "sqrt", 0.60, "linear", 1.60), "WOOL": (200, 105, "log", 0.20, "sq", 3.20), "FERTILIZER": (100, 200, "linear", 0.40, "linear", 0.40)}
# the lineage tape's own sales per day (days 12..29), c26 mirror mean over the 16 panel seeds: the opponent's supply profile
