def shape(f, x, T):
    x = max(0.0, x)
    if f == "linear": return x
    if f == "sq": return x * x
    if f == "sqrt": return math.sqrt(x)
    if f == "log": return math.log(1.0 + x)
    if f == "hinge": u = x / T; return u + 8.0 * max(0.0, u - 1.0) ** 2
    return x
# churn MV_GATE: marginal-margin value of ONE extra unit of an animal product, from the engine price function and observed state only
# (market inventory, both farms' herds, unlocked shops). Extra unit sold during the remaining days at the mid-path inventory; it lowers
# the price of the later half of our remaining units and of the opponent's (margin gain), consumption as today's shops.
MV_RATE = {'COW': 1.5, 'SHEEP': 4.0 / 3.0, 'GOOSE': 2.0}   # units per animal-day under daily feed + care (engine care bonus)
def _price_f(item, inv):
    base, T, fb, tb, fa, ta = MP[item]
    if inv < 10000: return base + tb * base / shape(fb, T, T) * shape(fb, 10000 - inv, T)
    return max(1.0, base - ta * base / shape(fa, T, T) * shape(fa, inv - 10000, T))
def mv_marginal(prod, kind, ctx):
    key = (ctx['day'], prod)
    c = S.setdefault('mv_cache', {})
    if key in c: return c[key]
    R = max(0, LAST_DAY - ctx['day'])
    def herd(tiles): return sum(1 for row in tiles for tt in row if isinstance(tt, dict) and tt.get('animal') == kind)
    nm = herd(ctx['tiles']); no = herd(ctx['opp_tiles']) if ctx.get('opp_tiles') is not None else 0
    cons = 1 + 6 * sum((2 if len(SHOPS[sh]) == 1 else 1) for sh in ctx.get('shops', ()) if prod in SHOPS.get(sh, ()))
    U = nm * MV_RATE[kind] * R; V = no * MV_RATE[kind] * R; C = cons * R
    x = ctx['inv'].get(prod, 10000) + (U + V - C) / 2.0
    slope = _price_f(prod, x) - _price_f(prod, x + 1)
    v = _price_f(prod, x) - slope * (U - V) / 2.0
    c.clear() if len(c) > 64 else None; c[key] = v
    if P['DEBUG']: log(f"d{ctx['day']} MV {prod} n {nm}/{no} x {x - 10000:.0f} p {_price_f(prod, x):.1f} slope {slope:.2f} mv {v:.1f}")
    return v
def market_price(item, inv):
    base, T, fb, tb, fa, ta = MP[item]
    if inv < 10000: p = base + tb * base / shape(fb, T, T) * shape(fb, 10000 - inv, T)
    else: p = base - ta * base / shape(fa, T, T) * shape(fa, inv - 10000, T)
    return max(1, int(round(p)))

_LOG = open(os.environ['CIRCUIT_LOG'], 'a') if os.environ.get('CIRCUIT_LOG') else None
def log(msg):
    if _LOG: _LOG.write(str(P.get('LOG_TAG', '')) + msg + '\n'); _LOG.flush()

def dist(a, b): return abs(a[0] - b[0]) + abs(a[1] - b[1])
def nearest_shed(pos): return min(SHED, key=lambda s: dist(s, pos))
def step_toward(pos, tgt):
    if pos[0] != tgt[0]: return ['EAST' if tgt[0] > pos[0] else 'WEST']
    if pos[1] != tgt[1]: return ['SOUTH' if tgt[1] > pos[1] else 'NORTH']
    return None
def fib(n):
    a = b = 1
    for _ in range(n): a, b = b, a + b
    return a

# ---------------------------------------------------------------- tile cadence -> stop
class Stop:
    __slots__ = ('pos', 'acts', 'needs', 'load', 'home', 'prem', 'ahy', 'wy')
    def load_ah(self): return getattr(self, 'ahy', 0) or 0
    def __init__(self, pos):
        self.pos = pos; self.acts = []; self.needs = {}; self.load = 0; self.home = nearest_shed(pos); self.prem = 0; self.ahy = 0; self.wy = 0
    def add(self, op, arg=None, value=0.0, mand=False):
        self.acts.append([op, arg, value, mand])
    def cost(self): return len(self.acts)
    def value(self): return sum(a[2] for a in self.acts)
    def copy(self):
        n = Stop(self.pos); n.acts = [list(a) for a in self.acts]; n.needs = dict(self.needs); n.load = self.load; n.prem = self.prem; n.ahy = self.load_ah(); n.wy = self.wy; return n

def filler_crop(ctx):
    """Crop planted on empty tiles today: wheat, or carrots late when the tape's LATE rule would fire."""
    day = ctx['day']; pr = ctx['prices']
    if day >= P['LATE_START']:
        if S.get('late_enabled') is None or (P['LATE_RETRY'] and not S['late_enabled'] and S.get('late_eval_day') != day):
            # decided once at LATE_START (tape rule); with LATE_RETRY re-evaluated every day until it fires
            wheat, carrot = pr['WHEAT'], pr['CARROT']
            net = 4 * carrot - 6 * wheat if day == 25 else (4 * carrot - 5 * wheat if day == 26 else 2 * (carrot - wheat))
            S['late_enabled'] = carrot >= P['LATE_RATIO'] * wheat and net > 20; S['late_eval_day'] = day
        if S['late_enabled']:
            if not P['CARROT_LATE_CAP']: return 'CARROT'
            if S.get('late_quota', 0) >= 1: S['late_quota'] -= 1; return 'CARROT'
    return 'WHEAT'

def target_for(pos, ctx):
    """What an empty tile at pos should become today: a crop name or 'PASTURE:COW' style structure."""
    t = S.get('target', {}).get(pos)
    if t and t != 'FILLER':
        # circ12 (TARGET_EXPIRE): an ongoing-crop target that can no longer mature falls back to the filler (carrots late) instead of wheat
        if P['TARGET_EXPIRE'] and t in CROPS and CROPS[t]['ongoing'] and ctx['day'] + CROPS[t]['first'] > LAST_DAY - 1: return filler_crop(ctx)
        return t
    return filler_crop(ctx)

def add_target(st, ctx, pos):
    tgt = target_for(pos, ctx)
    if tgt == 'HOLD': return
    if ':' in tgt:
        struct, animal = tgt.split(':')
        st.add('BUILD_' + struct, None, 50.0, False)
        avail = ctx['shed_animals'].get(animal, 0)
        if avail > 0:
            ctx['shed_animals'][animal] = avail - 1
            st.add('PLACE', animal, 600.0, False); st.needs[animal] = st.needs.get(animal, 0) + 1
        return
    add_plant(st, ctx, tgt)

def add_plant(st, ctx, crop):
    day = ctx['day']
    if day > P['PLANT_LAST_DAY']: return
    if crop == 'WHEAT' and day >= P['FAR_IDLE_DAY'] and dist(st.pos, st.home) >= P['FAR_IDLE_DIST']: return
    cd = CROPS[crop]
    if cd['ongoing'] and day + cd['first'] > LAST_DAY - 1: crop = 'WHEAT'; cd = CROPS[crop]
    days_left = LAST_DAY - day
    if days_left < cd['first']: return
    units = 1 + max(0, min(cd['maxday'], days_left) - (cd['maxday'] + 1) // 2 + 1) if not cd['ongoing'] else 4
    st.add('PLANT', crop, units * ctx['prices'][crop] * 0.6, False); st.needs['SEED:' + crop] = st.needs.get('SEED:' + crop, 0) + 1
    st.add('WATER', None, 0.0, True)          # a new plant must be watered on its planting day
    if P['C2'] and crop == 'CARROT' and ctx['prices']['FERTILIZER'] <= P['CARROT_FERT_MAXP'] and day + 2 <= LAST_DAY - 1:
        # lateexec C2: fertilize the new carrot on its planting day (active a0-a2): the age-2 watering gives +2 and the tile is
        # harvested at age 2 (3 carrots in 2 days instead of 4 in 3)
        st.add('FERTILIZE', None, P['C2_V'] * ctx['prices']['CARROT'], False); st.needs['FERTILIZER'] = st.needs.get('FERTILIZER', 0) + 1

def tile_stop(x, y, t, ctx):
    """Today's actions for one tile in execution order; None when nothing is needed."""
    day = ctx['day']; pr = ctx['prices']; st = Stop((x, y))
    if t == 'LOCKED': return None
    if t is None:
        add_target(st, ctx, (x, y)); return st if st.acts else None
    kind = t.get('kind')
    if kind == 'WEED':
        if day <= P['PLANT_LAST_DAY']:
            st.add('DIG', None, 5.0, False); add_target(st, ctx, (x, y))
        return st if st.acts else None
    if 'animal' in t:
        a = ANIMALS[t['animal']]; prod = a['product']; y_units = t.get('yield_units', 0)
        k = day + 1 - t['placed_day'] - a['first']
        produces_tonight = k >= 0 and k % a['interval'] == 0
        skip_feed = False
        if (x, y) in S.get('cull', set()):
            pass        # culled: no feed, no care; the animal escapes after two unfed nights and the structure is dug
        elif P['ENDGAME_FEED'] and day >= LAST_DAY - 2 and day < LAST_DAY:
            # remaining production nights: tonight (harvested tomorrow) and, on day 27, tomorrow night (harvested day 29)
            k2 = day + 2 - t['placed_day'] - a['first']
            prod_next = day + 1 <= LAST_DAY - 1 and k2 >= 0 and k2 % a['interval'] == 0
            bonus = t.get('pending_care_bonus', 0); unfed_prev = t.get('consecutive_unfed', 0) >= 1
            if not t.get('fed_today'):
                v = 0.0
                if produces_tonight: v += pr[prod] * (bonus + (1 if unfed_prev else 0))
                if prod_next: v += pr[prod] * (1 if unfed_prev else 0) + (pr[prod] if not t.get('cared_today') else 0) * 0.8
                if v > pr['WHEAT'] + 10: st.add('FEED', None, v - pr['WHEAT'], False); st.needs['WHEAT'] = 1
            if not t.get('cared_today') and prod_next and (t.get('fed_today') or 'WHEAT' in st.needs):
                st.add('CARE', None, pr[prod] * 0.8, False)
        elif day < LAST_DAY - 1:
            # Off nights with a fresh unfed counter can be skipped: escape needs two missed nights,
            # and a non-production night does not pay the care bonus. Geese produce every night, so they still eat.
            skip_feed = P['FEED_PROD'] and not produces_tonight and t.get('consecutive_unfed', 0) < 1
            if P['MV_GATE'] and not skip_feed and day >= P['MV_FROM'] and t['animal'] in P['MV_KINDS'] and not produces_tonight and t.get('consecutive_unfed', 0) < 1 and not t.get('fed_today'):
                _mv_skip = mv_marginal(prod, t['animal'], ctx) < pr['WHEAT'] + P['MV_LAB']
                if not P['MV_PLACEBO']: skip_feed = _mv_skip   # placebo arm: gate computed, decision discarded
            if not skip_feed:
                if not t.get('fed_today'): st.add('FEED', None, 400.0, True); st.needs['WHEAT'] = 1
                if not t.get('cared_today'): st.add('CARE', None, pr[prod] * P['CARE_W'], False)
        elif day == LAST_DAY - 1:
            bonus = t.get('pending_care_bonus', 0)
            if not t.get('fed_today') and produces_tonight and bonus > 0 and pr[prod] * bonus > pr['WHEAT']:
                st.add('FEED', None, pr[prod] * bonus, False); st.needs['WHEAT'] = 1
        if t.get('fertilizer_available') and pr['FERTILIZER'] >= P['COLLECT_MIN_PRICE'] and (day < LAST_DAY or P['COLLECT_LAST']):
            st.add('COLLECT_FERTILIZER', None, pr['FERTILIZER'], P['COLLECT_MAND']); st.load += 1
        if y_units > 0:
            cap_risk = produces_tonight and y_units + 1 + t.get('pending_care_bonus', 0) > a['max_held']
            ah_mand = cap_risk or day == LAST_DAY or skip_feed or P['ANIMAL_HARVEST_MAND']
            if (P['AH_V'] < 1.0 or P['OVF_DEFER']) and not ah_mand and day < LAST_DAY - 1:
                # lateexec: a harvest that can wait a day (no cap risk tonight) is tagged 'AH' (deferrable), valued AH_V x units x price
                st.add('HARVEST', 'AH', P['AH_V'] * y_units * pr[prod], False); st.load += y_units; st.ahy = y_units
            else: st.add('HARVEST', None, y_units * pr[prod], ah_mand); st.load += y_units
            if prod in P['PREM_ITEMS'] and pr[prod] >= P['PREM_MIN_PRICE']: st.prem += y_units
        return st if st.acts else None
    if kind == 'PLANT':
        crop = t['crop']; cd = CROPS[crop]; age = day - t['planted_day']; cu = t.get('consecutive_unwatered', 0)
        watered = t.get('watered_today', False); y_units = t.get('yield_units', 0); fert_ok = t.get('fertilized_until_day', -1) >= day
        must_water = cu >= 1 and not watered
        if not cd['ongoing']:
            ws = (cd['maxday'] + 1) // 2
            if day == LAST_DAY:
                if ws <= age <= cd['maxday'] and not watered and y_units < cd['max_yield']: st.add('WATER', None, pr[crop], False)
                if y_units > 0 and age >= cd['first']: st.add('HARVEST', None, y_units * pr[crop], True); st.load += y_units
                return st if st.acts else None
            if P['MELON_RUSH'] and crop == 'MELON' and cd['first'] <= age < cd['maxday'] and y_units + (0 if watered else (2 if fert_ok else 1)) >= cd['max_yield']:
                # melon rush: full yield is reached with today's watering -> water, harvest and carry to the shed now (see P['MELON_RUSH'])
                if not watered and y_units < cd['max_yield']:
                    st.add('WATER', None, pr[crop] * (2 if fert_ok else 1), True); y_units = min(cd['max_yield'], y_units + (2 if fert_ok else 1))
                st.add('HARVEST', None, y_units * pr[crop], True); st.load += y_units
                if crop in P['PREM_ITEMS'] and pr[crop] >= P['PREM_MIN_PRICE']: st.prem += y_units
                if not P['MELON_RUSH_NOPLANT']: add_target(st, ctx, (x, y))   # (no replant = 2 steps shorter loop; the tile is planted tomorrow)
                return st
            if P['MELON_EARLY'] and crop == 'MELON' and age >= cd['first'] and age < cd['maxday'] and y_units + (0 if watered else (2 if fert_ok else 1)) >= cd['max_yield']:
                # fable: full yield is reached today -> water (if needed), harvest, replant; the tile is freed 2 days earlier and the
                # melons sell before the opponent's same-age melons
                if not watered and y_units < cd['max_yield']: st.add('WATER', None, pr[crop] * (2 if fert_ok else 1), True); y_units = min(cd['max_yield'], y_units + (2 if fert_ok else 1))
                st.add('HARVEST', None, y_units * pr[crop], True); st.load += y_units
                if crop in P['PREM_ITEMS'] and pr[crop] >= P['PREM_MIN_PRICE']: st.prem += y_units
                add_target(st, ctx, (x, y)); return st
            # Opening only: a ripe wheat tile marked STRAWBERRY is cut at first yield and replanted. Off keeps the max-day harvest.
            if P['OPEN_RANK4'] and crop == 'WHEAT' and day <= 5 and age >= cd['first'] and y_units > 0 and S.get('target', {}).get((x, y)) == 'STRAWBERRY':
                st.add('HARVEST', None, y_units * pr[crop], True); st.load += y_units
                add_target(st, ctx, (x, y)); return st
            hage = cd['maxday']
            if crop == 'WHEAT' and P['WHEAT_CHECKER'] and (x + y) % 2 == 1 and day + 1 <= LAST_DAY - 1: hage = cd['maxday'] - 1
            # lateexec W3: every fertilized wheat tile on the 3-day cycle (1+2+2 = 5 units in 3 days beats 6 in 4 days); W3_FERT_ONLY keeps
            # unfertilized tiles on the 4-day cycle (4 in 4 = 3 in 3 per tile-day, one harvest+replant fewer)
            if crop == 'WHEAT' and P['W3'] and day + 1 <= LAST_DAY - 1 and day >= P['W3_FROM'] and (fert_ok or not P['W3_FERT_ONLY']): hage = cd['maxday'] - 1
            if crop == 'CARROT' and P['C2'] and day + 1 <= LAST_DAY - 1 and fert_ok: hage = cd['maxday'] - 1
            if age >= hage and age < cd['maxday'] and not (day == LAST_DAY):
                # early (3-day) harvest on checkerboard tiles: water first (+1), harvest, replant
                if not watered and y_units < cd['max_yield']: st.add('WATER', None, pr[crop] * (2 if fert_ok else 1), True); y_units += (2 if fert_ok else 1)
                if P['W3D'] and crop in ('WHEAT', 'CARROT') and fert_ok and day < LAST_DAY - 2:
                    # lateexec W3D: the early harvest (+ replant) is deferrable to tomorrow (age = maxday: 6 wheat instead of 5, the cycle
                    # shifts one day): value = W3D_V x price; dropping it drops the replant (drop_action), so peak days level out
                    st.add('HARVEST', 'DEFER', P['W3D_V'] * pr[crop], False); st.load += y_units
                else: st.add('HARVEST', None, y_units * pr[crop], True); st.load += y_units
                add_target(st, ctx, (x, y)); return st
            if age > cd['maxday']:            # decaying: harvest now, replant
                if y_units > 0: st.add('HARVEST', None, y_units * pr[crop], True); st.load += y_units
                else: st.add('DIG', None, 5.0, False)
                add_target(st, ctx, (x, y)); return st
            if age == cd['maxday']:
                if not watered and y_units < cd['max_yield']: st.add('WATER', None, pr[crop] * (2 if fert_ok else 1), True)
                st.add('HARVEST', None, (y_units + 1) * pr[crop], True); st.load += y_units + 1
                if crop in P['PREM_ITEMS'] and pr[crop] >= P['PREM_MIN_PRICE']: st.prem += y_units + 1
                add_target(st, ctx, (x, y)); return st
            # conversion of a young window crop to a higher-value target decided by the allocation layer
            tgt = S.get('target', {}).get((x, y))
            if tgt in ('CARROT', 'FILLER') and not P['CARROT_DIG']: tgt = None
            if tgt and tgt != crop and P['CONVERT_NOW'] and age <= cd['maxday'] - 2:
                if y_units > 0 and age >= cd['first']: st.add('HARVEST', None, y_units * pr[crop], False); st.load += y_units
                else: st.add('DIG', None, 5.0, False)
                add_target(st, ctx, (x, y)); return st
            if ws <= age < cd['maxday']:
                if not watered:
                    gain = pr[crop]
                    if P['FERT_WHEAT'] and age == ws and not fert_ok and pr['FERTILIZER'] <= (P['CARROT_FERT_MAXP'] if crop == 'CARROT' else ctx.get('fert_wheat_maxp', P['FERT_WHEAT_MAXP'])) and day + (cd['maxday'] - age) <= LAST_DAY:
                        extra = cd['maxday'] - age + 1
                        st.add('FERTILIZE', None, P['FERT_W_V'] * (extra * pr[crop] - pr['FERTILIZER']), False); st.needs['FERTILIZER'] = 1; gain *= 2
                    st.add('WATER', None, gain + (200.0 if must_water else 0.0), True)
                return st if st.acts else None
            if not watered and (must_water or (P['WATER_AGE1'] and age >= 1)):
                st.add('WATER', None, 250.0 if must_water else 2.0, must_water)
            return st if st.acts else None
        # ongoing crop
        k = day + 1 - t['planted_day'] - cd['first']
        prod_tonight = k >= 0 and k % cd['interval'] == 0 and (k // cd['interval'] + 1) <= cd['max_yield']
        finished = k >= 0 and k // cd['interval'] + 1 > cd['max_yield']
        if P['FIN_FIX'] and age >= cd['first']:
            # fable: the plant is finished the day its last production is available (for interval-2 strawberries the old test
            # fired one day late, when the units were already decaying 1 per 2 steps): harvest + dig + replant that day
            n_done = min(cd['max_yield'], (age - cd['first']) // cd['interval'] + 1)
            finished = n_done >= cd['max_yield']
        if finished or day == LAST_DAY:
            if y_units > 0 and age >= cd['first']:
                st.add('HARVEST', None, y_units * pr[crop], True); st.load += y_units
                if crop in P['PREM_ITEMS'] and pr[crop] >= P['PREM_MIN_PRICE']: st.prem += y_units
            if finished and day < LAST_DAY:
                st.add('DIG', None, 5.0, False); add_target(st, ctx, (x, y))
            return st if st.acts else None
        tgt = S.get('target', {}).get((x, y))
        if tgt and tgt != crop and P['CONVERT_NOW'] and day <= P['PLANT_LAST_DAY']:
            # allocation layer decided to replace this ongoing crop (strawberry cut): harvest what is there, dig, replant
            if y_units > 0 and age >= cd['first']: st.add('HARVEST', None, y_units * pr[crop], False); st.load += y_units
            st.add('DIG', None, 5.0, False); add_target(st, ctx, (x, y)); return st
        if y_units > 0:
            mand = prod_tonight and y_units + 2 > cd['max_yield']
            if prod_tonight or must_water or mand or P['OPP_HARVEST']:
                off = not (prod_tonight or must_water or mand)
                st.add('HARVEST', None, y_units * pr[crop] * (1.0 if not off else P['LATE_HARVEST_W']), mand or (off and P['OFFDAY_HARVEST_MAND']))
                st.load += y_units
                if crop in P['PREM_ITEMS'] and pr[crop] >= P['PREM_MIN_PRICE']: st.prem += y_units
        if prod_tonight:
            remaining_after = cd['max_yield'] - (k // cd['interval'] + 1)
            covers = 1 + (1 if remaining_after >= 1 and cd['interval'] <= 2 else 0)
            if P['FERT_ONGOING'] and not fert_ok and covers * pr[crop] > pr['FERTILIZER'] + 10 and (remaining_after >= 1 or P['FERT_LAST_PROD']):
                st.add('FERTILIZE', None, covers * pr[crop] - pr['FERTILIZER'], P['FERT_MAND']); st.needs['FERTILIZER'] = 1
            if not watered: st.add('WATER', None, pr[crop] + (250.0 if must_water else 0.0), True)
        elif must_water:
            st.add('WATER', None, 250.0, True)
        return st if st.acts else None
    if kind in ('COOP', 'PASTURE'):
        # empty structure: place a matching animal from the shed (bought today or left over), else dig and plant
        for animal in STRUCT_ANIMAL[kind]:
            if ctx['shed_animals'].get(animal, 0) > 0:
                ctx['shed_animals'][animal] -= 1
                st.add('PLACE', animal, 600.0, False); st.needs[animal] = 1
                return st
        tgt = S.get('target', {}).get((x, y), '')
        if tgt.startswith(kind) and S.get('buy_today'): return None      # animal arrives with today's purchase -> placed tomorrow
        if tgt.startswith(kind) and P['KEEP_STRUCT']:
            if day - S.get('target_day', {}).get((x, y), day) <= P['REBUY_DAYS']: return None   # purchase pending / retried: keep the structure
            S['target'][(x, y)] = 'FILLER'                                                     # the animal is not coming: back to the filler crop
        if day <= P['PLANT_LAST_DAY']:
            st.add('DIG', None, 5.0, False); add_target(st, ctx, (x, y))
        return st if st.acts else None
    return None

# ---------------------------------------------------------------- routing
def path_len(order, start):
    d = 0; cx, cy = start
    for x, y in order: d += abs(x - cx) + abs(y - cy); cx, cy = x, y
    return d

def nn_order(stops, start, end=None):
    rem = list(stops); order = []; cx, cy = start
    if end: ex, ey = end
    while rem:
        bi = 0; bk = None
        for i, s in enumerate(rem):
            x, y = s.pos; d = abs(x - cx) + abs(y - cy)
            k = (d, abs(x - ex) + abs(y - ey)) if end else d
            if bk is None or k < bk: bk = k; bi = i
        nxt = rem.pop(bi); order.append(nxt); cx, cy = nxt.pos
    return order

def two_opt(order, start, end=None):
    def total(o): return path_len([s.pos for s in o], start) + (dist(o[-1].pos, end) if end and o else 0)
    best = total(order); improved = True; n = len(order)
    while improved and n > 2:
        improved = False
        for i in range(n - 1):
            for j in range(i + 1, n):
                cand = order[:i] + order[i:j + 1][::-1] + order[j + 1:]
                c = total(cand)
                if c < best - 1e-9: order, best, improved = cand, c, True
    return order

def route_needs(stops):
    needs = {}
    for s in stops:
        for k, v in s.needs.items():
            if not k.startswith('SEED'): needs[k] = needs.get(k, 0) + v
    return needs

_RC = {}
def route_cost(stops, ret, exact=False):
    """Loading + actions + path from the nearest shed tile (+ return and DROP).  Memoised per clustering round."""
    if not stops: return 0
    key = None
    if not exact:
        key = (ret, B.get('clu', False), tuple(id(s) for s in stops))
        c = _RC.get(key)
        if c is not None: return c
    c = _route_cost(stops, ret, exact)
    if key is not None: _RC[key] = c
    return c

def _route_cost(stops, ret, exact):
    B['ops'] += 1
    start = stops[0].home
    end = start if ret else None
    order = nn_order(stops, start, end)
    if exact: order = two_opt(order, start, end)
    start = order[0].home
    keys = set()
    c = 0
    for s in stops:
        c += len(s.acts)
        if s.needs: keys.update(s.needs)
    if P['CREDIT']:
        for k in ('WHEAT', 'FERTILIZER'):
            if k in keys and credit_short(order, k) == 0: keys.discard(k)
    c += P['PICKUP_COST'] * sum(1 for k in keys if not k.startswith('SEED')) + path_len([s.pos for s in order], start)
    if P['FEED_CONS'] and B.get('clu') and 'WHEAT' in keys: c += P['FEED_CONS']   # lateexec FEED_CONS: clustering-only feeder penalty
    if ret: c += dist(order[-1].pos, order[-1].home) + 1
    return c

def credit_short(order, key):
    """lateexec CREDIT: units of key the route must load at the shed when wheat harvested (WHEAT) / fertilizer collected
    (FERTILIZER) earlier on the same route is used by its later FEED / FERTILIZE actions (CREDIT_MARGIN units kept spare)."""
    bal = 0; short = 0; use = 'FEED' if key == 'WHEAT' else 'FERTILIZE'
    for st in order:
        for a in st.acts:
            if a[0] == use:
                bal -= 1
                if bal < 0: short += -bal; bal = 0
            elif key == 'WHEAT' and a[0] == 'HARVEST' and st.wy > 0: bal += max(0, st.wy - P['CREDIT_MARGIN'])
            elif key == 'FERTILIZER' and a[0] == 'COLLECT_FERTILIZER': bal += 1
    return short

def route_credit_used(r):
    """lateexec CREDIT_OVF: carried units consumed on the route itself (harvested wheat fed / collected fertilizer spread later on
    the route) do not reach the day-end drop."""
    if not r: return 0
    order = nn_order(r, r[0].home); used = 0
    for key in ('WHEAT', 'FERTILIZER'):
        n_use = sum(1 for st in order for a in st.acts if a[0] == ('FEED' if key == 'WHEAT' else 'FERTILIZE'))
        used += max(0, n_use - credit_short(order, key))
    return used

def cluster_insert(stops, budgets, ret_flags):
    """Farthest-first cheapest insertion into capacitated routes."""
    _RC.clear()
    U = len(budgets); routes = [[] for _ in range(U)]; costs = [0] * U
    for s in sorted(stops, key=lambda s: (-dist(s.pos, nearest_shed(s.pos)), s.pos)):
        best = None
        for u in range(U):
            c = route_cost(routes[u] + [s], ret_flags[u])
            over = max(0, c - budgets[u])
            key = (over, c - costs[u] if not over else 0)
            if best is None or key < best[0]: best = (key, u, c)
        _, u, c = best
        routes[u].append(s); costs[u] = c
    return routes

def _centroid(r):
    if not r: return None
    return (sum(s.pos[0] for s in r) / len(r), sum(s.pos[1] for s in r) / len(r))

def refine(routes, budgets, ret_flags):
    """Move single stops between routes while the total cost (and over-budget) falls; candidate target routes limited to the
    REFINE_K nearest by centroid (0 = all)."""
    U = len(routes); K = P['REFINE_K']
    cost = [route_cost(r, ret_flags[u]) for u, r in enumerate(routes)]
    cents = [_centroid(r) for r in routes]
    for _ in range(4):
        moved = False
        for u in range(U):
            if budget_hit(): return routes
            for s in list(routes[u]):
                a = [x for x in routes[u] if x is not s]; ca = route_cost(a, ret_flags[u])
                best = None
                if K and U - 1 > K:
                    vs = sorted((v for v in range(U) if v != u), key=lambda v: dist(s.pos, cents[v]) if cents[v] else dist(s.pos, s.home))[:K]
                else:
                    vs = [v for v in range(U) if v != u]
                for v in vs:
                    b = routes[v] + [s]; cb = route_cost(b, ret_flags[v])
                    over_before = max(0, cost[u] - budgets[u]) + max(0, cost[v] - budgets[v])
                    over_after = max(0, ca - budgets[u]) + max(0, cb - budgets[v])
                    gain = (cost[u] + cost[v]) - (ca + cb)
                    key = (over_after - over_before, -gain)
                    if key < (0, 0) or (key[0] == 0 and gain > 0):
                        if best is None or key < best[0]: best = (key, v, b, cb)
                if best:
                    _, v, b, cb = best
                    routes[u] = a; routes[v] = b; cost[u] = ca; cost[v] = cb; moved = True
                    cents[u] = _centroid(a); cents[v] = _centroid(b)
                    break
        if not moved: break
    return routes

def trim_optional(routes, budgets, ret_flags):
    _RC.clear()
    dropped = []
    for u, r in enumerate(routes):
        if not r: continue
        while route_cost(r, ret_flags[u], P['EXACT_TRIM']) > budgets[u]:
            cands = [(act_value(s, a), s, a) for s in r for a in s.acts if not a[3]]
            if not cands: break
            if P['TRIM_DENS']:
                # lateexec TRIM_DENS: drop the action with the least value per step saved (its own steps + dependants, plus the stop's
                # detour when it is the stop's last action), so cheap one-step jobs on visited tiles outlive far single-purpose stops
                order = nn_order(r, r[0].home); idx = {id(z): i for i, z in enumerate(order)}
                def saving(z, a):
                    n_rm = 1
                    if a[0] == 'PLANT' or (P['DIG_DEP'] and a[0] == 'DIG') or (a[0] == 'HARVEST' and a[1] == 'DEFER'):
                        i = z.acts.index(a); n_rm = len(z.acts) - i if a[0] != 'PLANT' else 2
                    if n_rm >= len(z.acts):
                        i = idx.get(id(z)); prev = order[i - 1].pos if i and i > 0 else z.home
                        nxt = order[i + 1].pos if i is not None and i + 1 < len(order) else None
                        det = dist(prev, z.pos) + (dist(z.pos, nxt) - dist(prev, nxt) if nxt else 0)
                        n_rm += max(0, det)
                    return n_rm
                cands = [(v / max(1, saving(z, a)), z, a) for v, z, a in cands]
            _, s, a = min(cands, key=lambda z: z[0])
            if P['FILL'] > 0:
                ent = _FILLREF.get(id(routes))
                if ent is None or ent[0] is not routes: ent = _FILLREF[id(routes)] = (routes, {})
                ent[1].setdefault(u, []).append((s, [list(b) for b in s.acts], dict(s.needs), len(dropped), s.load))
            drop_action(s, a); dropped.append((s.pos, 'DEFER' if a[1] == 'DEFER' else a[0], a[2]))
            if not s.acts: r.remove(s)
    return dropped

_FILLREF = {}
SPAWN_ORDER = [(4, 4), (5, 4), (4, 5), (5, 5)]
def predict_spawns(n, occ):
    out = []
    for _ in range(n):
        t = min(SPAWN_ORDER, key=lambda q: (occ.get(q, 0), SPAWN_ORDER.index(q))); occ[t] = occ.get(t, 0) + 1; out.append(t)
    return out
def spawn_budgets(routes, bud_base, h0, h1, h2):
    """lateexec SPAWN_AWARE: hands appear on the shed tile with the fewest units (NWSE order; the farmer holds (4,4) at hour 0 and
    the hour-0 hands mostly still stand on their spawn tile at hour 1). Each hand route of a hire class is matched to one of the
    class's predicted spawn tiles (greedy, least extra walk) and its budget shrinks by the walk from that tile to its start."""
    occ = {(4, 4): 1}; sp = [predict_spawns(h0, occ), predict_spawns(h1, occ), predict_spawns(h2, occ)]
    out = list(bud_base); cls = [list(range(1, 1 + h0)), list(range(1 + h0, 1 + h0 + h1)), list(range(1 + h0 + h1, 1 + h0 + h1 + h2))]
    for c, us in enumerate(cls):
        tiles = list(sp[c]); starts = {}
        for u in us:
            r = routes[u] if u < len(routes) else None
            if r: o = nn_order(r, r[0].home); starts[u] = o[0].home
        pairs = sorted((dist(t, starts[u]), u, i) for u in starts for i, t in enumerate(tiles))
        du, di = set(), set()
        for dd, u, i in pairs:
            if u in du or i in di: continue
            du.add(u); di.add(i); out[u] = bud_base[u] - dd
    return out
XFILL_OPS = ('CARE', 'COLLECT_FERTILIZER', 'HARVEST')
def xfill_routes(routes, budgets, ret_flags, dropped, ctx):
    """lateexec XFILL: dropped inventory-free actions (CARE / COLLECT / off-day HARVEST) move, as one-action stops, into the route
    whose exact cost grows least while it stays within budget + slack (routes that finish early take work the busy routes shed)."""
    tiles = ctx['tiles']; out = []; cost = [route_cost(r, ret_flags[u], True) if r else 0 for u, r in enumerate(routes)]
    lim = [budgets[u] + (min(P['FILL'], P['HAND_SLACK']) if u > 0 else 0) for u in range(len(routes))]
    order = sorted(range(len(dropped)), key=lambda i: -dropped[i][2])
    moved = set()
    for i in order:
        pos, op, val = dropped[i]
        if op not in XFILL_OPS or val < P['XFILL_MIN']: continue
        t = tiles[pos[1]][pos[0]]
        if not isinstance(t, dict): continue
        if op == 'HARVEST' and 'animal' not in t and t.get('kind') != 'PLANT': continue
        best = None
        for u, r in enumerate(routes):
            if not r or cost[u] >= lim[u]: continue
            if any(z.pos == pos and any(a[0] == op for a in z.acts) for z in r): continue
            st = Stop(pos); st.add(op, None, val, False)
            if op == 'HARVEST': st.load = t.get('yield_units', 0)
            if op == 'COLLECT_FERTILIZER': st.load = 1
            _RC.clear(); c = route_cost(r + [st], ret_flags[u], True)
            if c <= lim[u] and (best is None or c - cost[u] < best[0]): best = (c - cost[u], u, st, c)
        if best:
            _, u, st, c = best; routes[u].append(st); cost[u] = c; moved.add(i)
    _RC.clear()
    return [d for i, d in enumerate(dropped) if i not in moved]

XSWAP_OPS = ('CARE', 'COLLECT_FERTILIZER', 'HARVEST')
def xswap_routes(routes, budgets, ret_flags, dropped, ctx):
    """lateexec XSWAP: a dropped inventory-free action (CARE / COLLECT / animal HARVEST) whose tile is still on some route v comes
    back when one other stop of v moves to a nearby route u with room (same return flag) and both exact routes fit their limits
    (budget + slack): the slack left on u is spent to make room on v."""
    tiles = ctx['tiles']; U = len(routes)
    lim = [budgets[u] + (min(P['FILL'], P['HAND_SLACK']) if u > 0 else 0) for u in range(U)]
    cost = [route_cost(r, ret_flags[u], True) if r else 0 for u, r in enumerate(routes)]
    cents = [_centroid(r) for r in routes]; out = []; tries = 0
    for pos, op, val in sorted(dropped, key=lambda d: -d[2]):
        done = False
        t = tiles[pos[1]][pos[0]]
        if op in XSWAP_OPS and val >= P['XFILL_MIN'] and isinstance(t, dict) and 'animal' in t and tries < P['XSWAP_MAX']:
            v = next((u for u, r in enumerate(routes) if any(z.pos == pos for z in r)), None)
            if v is not None:
                sv = next(z for z in routes[v] if z.pos == pos)
                if not any(a[0] == op for a in sv.acts):
                    best = None
                    for s2 in routes[v]:
                        if s2 is sv: continue
                        us = sorted((u for u in range(U) if u != v and routes[u] and ret_flags[u] == ret_flags[v] and cost[u] < lim[u]),
                                    key=lambda u: dist(s2.pos, cents[u]) if cents[u] else 99)[:P['XSWAP_K']]
                        for u in us:
                            tries += 1; _RC.clear()
                            cu = route_cost(routes[u] + [s2], ret_flags[u], True)
                            if cu > lim[u]: continue
                            rv = [z for z in routes[v] if z is not s2]
                            sv.acts.append([op, None, val, False])
                            if op == 'COLLECT_FERTILIZER': sv.load += 1
                            if op == 'HARVEST': sv.load += t.get('yield_units', 0)
                            _RC.clear(); cv = route_cost(rv, ret_flags[v], True)
                            sv.acts.pop()
                            if op == 'COLLECT_FERTILIZER': sv.load -= 1
                            if op == 'HARVEST': sv.load -= t.get('yield_units', 0)
                            if cv <= lim[v] and (best is None or cu - cost[u] < best[0]): best = (cu - cost[u], s2, u, cu, cv)
                    if best:
                        _, s2, u, cu, cv = best
                        routes[v].remove(s2); routes[u].append(s2); cost[u] = cu; cost[v] = cv
                        # CARE / COLLECT before HARVEST in the stop's execution order
                        a_new = [op, None, val, False]; k = len(sv.acts)
                        if op in ('CARE', 'COLLECT_FERTILIZER'):
                            k = next((i for i, a in enumerate(sv.acts) if a[0] == 'HARVEST'), len(sv.acts))
                        sv.acts.insert(k, a_new)
                        if op == 'COLLECT_FERTILIZER': sv.load += 1
                        if op == 'HARVEST': sv.load += t.get('yield_units', 0)
                        cents[u] = _centroid(routes[u]); cents[v] = _centroid(routes[v]); done = True
        if not done: out.append((pos, op, val))
    _RC.clear()
    return out

def h0_sells_needed(shed, need, wbuf):
    free = 100 - sum(shed.values()); qs = sorted((v - (wbuf if k == 'WHEAT' else 0) for k, v in shed.items() if k in PRODUCTS), reverse=True); k = 0
    while k < len(qs) and qs[k] > 0 and free < need: free += qs[k]; k += 1
    return min(P['SELL0_MAX'], k)
def fill_routes(routes, budgets, ret_flags, dropped):
    """lateexec FILL: the plan trims every route to budget - HAND_SLACK; afterwards the trimmed optional actions are put back
    (most valuable first = reverse drop order) while the exact route stays within budget + FILL steps.  Execution still sheds optional
    actions when a unit runs late (shed_optional), so the slack step is used for optional work only."""
    ent = _FILLREF.get(id(routes)); refs = ent[1] if ent is not None and ent[0] is routes else {}; restored = set()
    for u, stack in refs.items():
        r = routes[u]; lim = budgets[u] + min(P['FILL'], P['HAND_SLACK'] if u > 0 else 0)
        while stack:
            s, acts, needs, k, ld = stack[-1]
            cur = (s.acts, s.needs, s in r, s.load)
            s.acts = [list(b) for b in acts]; s.needs = dict(needs); s.load = ld
            if not cur[2]: r.append(s)
            _RC.clear()
            if route_cost(r, ret_flags[u], True) > lim:
                s.acts, s.needs, s.load = cur[0], cur[1], cur[3]
                if not cur[2]: r.remove(s)
                _RC.clear(); break
            stack.pop(); restored.add(k)
    _FILLREF.clear()
    return [d for i, d in enumerate(dropped) if i not in restored]

DIG_DEPS = ('PLANT', 'WATER', 'BUILD_COOP', 'BUILD_PASTURE', 'PLACE', 'FERTILIZE')
def act_value(s, a):
    """trim value of an optional action; lateexec DIG_DEP: a DIG carries the value of the planting/building that needs the cleared tile"""
    if P['DIG_DEP'] and a[0] == 'DIG' and a in s.acts:
        i = s.acts.index(a)
        return a[2] + sum(b[2] for b in s.acts[i + 1:] if b[0] in DIG_DEPS)
    return a[2]

def drop_action(s, a):
    """Remove an action from a stop with its dependants (a planting takes its watering with it)."""
    _RC.clear()
    if a in s.acts:
        i = s.acts.index(a); s.acts.pop(i)
        if a[0] == 'PLANT':
            s.needs.pop('SEED:' + str(a[1]), None)
            if i < len(s.acts) and s.acts[i][0] == 'WATER': s.acts.pop(i)
        if a[0] == 'FERTILIZE': s.needs.pop('FERTILIZER', None)
        if a[0] == 'FEED': s.needs.pop('WHEAT', None)
        if P['LOADFIX'] and S.get('_tiles') is not None:
            # lateexec LOADFIX: a dropped harvest / collect no longer counts in the stop's carried load (day-end overflow check)
            t = S['_tiles'][s.pos[1]][s.pos[0]]
            if a[0] == 'COLLECT_FERTILIZER': s.load = max(0, s.load - 1)
            elif a[0] == 'HARVEST' and isinstance(t, dict) and ('animal' in t or (t.get('kind') == 'PLANT' and CROPS[t['crop']]['ongoing'])):
                s.load = max(0, s.load - t.get('yield_units', 0))
        if P['DIG_DEP'] and a[0] == 'DIG':
            # the planting / building after a DIG cannot happen on the uncleared tile: drop it with the DIG
            for b in s.acts[i:]:
                if b[0] == 'PLANT': s.needs.pop('SEED:' + str(b[1]), None)
                if b[0] == 'PLACE': s.needs.pop(b[1], None)
                if b[0] == 'FERTILIZE': s.needs.pop('FERTILIZER', None)
            del s.acts[i:]
        if a[0] == 'HARVEST' and a[1] == 'DEFER':
            for b in s.acts[i:]:
                if b[0] == 'PLANT': s.needs.pop('SEED:' + str(b[1]), None)
            del s.acts[i:]

# ---------------------------------------------------------------- day plan
def plan_loops(prem, n_units):
    """Premium collector loops: the fewest k loops (shed -> premium stops -> shed) each within PREM_LOOP_MAX steps; stops that
    do not fit are evicted (farthest first) and stay in the regular routes.  Returns (loops, evicted_ids)."""
    kmax = max(1, min(P['PREM_K_MAX'], n_units))
    prem = sorted(prem, key=lambda s: (dist(s.pos, s.home), s.pos))
    evicted = set()
    if P['PREM_ONE_PER_LOOP']:
        # one stop per loop, farthest tiles on the units that start earliest (unit 0 = farmer acts from hour 0); stops beyond the
        # unit count or the loop step cap are evicted to the regular routes
        fit = [s for s in prem if route_cost([s], True, True) <= P['PREM_LOOP_MAX']]
        keep = fit[:kmax]
        loops = [[s] for s in sorted(keep, key=lambda s: (-dist(s.pos, s.home), s.pos))]
        return loops, {id(s) for s in prem if not any(s is k for k in keep)}
    while True:
        cand = [s for s in prem if id(s) not in evicted]
        if not cand: return [], evicted
        best = None
        for k in range(1, min(kmax, len(cand)) + 1):
            cp = [s.copy() for s in cand]
            bud = [P['PREM_LOOP_MAX']] * k; rf = [True] * k
            loops = cluster_insert(cp, bud, rf)
            loops = refine(loops, bud, rf)
            over = sum(max(0, route_cost(lp, True) - P['PREM_LOOP_MAX']) for lp in loops)
            if best is None or over < best[0]: best = (over, loops)
            if over == 0 or budget_hit(): break
        over, loops = best
        if over == 0 or budget_hit():
            return [lp for lp in loops if lp], evicted
        # evict the farthest stop of the most over-budget loop
        worst = max(loops, key=lambda lp: route_cost(lp, True) - P['PREM_LOOP_MAX'])
        far = max(worst, key=lambda s: dist(s.pos, s.home))
        orig = next(s for s in cand if s.pos == far.pos); evicted.add(id(orig))

def melon_rush_tiles(ctx):
    """Melon tiles that reach full yield with today's watering (harvested today under P['MELON_RUSH'])."""
    if not P['MELON_RUSH']: return []
    day = ctx['day']; cd = CROPS['MELON']; out = []
    for y, row in enumerate(ctx['tiles']):
        for x, t in enumerate(row):
            if isinstance(t, dict) and t.get('crop') == 'MELON':
                age = day - t['planted_day']; fert_ok = t.get('fertilized_until_day', -1) >= day
                if cd['first'] <= age < cd['maxday'] and t.get('yield_units', 0) + (0 if t.get('watered_today') else (2 if fert_ok else 1)) >= cd['max_yield']: out.append((x, y))
    return out

# ---------------------------------------------------------------- micro: day-plan routing optimiser (agents/micro)
# Pasted verbatim into circuit_micro.py (see build_micro.py) just before `def plan_day`. Stdlib only; uses circuit globals
# (P, S, SHED, dist, nearest_shed, nn_order, two_opt, Stop, fib, log, LAST_DAY, time).
#
# Problem: prize-collecting multi-vehicle routing on the 10x10 grid. Vehicles = the units lx1 already chose (farmer + hands) with
# lx1's step limits (budget + FILL slack). A "node" is a visit to one tile carrying a subset of that tile's original actions
# (tile_stop output, in engine execution order). Cost of a route = actions + one PICKUP step per distinct carried input
# (feed wheat / fertilizer / animal) + Manhattan path from the shed tile nearest the first node (+ walk back and DROP for
# return routes) -- exactly lx1's route_cost(exact=True) model. Objective, lexicographic: (sum of over-limit steps, -value of the
# actions actually executable, total steps). Constraints: per-route step limit, the day-end shed-overflow cap on carried produce of
# non-return routes (same target as lx1), intra-tile precedence (a PLANT/BUILD needs every DIG/HARVEST before it on the tile, any
# action after a PLANT/BUILD needs it, a planting's own WATER comes with it), tile-changing bundles stay with the unit that owns the
# tile's other actions. Moves: 2-opt + or-opt inside routes, relocate / swap stops between routes, insertion of missing work
# (merged into an existing visit of the tile when possible), ejection (move one stop elsewhere to make room), replacement (drop
# lower-value independent optional actions for a higher-value missing bundle). Starts from lx1's final routes and orders, so the
# result is never worse than lx1 in the plan's own objective; returns None (lx1 plan kept) when nothing improves or on error.

_HD = {}
def _hd(p):
    v = _HD.get(p)
    if v is None: v = _HD[p] = dist(p, nearest_shed(p))
    return v

_KEY_OP = {'FEED': 'WHEAT', 'FERTILIZE': 'FERTILIZER'}
_TILE_CHANGE = ('DIG', 'PLANT', 'BUILD_COOP', 'BUILD_PASTURE', 'PLACE')

class _MT:
    """per-tile metadata of the original (untrimmed) stop"""
    __slots__ = ('pos', 'O', 'n', 'op', 'arg', 'val', 'mand', 'key', 'load', 'req', 'dep', 'tc', 'wy')
    def __init__(self, O):
        self.pos = O.pos; self.O = O; self.wy = getattr(O, 'wy', 0) or 0; A = O.acts; n = self.n = len(A)
        self.op = [a[0] for a in A]; self.arg = [a[1] for a in A]; self.val = [float(a[2]) for a in A]; self.mand = [bool(a[3]) for a in A]
        ncol = sum(1 for o in self.op if o == 'COLLECT_FERTILIZER'); nh = sum(1 for o in self.op if o == 'HARVEST')
        hl = (O.load - ncol) if nh else 0
        self.key = []; self.load = []
        for i in range(n):
            o = self.op[i]
            k = _KEY_OP.get(o)
            if o == 'PLACE': k = self.arg[i]
            self.key.append(k)
            self.load.append(1 if o == 'COLLECT_FERTILIZER' else (hl if o == 'HARVEST' and nh == 1 else 0))
        req = [set() for _ in range(n)]
        for i in range(n):
            o = self.op[i]
            if o in ('PLANT', 'BUILD_COOP', 'BUILD_PASTURE'):
                for j in range(i):
                    if self.op[j] in ('DIG', 'HARVEST'): req[i].add(j)
            for j in range(i - 1, -1, -1):
                if self.op[j] in ('PLANT', 'BUILD_COOP', 'BUILD_PASTURE'): req[i].add(j); break
            for j in range(i):
                if self.op[j] == 'HARVEST' and self.arg[j] == 'DEFER': req[i].add(j)
        ch = True
        while ch:
            ch = False
            for i in range(n):
                add = set()
                for j in req[i]: add |= req[j]
                if not add <= req[i]: req[i] |= add; ch = True
        self.req = req
        self.dep = [set(k for k in range(n) if i in req[k]) for i in range(n)]
        # a set of actions is tile-changing when it contains a DIG/PLANT/BUILD/PLACE or an action other actions depend on
        self.tc = [self.op[i] in _TILE_CHANGE or bool(self.dep[i]) or bool(req[i]) for i in range(n)]

class _MN:
    """a visit: tile metadata + the set of original action indices executed there"""
    __slots__ = ('m', 'ids', 'src', 'dirty', 'pos', 'kc')
    def __init__(self, m, ids, src=None):
        self.m = m; self.ids = set(ids); self.src = src; self.dirty = src is None; self.pos = m.pos; self.kc = None
    def nacts(self): return len(self.ids)
    def keys(self):
        if self.kc is None:
            m = self.m; self.kc = tuple(set(m.key[i] for i in self.ids if m.key[i]))
        return self.kc
    def load(self):
        m = self.m; return sum(m.load[i] for i in self.ids)
    def stop(self):
        if not self.dirty and self.src is not None: return self.src
        m = self.m; O = m.O; st = Stop(m.pos)
        for i in sorted(self.ids): st.acts.append(list(O.acts[i]))
        for i in sorted(self.ids):
            o = m.op[i]
            if o == 'FEED': st.needs['WHEAT'] = 1
            elif o == 'FERTILIZE': st.needs['FERTILIZER'] = st.needs.get('FERTILIZER', 0) + 1
            elif o == 'PLANT': st.needs['SEED:' + str(m.arg[i])] = st.needs.get('SEED:' + str(m.arg[i]), 0) + 1
            elif o == 'PLACE': st.needs[m.arg[i]] = st.needs.get(m.arg[i], 0) + 1
            elif o == 'HARVEST':
                if m.arg[i] == 'AH': st.ahy = m.load[i]
                st.prem = O.prem; st.wy = m.wy
        st.load = self.load()
        return st

def _okeys(order):
    c = set()
    for n in order: c.update(n.keys())
    return c

def _path(order, ret):
    if not order: return 0
    d = _hd(order[0].pos); px, py = order[0].pos
    for n in order[1:]:
        x, y = n.pos; d += abs(x - px) + abs(y - py); px, py = x, y
    if ret: d += _hd(order[-1].pos) + 1
    return d

def _credit_free(order, key):
    """CREDIT (lx2/lx3 lineage): wheat harvested / fertilizer collected earlier on the route covers its later FEED / FERTILIZE,
    so the route needs no PICKUP of that input (same rule as the circuit's credit_short == 0)"""
    bal = 0; use = 'FEED' if key == 'WHEAT' else 'FERTILIZE'; mg = P['CREDIT_MARGIN']
    for n in order:
        m = n.m
        for i in sorted(n.ids):
            o = m.op[i]
            if o == use:
                bal -= 1
                if bal < 0: return False
            elif key == 'WHEAT' and o == 'HARVEST' and m.wy > 0: bal += max(0, m.wy - mg)
            elif key == 'FERTILIZER' and o == 'COLLECT_FERTILIZER': bal += 1
    return True

def _ocost(order, ret):
    if not order: return 0
    ks = _okeys(order)
    if P['CREDIT']:
        for k in ('WHEAT', 'FERTILIZER'):
            if k in ks and _credit_free(order, k): ks = ks - {k}
    return sum(n.nacts() for n in order) + len(ks) * P['PICKUP_COST'] + _path(order, ret)

def _ins_delta(order, p, ret):
    """cheapest path delta and position for inserting a node at tile p into order"""
    if not order: return _hd(p) + ((_hd(p) + 1) if ret else 0), 0
    best = None
    q0 = order[0].pos
    d = _hd(p) + dist(p, q0) - _hd(q0)
    best = (d, 0)
    for k in range(1, len(order)):
        a = order[k - 1].pos; b = order[k].pos
        d = dist(a, p) + dist(p, b) - dist(a, b)
        if d < best[0]: best = (d, k)
    a = order[-1].pos
    d = dist(a, p) + ((_hd(p) - _hd(a)) if ret else 0)
    if d < best[0]: best = (d, len(order))
    return best

def _improve_route(order, ret, ops):
    """2-opt + or-opt (segments of 1-3) on an explicit order, full cost recompute (routes are short)"""
    if len(order) < 2: return order
    best = _path(order, ret); improved = True; n = len(order)
    while improved:
        improved = False
        for i in range(n - 1):
            for j in range(i + 1, n):
                ops[0] += 1
                cand = order[:i] + order[i:j + 1][::-1] + order[j + 1:]
                c = _path(cand, ret)
                if c < best: order, best, improved = cand, c, True
        for L in (1, 2, 3):
            for i in range(n - L + 1):
                seg = order[i:i + L]; rest = order[:i] + order[i + L:]
                for k in range(len(rest) + 1):
                    if k == i: continue
                    ops[0] += 1
                    for sg in (seg, seg[::-1]) if L > 1 else (seg,):
                        cand = rest[:k] + sg + rest[k:]
                        c = _path(cand, ret)
                        if c < best: order, best, improved = cand, c, True; break
                    if improved: break
                if improved: break
            if improved: break
    return order

def micro_opt(routes, budgets, ret_flags, dropped, stops, ctx, wall=None, final=True):
    t0 = time.perf_counter()
    # hard step cap: the whole agent step (lx1 planning + every micro stage) stays under OPT_STEP_CAP seconds
    left = ctx.get('t0', t0) + P['OPT_STEP_CAP'] - t0
    wall = min(P['OPT_WALL'] if wall is None else wall, left)
    if wall < 0.01:
        S['opt_obj'] = None; S['opt_stat'] = {'nowall': 1}; return None
    try:
        return _micro_opt(routes, budgets, ret_flags, dropped, stops, ctx, t0 + wall, final)
    except Exception as e:      # noqa  -- any failure keeps lx1's plan
        if P['DEBUG']:
            import traceback; log(f"OPT d{ctx['day']} EXC {e!r}\n{traceback.format_exc()}")
        S['opt_stat'] = {'exc': 1}
        return None

def _micro_opt(routes, budgets, ret_flags, dropped, stops, ctx, deadline, final):
    day = ctx['day']; U = len(routes); ops = [0]; OPS = P['OPT_OPS']; T0 = [time.perf_counter()]
    def out_of_time(): return ops[0] > OPS or time.perf_counter() > deadline
    lim = [budgets[u] + (min(P['FILL'], P['HAND_SLACK']) if u > 0 else 0) for u in range(U)]
    meta = {s.pos: _MT(s) for s in stops}
    # ---- initial solution: lx1's final routes in the order lx1's plan builder would produce
    R = []
    for u, r in enumerate(routes):
        if not r: R.append([]); continue
        end = None
        start = nearest_shed(r[0].pos); end = start if ret_flags[u] else None
        o2 = two_opt(nn_order(r, start, end), start, end)
        start = nearest_shed(o2[0].pos); end = start if ret_flags[u] else None
        o2 = two_opt(nn_order(r, start, end), start, end)
        R.append(o2)
    # align every routed stop to its tile's original actions (op match, arg for PLANT/PLACE, original order)
    claimed = {}
    NR = [[None] * len(R[u]) for u in range(U)]
    items = sorted(((u, k) for u in range(U) for k in range(len(R[u]))), key=lambda z: -len(R[z[0]][z[1]].acts))
    for u, k in items:
        s = R[u][k]; m = meta.get(s.pos)
        if m is None: return None
        cl = claimed.setdefault(s.pos, set()); ids = []; j = 0
        for a in s.acts:
            while j < m.n and (j in cl or m.op[j] != a[0] or (a[0] in ('PLANT', 'PLACE') and m.arg[j] != a[1])): j += 1
            if j >= m.n:
                # out-of-order single action (XFILL stop): first unclaimed match anywhere
                jj = next((q for q in range(m.n) if q not in cl and q not in ids and m.op[q] == a[0]), None)
                if jj is None: return None
                ids.append(jj); continue
            ids.append(j); j += 1
        cl.update(ids)
        NR[u][k] = _MN(m, ids, s)
    R = NR
    shed_keep = ctx.get('shed_keep', 0)
    cap = P['OVERFLOW_LATE'] if P['OVERFLOW_LATE'] > 0 and day >= LAST_DAY - 2 else P['OVERFLOW_TARGET']

    def present(pos):
        s = set()
        for u in range(U):
            for n in R[u]:
                if n.m.pos == pos: s |= n.ids
        return s

    def value_of(n, pres):
        m = n.m; v = 0.0
        for i in n.ids:
            if m.req[i] <= pres: v += m.val[i]
        return v

    def state_obj():
        over = 0; val = 0.0; cost = 0
        P_ = {}
        for u in range(U):
            for n in R[u]: P_.setdefault(n.m.pos, set()).update(n.ids)
        for u in range(U):
            c = _ocost(R[u], ret_flags[u]); cost += c; over += max(0, c - lim[u])
            for n in R[u]: val += value_of(n, P_[n.m.pos])
        return over, val, cost

    base = state_obj()
    nonret = [not f for f in ret_flags]
    def exp_total(): return shed_keep + sum(n.load() for u in range(U) if nonret[u] for n in R[u])
    load_room = [cap - exp_total()]
    cost = [_ocost(R[u], ret_flags[u]) for u in range(U)]
    changed = [False]
    stat = {'repair': 0, 'relocate': 0, 'swap': 0, 'insert': 0, 'insert_v': 0.0, 'eject': 0, 'replace': 0, 'intra': 0}

    # ---- repair: a planting / building whose tile-clearing prerequisite was trimmed cannot execute (lx1 plans its steps anyway)
    for u in range(U):
        for n in list(R[u]):
            m = n.m; pres = present(m.pos)
            bad = set(i for i in n.ids if not m.req[i] <= pres)
            if bad:
                n.ids -= bad; n.dirty = True; n.kc = None; changed[0] = True; stat['repair'] += len(bad)
                if not n.ids: R[u].remove(n)
    cost = [_ocost(R[u], ret_flags[u]) for u in range(U)]

    # ---- intra-route sequencing
    def intra(u):
        if len(R[u]) < 2: return
        c0 = _path(R[u], ret_flags[u]); o = _improve_route(list(R[u]), ret_flags[u], ops)
        if _path(o, ret_flags[u]) < c0: R[u] = o; cost[u] = _ocost(o, ret_flags[u]); changed[0] = True; stat['intra'] += 1
    for u in range(U): intra(u)

    # ---- inter-route relocate / swap: total steps down, no route pushed over its limit (or further over)
    def fits(u, c): return c <= lim[u] or c <= cost[u]
    def relocate_pass():
        moved = False
        for u in range(U):
            for n in list(R[u]):
                if out_of_time(): return moved
                if n not in R[u]: continue
                a = [x for x in R[u] if x is not n]; ca = _ocost(a, ret_flags[u])
                if nonret[u] == False: pass
                best = None
                for v in range(U):
                    if v == u: continue
                    if n.load() and nonret[v] and not nonret[u] and n.load() > load_room[0]: continue
                    d, k = _ins_delta(R[v], n.pos, ret_flags[v]); ops[0] += 1
                    b = R[v][:k] + [n] + R[v][k:]
                    cb = _ocost(b, ret_flags[v])
                    if cb > lim[v]: continue
                    gain = (cost[u] + cost[v]) - (ca + cb)
                    over_b = max(0, cost[u] - lim[u]) + max(0, cost[v] - lim[v]); over_a = max(0, ca - lim[u]) + max(0, cb - lim[v])
                    if over_a > over_b or (over_a == over_b and gain <= 0): continue
                    key = (over_a - over_b, -gain)
                    if best is None or key < best[0]: best = (key, v, b, cb)
                if best:
                    _, v, b, cb = best
                    if nonret[v] != nonret[u]: load_room[0] += (n.load() if nonret[u] else -n.load())
                    R[u] = a; R[v] = b; cost[u] = ca; cost[v] = cb; moved = True; changed[0] = True; stat['relocate'] += 1
        return moved
    def swap_pass():
        moved = False
        for u in range(U):
            for v in range(u + 1, U):
                if out_of_time(): return moved
                if nonret[u] != nonret[v]: continue
                for i in range(len(R[u])):
                    for j in range(len(R[v])):
                        ops[0] += 1
                        a = R[u][:i] + [R[v][j]] + R[u][i + 1:]; b = R[v][:j] + [R[u][i]] + R[v][j + 1:]
                        ca = _ocost(a, ret_flags[u]); cb = _ocost(b, ret_flags[v])
                        if ca > lim[u] and ca > cost[u]: continue
                        if cb > lim[v] and cb > cost[v]: continue
                        over_b = max(0, cost[u] - lim[u]) + max(0, cost[v] - lim[v]); over_a = max(0, ca - lim[u]) + max(0, cb - lim[v])
                        if over_a < over_b or (over_a == over_b and ca + cb < cost[u] + cost[v]):
                            R[u] = a; R[v] = b; cost[u] = ca; cost[v] = cb; moved = True; changed[0] = True; stat['swap'] += 1
                            break
                    else: continue
                    break
        return moved

    # ---- missing work: candidate bundles per tile
    def bundles(m, pres):
        out = []
        miss = [i for i in range(m.n) if i not in pres]
        for i in miss:
            if m.mand[i] and not m.req[i]: pass        # a mandatory action outside every route (over-limit day): candidate too
            if m.val[i] < P['OPT_MIN_V'] and not m.mand[i]: continue
            B = {i} | (m.req[i] - pres)
            # mandatory dependants that become executable with B (a new planting's WATER)
            for k in miss:
                if k not in B and m.mand[k] and m.req[k] and m.req[k] <= (pres | B) and (m.req[k] & B): B.add(k)
            if any(not (m.req[j] <= (pres | B)) for j in B): continue
            v = sum(m.val[j] for j in B)
            if v < P['OPT_MIN_V']: continue
            out.append((v, frozenset(B)))
        seen = set(); res = []
        for v, B in sorted(out, key=lambda z: -z[0]):
            if B in seen: continue
            seen.add(B); res.append((v, B))
        return res

    def try_insert(m, B, v, commit=True, only=None):
        """best feasible insertion of bundle B at tile m.pos; returns (dcost, u, how) or None"""
        tc = any(m.tc[j] for j in B)
        nodes = [(u, n) for u in range(U) for n in R[u] if n.m is m]
        if tc and len(nodes) > 1: return None
        bl = sum(m.load[j] for j in B); bkeys = set(m.key[j] for j in B if m.key[j])
        best = None
        for u in (range(U) if only is None else only):
            if nonret[u] and bl > load_room[0]: continue
            rk = _okeys(R[u])
            nk = sum(1 for k in bkeys if k not in rk) * P['PICKUP_COST']
            own = next((n for uu, n in nodes if uu == u), None)
            if tc and nodes and own is None: continue
            if own is not None: dc = len(B) + nk; how = ('merge', own)
            else:
                d, k = _ins_delta(R[u], m.pos, ret_flags[u]); dc = len(B) + nk + d; how = ('new', k)
            ops[0] += 1
            if cost[u] + dc > lim[u]: continue
            if best is None or dc < best[0]: best = (dc, u, how)
        if best and commit:
            dc, u, how = best
            if how[0] == 'merge':
                old = (set(how[1].ids), how[1].dirty); how[1].ids |= set(B); how[1].dirty = True; how[1].kc = None
            else: R[u].insert(how[1], _MN(m, B))
            c2 = _ocost(R[u], ret_flags[u])
            if c2 > lim[u]:
                # exact cost (pickups / CREDIT) above the estimate: undo
                if how[0] == 'merge': how[1].ids, how[1].dirty = old; how[1].kc = None
                else: R[u].pop(how[1])
                return None
            cost[u] = c2
            if nonret[u]: load_room[0] -= bl
            changed[0] = True
        return best

    def all_cands():
        C = []
        for pos, m in meta.items():
            pres = present(pos)
            for v, B in bundles(m, pres): C.append((v, m, B))
        C.sort(key=lambda z: (-z[0], z[1].pos))
        return C

    def insert_pass():
        any_ins = False
        while not out_of_time():
            C = all_cands(); done = False
            for v, m, B in C:
                if out_of_time(): break
                r = try_insert(m, B, v)
                if r:
                    stat['insert'] += 1; stat['insert_v'] += v; any_ins = done = True; intra(r[1]); break
            if not done: break
        return any_ins

    def eject_pass():
        """a bundle that fits nowhere: move one stop of a nearly-fitting route to another route with room, then insert"""
        for v_, m, B in all_cands():
            if out_of_time(): return False
            tc = any(m.tc[j] for j in B)
            nodes = [(u, n) for u in range(U) for n in R[u] if n.m is m]
            if tc and len(nodes) > 1: continue
            for u in range(U):
                if tc and nodes and nodes[0][0] != u: continue
                for n in list(R[u]):
                    if n.m is m: continue
                    a = [x for x in R[u] if x is not n]; ca = _ocost(a, ret_flags[u])
                    for w in range(U):
                        if w == u or nonret[w] != nonret[u]: continue
                        d, k = _ins_delta(R[w], n.pos, ret_flags[w]); ops[0] += 1
                        b = R[w][:k] + [n] + R[w][k:]; cb = _ocost(b, ret_flags[w])
                        if cb > lim[w]: continue
                        sv = (list(R[u]), list(R[w]), cost[u], cost[w])
                        R[u] = a; R[w] = b; cost[u] = ca; cost[w] = cb
                        r = try_insert(m, B, v_, only=[u])
                        if r:
                            stat['eject'] += 1; stat['insert_v'] += v_; changed[0] = True; intra(u); intra(w); return True
                        R[u], R[w], cost[u], cost[w] = sv
        return False

    def replace_pass():
        """drop lower-value independent optional actions from a route to make room for a higher-value missing bundle"""
        for v_, m, B in all_cands():
            if out_of_time(): return False
            tc = any(m.tc[j] for j in B)
            nodes = [(u, n) for u in range(U) for n in R[u] if n.m is m]
            if tc and len(nodes) > 1: continue
            for u in range(U):
                if tc and nodes and nodes[0][0] != u: continue
                r = try_insert(m, B, v_, commit=False, only=[u])
                if r: continue
                own = next((n for uu, n in nodes if uu == u), None)
                if own is not None: need = len(B) + sum(1 for k in set(m.key[j] for j in B if m.key[j]) if k not in _okeys(R[u]))
                else: need = len(B) + 1 + _ins_delta(R[u], m.pos, ret_flags[u])[0]
                need = cost[u] + need - lim[u]
                if need <= 0 or need > 4: continue
                # removable: optional, independent (no dependants present, not tile-changing), cheapest value first
                rem = []
                for n in R[u]:
                    mm = n.m
                    for i in n.ids:
                        if mm.mand[i] or mm.tc[i] or (n.m is m): continue
                        rem.append((mm.val[i], n, i))
                rem.sort(key=lambda z: z[0])
                take = []; tv = 0.0
                for val, n, i in rem:
                    if len(take) >= need: break
                    take.append((n, i)); tv += val
                if len(take) < need or tv >= v_ * 0.999: continue
                sv = ([(n, set(n.ids), n.dirty) for n in R[u]], list(R[u]), cost[u], load_room[0])
                for n, i in take:
                    n.ids.discard(i); n.dirty = True; n.kc = None
                    if nonret[u]: load_room[0] += n.m.load[i]
                R[u] = [n for n in R[u] if n.ids]
                cost[u] = _ocost(R[u], ret_flags[u])
                r = try_insert(m, B, v_, only=[u])
                if r:
                    stat['replace'] += 1; stat['insert_v'] += v_ - tv; changed[0] = True; intra(u); return True
                for n, ids, dt in sv[0]: n.ids = ids; n.dirty = dt; n.kc = None
                R[u] = sv[1]; cost[u] = sv[2]; load_room[0] = sv[3]
        return False

    # ---- anytime loop
    S['opt_obj'] = base
    if not all_cands() and not changed[0]:
        S['opt_stat'] = {'skip': 1}; return None
    for _round in range(6):
        if out_of_time(): break
        c = insert_pass()
        a = relocate_pass() if not out_of_time() else False
        if a: insert_pass()
        d = P['OPT_EJECT'] and not out_of_time() and eject_pass()
        e = P['OPT_REPLACE'] and not out_of_time() and replace_pass()
        if d or e: insert_pass()
        b = swap_pass() if not out_of_time() and P['OPT_SWAP'] else False
        if not (a or b or c or d or e): break
    new = state_obj()
    stat.update(base=base, new=new, ops=ops[0], sec=round(time.perf_counter() - T0[0], 4))
    S['opt_stat'] = stat
    better = (new[0] < base[0]) or (new[0] == base[0] and (new[1] > base[1] + 1e-6 or (abs(new[1] - base[1]) <= 1e-6 and new[2] < base[2])))
    if P['DEBUG']: log(f"OPT d{day} base {base} new {new} better {better} {stat}")
    S['opt_obj'] = new if (better and changed[0]) else base
    if not better or not changed[0] or not final: return None
    # ---- materialise
    new_routes = []; orders = []
    for u in range(U):
        o = [n.stop() for n in R[u]]
        new_routes.append(o); orders.append(list(o) if o else None)
    nd = []
    for pos, m in meta.items():
        pres = present(pos)
        for i in range(m.n):
            if i not in pres and not m.mand[i]: nd.append((pos, 'DEFER' if m.arg[i] == 'DEFER' else m.op[i], m.val[i]))
    return new_routes, nd, orders, new


def plan_day(ctx):
    rush = melon_rush_tiles(ctx)
    if not rush: return _plan_day(ctx)
    # melon rush day: every ripe melon tile on its own shed loop (PREM_LOOP machinery), enough units hired to run them at once
    saved = {k: P[k] for k in ('PREM_LOOP', 'PREM_LOOP_MAX', 'PREM_K_MAX', 'PREM_MAX_DIST', 'HANDS_MIN', 'PREM_MIN_PRICE', 'PREM_ONE_PER_LOOP')}
    P['PREM_LOOP'] = True; P['PREM_ONE_PER_LOOP'] = True; P['PREM_LOOP_MAX'] = P['MELON_RUSH_LOOP_MAX']; P['PREM_K_MAX'] = P['MELON_RUSH_K']; P['PREM_MAX_DIST'] = 8; P['PREM_MIN_PRICE'] = 0
    P['HANDS_MIN'] = max(P['HANDS_MIN'], min(P['HANDS_MAX'], min(P['MELON_RUSH_K'], len(rush)) - 1))
    try: return _plan_day(ctx)
    finally: P.update(saved)

def _plan_day(ctx):
    day = ctx['day']; tiles = ctx['tiles']; S['_tiles'] = tiles
    stops = []
    for y, row in enumerate(tiles):
        for x, t in enumerate(row):
            st = tile_stop(x, y, t, ctx)
            if st and st.acts:
                if P['CREDIT'] and isinstance(t, dict) and t.get('crop') == 'WHEAT' and any(a[0] == 'HARVEST' and a[3] for a in st.acts): st.wy = st.load
                stops.append(st)
    produce = sum(s.load for s in stops)
    hold = hold_plan(ctx, produce)
    ctx['shed_keep'] = P['WHEAT_BUFFER'] + sum(hold.values())
    if P['MT'] and P['MT_PLAN_KEEP']: ctx['shed_keep'] += min(P['MT_CAP'], sum(S.get('mt_hold_now', {}).values()))
    total_actions = sum(s.cost() for s in stops)
    est_moves = int(0.9 * total_actions)
    off = ctx['hour'] if ctx.get('replan') else 0          # circ12 LAND_H0 re-plan: hours already spent today
    farmer_budget = (24 if day < LAST_DAY else 22) - off
    lo = max(P['HANDS_MIN'] if day < LAST_DAY - 1 else (P['END_MIN'] if day == LAST_DAY - 1 else 3), min(P['HANDS_MAX'], (total_actions + est_moves) // 22))
    best_plan = None
    B['ops'] = 0; B['hit'] = None; B['deadline'] = ctx.get('t0', time.perf_counter()) + P['PLAN_WALL']
    n_buy = (1 if ctx.get('need_wheat_buy') else 0) + (1 if ctx.get('need_fert_buy') else 0) + len(S.get('buy_today', {}))
    if P['H0EST']:
        # lateexec H0EST: the hour-0 wheat / fertilizer buys are issued when the shed is short of the day's feeds / fertilizes, so
        # estimate them from today's stops (the old test compared with the herd size / 4 fertilizer only)
        n_feed = sum(1 for s_ in stops for a in s_.acts if a[0] == 'FEED'); n_fz = sum(1 for s_ in stops for a in s_.acts if a[0] == 'FERTILIZE')
        n_buy = (1 if ctx['shed'].get('WHEAT', 0) < n_feed + P['WHEAT_BUFFER'] else 0) + (1 if ctx['shed'].get('FERTILIZER', 0) < n_fz and ctx['prices']['FERTILIZER'] <= P['FERT_BUY_MAXP'] else 0) + len(S.get('buy_today', {}))
    n_sell0 = min(P['SELL0_MAX'], sum(1 for k, v in ctx['shed'].items() if k in PRODUCTS and v > (P['WHEAT_BUFFER'] if k == 'WHEAT' else 0))) if day < LAST_DAY else 0
    if P['H0H'] and day < LAST_DAY and not ctx.get('replan'):
        # lateexec H0H: only the hour-0 sells needed to make shed room for the hour-0 purchases; the freed order slots hire hands
        # at hour 0 (they act from hour 1 instead of hour 2)
        n_an = sum(1 for row in tiles for t in row if isinstance(t, dict) and 'animal' in t)
        est = max(0, n_an + P['WHEAT_BUFFER'] - ctx['shed'].get('WHEAT', 0)) + max(0, P['H0H_FERT'] - ctx['shed'].get('FERTILIZER', 0)) + sum(S.get('buy_today', {}).values())
        n_sell0 = min(P['SELL0_MAX'], h0_sells_needed(ctx['shed'], est + 2, P['WHEAT_BUFFER']) + sum(1 for k in P['H0H_KEEP'] if ctx['shed'].get(k, 0) > 0))
        S['h0h_est'] = n_sell0
    hmax = P['HANDS_MAX'] + (1 if P['ALLOC'] and sum(S.get('alloc_count', {}).get(a, 0) for a in ANIMALS) >= P['HANDS13_ANIMALS'] else 0)
    if P['PREM_LOOP'] and P['PREM_EXTRA_HAND'] and day < LAST_DAY and any(s.prem >= P['PREM_MIN'] and dist(s.pos, s.home) <= P['PREM_MAX_DIST'] for s in stops): hmax += 1
    def build(hands):
        h0 = max(0, min(hands, 10 - n_buy - n_sell0)); h1 = min(hands - h0, 9 if P['PLAN_H1ALL'] else 6); h2 = hands - h0 - h1
        # (lateexec PLAN_H1ALL: market_orders hires every remaining hand at hour 1 (10 order slots), so the plan gives them hour-1 budgets)
        # (hands hired at hour 0 act from hour 1: on a re-plan at hour 1 their budget is unchanged; only the farmer lost `off` steps)
        if day < LAST_DAY: budgets = [farmer_budget] + [23 - P['HAND_SLACK']] * h0 + [22 - P['HAND_SLACK']] * h1 + [21 - P['HAND_SLACK']] * h2
        else: budgets = [22 - off] + [21 - P['HAND_SLACK']] * h0 + [20 - P['HAND_SLACK']] * h1 + [19 - P['HAND_SLACK']] * h2
        if day == LAST_DAY and P['LAST_BUDGET'] > 0:
            # lateexec LAST_BUDGET: last-day routes (all return to the shed) are capped so the produce reaches the shed and sells
            # before the h22 sweep, when both farms dump their stock
            budgets = [min(b, P['LAST_BUDGET']) for b in budgets]
        ret_flags = [day == LAST_DAY] * len(budgets)
        loops = []; loop_dropped = []; budgets2 = list(budgets); looped = set()
        if P['PREM_LOOP'] and day < LAST_DAY:
            elig = [s for s in stops if s.prem >= P['PREM_MIN'] and dist(s.pos, s.home) <= P['PREM_MAX_DIST']]
            if elig:
                loops, evicted = plan_loops(elig, len(budgets))
                looped = {s.pos for lp in loops for s in lp}
                for u, lp in enumerate(loops):
                    budgets2[u] = max(4, budgets[u] - route_cost(lp, True))
        elif P['DAWN_LOOP'] and day < LAST_DAY:
            # strawberries already ripe at dawn, one loop, the farmer. Milk and wool stay on the normal route.
            def _ripe_straw(s):
                t = ctx['tiles'][s.pos[1]][s.pos[0]]
                return isinstance(t, dict) and t.get('crop') == 'STRAWBERRY' and t.get('yield_units', 0) > 0
            elig = sorted((s for s in stops if _ripe_straw(s)), key=lambda s: (dist(s.pos, s.home), s.pos))[:int(P['DAWN_K'])]
            if elig:
                saved = (P['PREM_K_MAX'], P['PREM_LOOP_MAX'], P['PREM_ONE_PER_LOOP'])
                P['PREM_K_MAX'] = 1; P['PREM_LOOP_MAX'] = P['DAWN_LOOP_MAX']; P['PREM_ONE_PER_LOOP'] = False
                try: loops, _ev = plan_loops(elig, 1)
                finally: P['PREM_K_MAX'], P['PREM_LOOP_MAX'], P['PREM_ONE_PER_LOOP'] = saved
                loops = [lp for lp in loops if lp][:1]
                looped = {s.pos for lp in loops for s in lp}
                if loops: budgets2[0] = max(4, budgets[0] - route_cost(loops[0], True))
        bud_base = list(budgets2)
        for _it in range(len(budgets) + 1):
            cp = [s.copy() for s in stops if s.pos not in looped]
            B['clu'] = True
            routes = cluster_insert(cp, budgets2, ret_flags)
            routes = refine(routes, budgets2, ret_flags)
            B['clu'] = False; _RC.clear()
            if P['SPAWN_AWARE'] and not loops:
                budgets2 = spawn_budgets(routes, bud_base, h0, h1, h2)
            dropped = trim_optional(routes, budgets2, ret_flags) + loop_dropped
            if day == LAST_DAY: break
            if P['PREM_RET']:
                # routes carrying premium produce return to the shed at the end of the day and drop (sold the same step)
                new = [u for u in range(len(routes)) if not ret_flags[u] and sum(s.prem for s in routes[u]) >= P['PREM_RET_MIN']]
                if new and not budget_hit():
                    for u in new: ret_flags[u] = True
                    continue
            # day-end overflow: goods carried at hour 23 beyond the shed room are discarded -> mark the heaviest
            # non-returning route as a return-drop route and re-cluster with its return cost in the budget
            exp_total = ctx.get('shed_keep', 0) + sum(sum(s.load for s in r) - (route_credit_used(r) if P['CREDIT_OVF'] else 0) for u, r in enumerate(routes) if not ret_flags[u])
            cap = P['OVERFLOW_LATE'] if P['OVERFLOW_LATE'] > 0 and day >= LAST_DAY - 2 else P['OVERFLOW_TARGET']
            if exp_total > cap and P['OVF_DEFER']:
                # lateexec OVF_DEFER: before paying for return trips, leave deferrable animal harvests ('AH') on the tile until tomorrow,
                # largest lots first (the units stay on the animal; nothing is lost while it is under max_held)
                ah = sorted(((s.load_ah(), u, s, a) for u, r in enumerate(routes) if not ret_flags[u] for s in r for a in s.acts if a[0] == 'HARVEST' and a[1] == 'AH'), key=lambda z: -z[0])
                for yv, u, s, a in ah:
                    if exp_total <= cap: break
                    drop_action(s, a); s.load -= yv; exp_total -= yv; dropped.append((s.pos, 'DEFER', 0.0))
                    if not s.acts: routes[u].remove(s)
            if exp_total <= cap: break
            cand = [u for u in range(len(routes)) if not ret_flags[u] and routes[u]]
            if not cand or budget_hit(): break
            cand.sort(key=lambda u: -(sum(s.load for s in routes[u]) - 0.5 * dist(routes[u][-1].pos, routes[u][-1].home)))
            excess = exp_total - cap
            for u in cand:               # mark enough return routes to cover the excess in one pass (OVERFLOW_MULTI) or one per pass
                ret_flags[u] = True; excess -= sum(s.load for s in routes[u])
                if excess <= 0 or not P['OVERFLOW_MULTI']: break
        over = sum(max(0, route_cost(r, ret_flags[u], P['EXACT_TRIM']) - budgets2[u]) for u, r in enumerate(routes)) + sum(max(0, route_cost(lp, True) - P['PREM_LOOP_MAX']) for lp in loops)
        if P['FILL'] > 0 and P['FILL_HD'] and day < LAST_DAY and not loops:
            # lateexec FILL_HD: judge each hand count on the dropped value left after the slack fill
            dropped = fill_routes(routes, budgets2, ret_flags, dropped)
        dval = sum(d[2] for d in dropped)
        plan = (over, dval, hands, routes, dropped, budgets2 if P['SPAWN_AWARE'] and not loops else budgets, ret_flags, loops)
        if P['DEBUG']:
            kc = {}
            for d in dropped: kc[d[1]] = kc.get(d[1], 0) + 1
            log(f"  d{day} try hands {hands} over {over} dval {dval:.0f} ndrop {len(dropped)} kinds {kc} ops {B['ops']}")
        return plan
    for hands in range(lo, hmax + 1):
        plan = build(hands); over, dval, dropped = plan[0], plan[1], plan[4]
        if best_plan is None or (over, dval) < (best_plan[0], best_plan[1]):
            # an extra hand must save at least HAND_W x its wage in dropped value (HAND_W 0 = any improvement)
            if best_plan is None or over < best_plan[0] or best_plan[1] - dval >= P['HAND_W'] * fib(hands): best_plan = plan
        if over == 0 and not dropped: break
        if budget_hit(): break
        if best_plan[0] == 0 and hands > lo and dval > 0 and best_plan is not plan and best_plan[1] - dval < fib(hands): break
    if P['HIRE_DOWN'] and day < P['HIRE_DOWN_LAST'] and best_plan[0] == 0 and best_plan[2] == lo and not budget_hit():
        # the lower bound already drops nothing (or little): try fewer hands while the extra drops cost less than the wage saved
        base_dval = best_plan[1]
        for hands in range(lo - 1, max(P['HIRE_DOWN_MIN'], 3 if day >= LAST_DAY - 1 else P['HANDS_MIN']) - 1, -1):
            plan = build(hands); over, dval, dropped = plan[0], plan[1], plan[4]
            if over > 0 or dval - base_dval >= P['HIRE_DOWN_W'] * fib(hands) or budget_hit(): break
            best_plan = plan
    over, dval, hands, routes, dropped, budgets, ret_flags, loops = best_plan
    if P['OPT_HIRE'] and day < LAST_DAY and not loops and not ctx.get('replan'):
        # micro OPT_HIRE: the routing optimiser values each hand count (routed value of the executable actions); one more hand
        # while the value it adds exceeds its wage (fib), one fewer while the value lost stays under the wage saved
        h_lx1 = hands; hsave = (B['ops'], B['hit'], B['deadline'])
        try:
            def _ev(pl):
                micro_opt(pl[3], pl[5], pl[6], pl[4], stops, ctx, wall=P['OPT_HIRE_WALL'], final=False)
                if S.get('opt_obj') is None: raise RuntimeError('no time')
                return S['opt_obj']
            cur = (hands, best_plan, _ev(best_plan))
            hmin = P['HANDS_MIN'] if day < LAST_DAY - 1 else max(P['HIRE_DOWN_MIN'], 3)
            for direction in (1, -1):
                moved = False
                for _k in range(P['OPT_HIRE_MAX']):
                    h2 = cur[0] + direction
                    if h2 > hmax or h2 < hmin: break
                    if time.perf_counter() - ctx['t0'] > P['OPT_STEP_CAP'] - P['OPT_WALL'] - 2 * P['OPT_HIRE_WALL']: break
                    B['ops'] = P['PLAN_OPS'] - P['OPT_HIRE_OPS']; B['hit'] = None; B['deadline'] = time.perf_counter() + P['OPT_HIRE_WALL']
                    pl = build(h2); ob = _ev(pl); co = cur[2]
                    if direction > 0: ok = ob[0] < co[0] or (ob[0] == co[0] and ob[1] - co[1] > P['OPT_HIRE_W'] * fib(h2 - 1))
                    else: ok = ob[0] <= co[0] and co[1] - ob[1] < P['OPT_HIRE_W'] * fib(cur[0] - 1)
                    if not ok: break
                    cur = (h2, pl, ob); moved = True
                if moved: break
            if cur[0] != hands:
                best_plan = cur[1]; over, dval, hands, routes, dropped, budgets, ret_flags, loops = best_plan
        except Exception as e:      # noqa  -- keep lx1's hand count
            if P['DEBUG']: log(f"OPT_HIRE d{day} EXC {e!r}")
        B['ops'], B['hit'], B['deadline'] = hsave
        S['opt_hire'] = (day, h_lx1, hands)
        if P['DEBUG']: log(f"OPT_HIRE d{day} lx1 {h_lx1} -> {hands}")
    if P['FILL'] > 0 and not P['FILL_HD'] and day < LAST_DAY and not loops:
        n0 = len(dropped); dropped = fill_routes(routes, [b - (0 if u == 0 else 0) for u, b in enumerate(budgets)], ret_flags, dropped)
        if P['DEBUG']: log(f"d{day} FILL restored {n0 - len(dropped)} of {n0} dropped")
    if P['XFILL'] and P['FILL'] > 0 and day < LAST_DAY and not loops:
        n0 = len(dropped); dropped = xfill_routes(routes, budgets, ret_flags, dropped, ctx)
        if P['DEBUG']:
            kc = {}
            for d_ in dropped: kc[d_[1]] = kc.get(d_[1], 0) + 1
            log(f"d{day} XFILL moved {n0 - len(dropped)} of {n0} dropped; left {kc}")
            pk = {}
            for d_ in dropped:
                if d_[1] == 'PLANT':
                    t_ = ctx['tiles'][d_[0][1]][d_[0][0]]; k_ = 'EMPTY' if t_ is None else (t_.get('crop') or t_.get('kind')) if isinstance(t_, dict) else str(t_)
                    pk[k_] = pk.get(k_, 0) + 1
            log(f"d{day} PLANTDROP {pk}")
    if P['XSWAP'] and P['FILL'] > 0 and day < LAST_DAY and not loops:
        n0 = len(dropped); dropped = xswap_routes(routes, budgets, ret_flags, dropped, ctx)
        if P['DEBUG']: log(f"d{day} XSWAP restored {n0 - len(dropped)} of {n0}")
    opt_orders = None
    if P['OPT_ROUTE'] and day < LAST_DAY and not loops:
        # micro OPT_ROUTE: prize-collecting VRP local search over lx1's final routes (micro_opt); None keeps lx1's plan
        _res = micro_opt(routes, budgets, ret_flags, dropped, stops, ctx)
        if _res is not None: routes, dropped, opt_orders = _res[0], _res[1], _res[2]
    _FILLREF.clear()
    plans = []
    for u, r in enumerate(routes):
        lp = loops[u] if u < len(loops) else []
        if not r and not lp: plans.append(None); continue
        order = []
        if lp:
            start = nearest_shed(lp[0].pos)
            o1 = two_opt(nn_order(lp, start, start), start, start)
            start = nearest_shed(o1[0].pos)
            o1 = two_opt(nn_order(lp, start, start), start, start)
            shed_stop = Stop(nearest_shed(o1[-1].pos)); shed_stop.add('PLACE_PROD', 0, 30.0 * sum(s.prem for s in lp), True)
            order = o1 + [shed_stop]
        if r and opt_orders is not None and opt_orders[u]:
            order = order + opt_orders[u]           # micro OPT_ROUTE: the optimiser's explicit visiting order
        elif r:
            start = nearest_shed(r[0].pos) if not order else order[-1].pos
            o2 = two_opt(nn_order(r, start, start if ret_flags[u] else None), start, start if ret_flags[u] else None)
            if not order:
                start = nearest_shed(o2[0].pos)
                o2 = two_opt(nn_order(r, start, start if ret_flags[u] else None), start, start if ret_flags[u] else None)
            order = order + o2
        start = nearest_shed(order[0].pos)
        needs = route_needs(order)
        if P['FERT_CREDIT'] and needs.get('FERTILIZER', 0) > 0:
            # fertilizer collected from animals earlier on the same route is used on the crops: only the prefix shortfall is loaded
            bal = 0; short = 0
            for s_ in order:
                bal += sum(1 for a in s_.acts if a[0] == 'COLLECT_FERTILIZER')
                bal -= sum(1 for a in s_.acts if a[0] == 'FERTILIZE')
                if bal < 0: short += -bal; bal = 0
            if short < needs['FERTILIZER']:
                if short > 0: needs['FERTILIZER'] = short
                else: del needs['FERTILIZER']
        if P['CREDIT']:
            for k_ in ('WHEAT', 'FERTILIZER'):
                if needs.get(k_, 0) > 0:
                    sh = credit_short(order, k_)
                    if sh < needs[k_]:
                        if sh > 0: needs[k_] = sh
                        else: del needs[k_]
        if P['DEBUG']:
            nk = sum(1 for s_ in order for a in s_.acts if a[0] == 'COLLECT_FERTILIZER'); nz = sum(1 for s_ in order for a in s_.acts if a[0] == 'FERTILIZE')
            nh = sum(s_.load for s_ in order for a in s_.acts if a[0] == 'HARVEST' and ctx['tiles'][s_.pos[1]][s_.pos[0]] and isinstance(ctx['tiles'][s_.pos[1]][s_.pos[0]], dict) and ctx['tiles'][s_.pos[1]][s_.pos[0]].get('crop') == 'WHEAT')
            nf = sum(1 for s_ in order for a in s_.acts if a[0] == 'FEED')
            log(f"CRED d{day} u{u} fertneed {needs.get('FERTILIZER', 0)} collects {nk} fertilizes {nz} wheatneed {needs.get('WHEAT', 0)} feeds {nf} wheatharv {nh}")
        plans.append({'stops': order, 'needs': needs, 'loaded': {k: 0 for k in needs}, 'ret': ret_flags[u], 'idx': 0,
                      'budget': budgets[u], 'phase': 'load' if needs else 'work', 'unit': None, 'start': start})
    seeds_needed = {}
    for r in routes:
        for s in r:
            for k, v in s.needs.items():
                if k.startswith('SEED'): seeds_needed[k[5:]] = seeds_needed.get(k[5:], 0) + v
    pool = {}
    if P['POOL'] and day < LAST_DAY:
        for pos, op, val in dropped:
            if op in P['POOL_OPS']:
                st = pool.get(pos) or Stop(pos); st.add(op, None, val, False); pool[pos] = st
        for st in pool.values():
            # execution order: CARE/COLLECT before HARVEST, DIG last
            st.acts.sort(key=lambda a: {'WATER': 0, 'CARE': 1, 'COLLECT_FERTILIZER': 2, 'HARVEST': 3, 'DIG': 4}.get(a[0], 5))
    S['plan'] = {'day': day, 'produce': produce, 'farmer': plans[0], 'hands_free': [p for p in plans[1:] if p], 'hires_wanted': hands,
                 'nonret_load': sum(sum(s.load for s in r) for u, r in enumerate(routes) if not ret_flags[u]), 'shed_keep': ctx.get('shed_keep', P['WHEAT_BUFFER']), 'n_returns': sum(1 for f in ret_flags if f),
                 'seeds_needed': seeds_needed, 'wheat_need': sum(p['needs'].get('WHEAT', 0) for p in plans if p),
                 'fert_need': sum(p['needs'].get('FERTILIZER', 0) for p in plans if p), 'dropped': dropped, 'over': over, 'pool': list(pool.values())}
    if P['DEBUG']:
        log(f"d{day} plan hands {hands} stops {len(stops)} actions {total_actions} produce {produce} returns {sum(ret_flags)} over {over} dropped {len(dropped)}/{dval:.0f} ops {B['ops']} hit {B['hit']} wheat_need {S['plan']['wheat_need']} fert_need {S['plan']['fert_need']} seeds {seeds_needed}")
        for u, p in enumerate(plans):
            if p: log(f"   route {u} budget {p['budget']} cost {route_cost(p['stops'], p['ret'], True)} ret {p['ret']} needs {p['needs']} stops {[(s.pos, ''.join(a[0][0] for a in s.acts)) for s in p['stops']]}")

# ---------------------------------------------------------------- execution
def remaining_cost(p, pos):
    stops = p['stops'][p['idx']:]
    c = 0
    if p['phase'] == 'load':
        c += sum(1 for k, v in p['needs'].items() if p['loaded'].get(k, 0) < v)
        if tuple(pos) not in SHED: c += dist(pos, nearest_shed(pos))
    if not stops: return c + ((dist(pos, nearest_shed(pos)) + 1) if p['ret'] else 0)
    c += sum(s.cost() for s in stops) + path_len([s.pos for s in stops], pos)
    if p['ret']: c += dist(stops[-1].pos, nearest_shed(stops[-1].pos)) + 1
    return c

def shed_optional(p, pos, hours_left, ctx):
    while remaining_cost(p, pos) > hours_left:
        stops = p['stops'][p['idx']:]
        cands = [(act_value(s, a), s, a) for s in stops for a in s.acts if not a[3]]
        if P['CREDIT'] and any(a[0] == 'COLLECT_FERTILIZER' for _, _, a in cands):
            # lateexec: a collect whose fertilizer a later FERTILIZE on this route relies on (credited, not loaded) is kept
            have = p['loaded'].get('FERTILIZER', 0) if p['phase'] != 'load' else p['needs'].get('FERTILIZER', 0)
            have += ctx.get('inv_now', {}).get('FERTILIZER', 0) if False else 0
            if credit_short(stops, 'FERTILIZER') <= have:
                keep = []
                for v, z, a in cands:
                    if a[0] == 'COLLECT_FERTILIZER':
                        a2 = z.acts.index(a); z.acts.pop(a2); short = credit_short(stops, 'FERTILIZER'); z.acts.insert(a2, a)
                        if short > have: v = v + 200.0
                    keep.append((v, z, a))
                cands = keep
        if cands:
            _, s, a = min(cands, key=lambda z: z[0]); drop_action(s, a); S['shed_log'].append((ctx['hour'], s.pos, a[0]))
            if not s.acts: p['stops'].remove(s)
            continue
        if not stops: return
        worst = min(stops, key=lambda s: s.value() / max(1, s.cost()))
        p['stops'].remove(worst); S['shed_log'].append((ctx['hour'], worst.pos, 'STOP'))

def valid_action(a, tile, inv, ctx, seeds_left):
    op, arg = a[0], a[1]
    if op == 'WATER':
        return isinstance(tile, dict) and tile.get('kind') == 'PLANT' and not tile.get('watered_today')
    if op == 'HARVEST':
        return isinstance(tile, dict) and tile.get('yield_units', 0) > 0 and (('animal' in tile) or (ctx['day'] - tile.get('planted_day', 0) >= CROPS[tile['crop']]['first']))
    if op == 'PLANT':
        if tile is not None: return 'skip'
        return seeds_left.get(arg, 0) > 0
    if op == 'DIG':
        return tile is not None and not (isinstance(tile, dict) and 'animal' in tile)
    if op == 'FERTILIZE':
        if not (isinstance(tile, dict) and tile.get('kind') == 'PLANT') or tile.get('fertilized_until_day', -1) >= ctx['day']: return 'skip'
        return inv.get('FERTILIZER', 0) > 0
    if op == 'FEED':
        if not (isinstance(tile, dict) and 'animal' in tile) or tile.get('fed_today'): return 'skip'
        return inv.get('WHEAT', 0) > 0
    if op in ('BUILD_PASTURE', 'BUILD_COOP'):
        if tile is None: return True
        if isinstance(tile, dict) and tile.get('kind') == op[6:]: return 'skip'
        return False
    if op == 'PLACE':
        if isinstance(tile, dict) and 'animal' in tile: return 'skip'
        if not (isinstance(tile, dict) and tile.get('kind') == ANIMALS[arg]['structure']): return False
        return inv.get(arg, 0) > 0
    if op == 'CARE':
        return isinstance(tile, dict) and 'animal' in tile and not tile.get('cared_today')
    if op == 'COLLECT_FERTILIZER':
        return isinstance(tile, dict) and 'animal' in tile and tile.get('fertilizer_available')
    if op == 'PLACE_PROD':
        if not any(inv.get(i, 0) > 0 for i in P['PREM_ITEMS']) or a[1] >= 4: return 'skip'
        return True
    return False

def exec_unit(p, pos, inv, ctx, seeds_left, hours_left):
    tiles = ctx['tiles']
    if p['phase'] == 'load':
        for k, v in p['needs'].items():
            if p['loaded'].get(k, 0) < v:
                if tuple(pos) not in SHED: return step_toward(pos, nearest_shed(pos))
                avail = ctx['shed'].get(k, 0) - ctx['reserved'].get(k, 0)
                n = min(v - p['loaded'][k], max(0, avail))
                if P['LOAD_BUY'] and k in ('WHEAT', 'FERTILIZER') and n < v - p['loaded'][k] and p.get('_lb', 0) < 2 and ctx['day'] < LAST_DAY:
                    # lateexec LOAD_BUY: the shed is short of the feed wheat / fertilizer this route needs: buy the shortfall now (it
                    # lands after this step's unit actions) and wait one step instead of starting the route without it
                    short = v - p['loaded'][k] - max(0, n)
                    if n > 0:
                        p['loaded'][k] += n; ctx['reserved'][k] = ctx['reserved'].get(k, 0) + n
                    lb = S.setdefault('load_buy', {}); lb[k] = lb.get(k, 0) + short; p['_lb'] = p.get('_lb', 0) + 1
                    return ['PICKUP', k, n] if n > 0 else ['PASS']
                if n <= 0:
                    if P['WAIT_ANIMAL'] and k in ANIMALS and ctx['hour'] == 0 and S.get('buy_today', {}).get(k): return ['PASS']   # bought this step: load next hour
                    p['loaded'][k] = v; continue
                p['loaded'][k] += n; ctx['reserved'][k] = ctx['reserved'].get(k, 0) + n
                return ['PICKUP', k, n]
        p['phase'] = 'work'
    if p['phase'] == 'work':
        shed_optional(p, pos, hours_left, ctx)
        if P['MIDDROP_LAST'] and ctx['day'] == LAST_DAY and ctx['hour'] < 21 and tuple(pos) in SHED and p['idx'] < len(p['stops']) and sum(v for v in inv.values() if v > 0) >= P['MD_MIN'] and p.get('_mdl') != ctx['hour']:
            # lateexec MIDDROP_LAST: on the last day a unit passing the shed drops what it carries (sold this hour instead of at the
            # h22 sweep, where every farm dumps its stock)
            p['_mdl'] = ctx['hour']
            return ['DROP']
        if P['MIDDROP'] and p['ret'] and tuple(pos) in SHED and sum(v for v in inv.values() if v > 0) >= P['MD_MIN']:
            # lateexec MIDDROP: a return-drop route passing the shed drops here when the rest of its route carries little, and
            # skips the end-of-route return (DROP now = 1 step instead of walk back + DROP)
            rest = sum(st.load for st in p['stops'][p['idx']:])
            if rest <= P['MD_REST']:
                p['ret'] = False
                return ['DROP']
        while p['idx'] < len(p['stops']):
            s = p['stops'][p['idx']]
            if tuple(pos) != s.pos: return step_toward(pos, s.pos)
            tile = tiles[s.pos[1]][s.pos[0]]
            while s.acts:
                a = s.acts[0]
                # The morning plan can name a tile that is still locked until this day's hour-1 buy clears.
                if a[0] == 'PLANT' and tile == 'LOCKED' and (P['LAND_SEE'] or P['LAND_SEE_N'] > 0) and ctx['hour'] <= 1 and ctx['day'] < LAST_DAY:
                    return ['PASS']
                ok = valid_action(a, tile, inv, ctx, seeds_left)
                if ok is True:
                    s.acts.pop(0)
                    if a[0] == 'PLANT':
                        seeds_left[a[1]] -= 1; return ['PLANT', a[1]]
                    if a[0] == 'FEED': inv['WHEAT'] = inv.get('WHEAT', 0) - 1
                    if a[0] == 'FERTILIZE': inv['FERTILIZER'] = inv.get('FERTILIZER', 0) - 1
                    if a[0] == 'PLACE': inv[a[1]] = inv.get(a[1], 0) - 1; return ['PLACE', a[1]]
                    if a[0] == 'PLACE_PROD':
                        s.acts.insert(0, a); a[1] += 1          # keep the act until every premium item is placed (max 4 tries)
                        item = next(i for i in P['PREM_ITEMS'] if inv.get(i, 0) > 0); n = inv[item]; inv[item] = 0
                        ctx['dropping'][item] = ctx['dropping'].get(item, 0) + n
                        return ['PLACE', item, n]
                    return [a[0]]
                if a[0] == 'PLANT' and ok is False and ctx['hour'] <= 2 and ctx['day'] < LAST_DAY: return ['PASS']   # seeds arrive with the hour-1 order
                if a[0] == 'PLANT' and ok is False and P['OPEN_RANK4'] and ctx['day'] <= 5 and ctx['hour'] < 20: return ['PASS']   # fertilizer-funded seed lands later the same day
                if a[0] == 'PLACE' and ok is False and P['OPEN_RANK4'] and ctx['hour'] <= 8 and S.get('buy_today', {}).get(a[1]): return ['PASS']   # the morning buy has not reached the shed yet
                if P['DEBUG']:
                    t_ = tile; tk_ = (t_.get('crop') or t_.get('animal') or t_.get('kind')) if isinstance(t_, dict) else str(t_)
                    S.setdefault('exd', {}); kk = (a[0], 'skip' if ok == 'skip' else 'fail', tk_); S['exd'][kk] = S['exd'].get(kk, 0) + 1
                    if a[0] == 'FERTILIZE' and ok is False: log(f"FZFAIL d{ctx['day']} h{ctx['hour']} unit {p.get('unit')} needs {p['needs']} loaded {p['loaded']}")
                if ok == 'skip': s.acts.pop(0)          # already done (e.g. the planting landed): keep the dependants
                else: drop_action(s, a)
            p['idx'] += 1
        p['phase'] = 'return' if p['ret'] else 'done'
    if p['phase'] == 'return':
        if tuple(pos) in SHED:
            p['phase'] = 'done'; p['dropped'] = True
            return ['DROP'] if sum(inv.values()) > 0 else ['PASS']
        return step_toward(pos, nearest_shed(pos))
    return ['PASS']

def help_assign(idle_units, plans, positions, ctx, hours_left):
    if not P['HELP']: return
    for ui in idle_units:
        pos = positions[ui]; best = None
        for vj, p in plans.items():
            if p is None or vj == ui or p['phase'] != 'work': continue
            stops = p['stops'][p['idx']:]
            if len(stops) < 2: continue
            over = remaining_cost(p, positions[vj]) - hours_left
            if over <= 0 and len(stops) < 3: continue
            s = stops[-1]
            if any(k in ('WHEAT', 'FERTILIZER') for k in s.needs) or any(a[0] == 'PLACE_PROD' for a in s.acts): continue
            c = dist(pos, s.pos) + s.cost()
            if c > hours_left: continue
            saving = dist(stops[-2].pos, s.pos) + s.cost()
            key = (-(over > 0), -saving + c * 0.5)
            if over <= 0 and saving < 3: continue
            if best is None or key < best[0]: best = (key, vj, s)
        if best:
            _, vj, s = best
            plans[vj]['stops'].remove(s)
            plans[ui] = {'stops': [s], 'needs': {}, 'loaded': {}, 'ret': False, 'idx': 0, 'budget': 0, 'phase': 'work', 'unit': ui}
            if P['DEBUG']: log(f"d{ctx['day']} h{ctx['hour']} help: unit {ui} takes {s.pos} {''.join(a[0][0] for a in s.acts)} from unit {vj}")
            continue
        pool = S['plan'].get('pool') if P['POOL'] else None
        if pool:
            # dropped inventory-free actions: the idle unit takes the best-paying stop it can still reach and finish today
            bestp = None
            for s in pool:
                c = dist(pos, s.pos) + s.cost()
                if c > hours_left - 1: continue
                key = s.value() - P['POOL_W'] * c
                if bestp is None or key > bestp[0]: bestp = (key, s)
            if bestp:
                s = bestp[1]; pool.remove(s)
                plans[ui] = {'stops': [s], 'needs': {}, 'loaded': {}, 'ret': False, 'idx': 0, 'budget': 0, 'phase': 'work', 'unit': ui, 'pool': True}
                if P['DEBUG']: log(f"d{ctx['day']} h{ctx['hour']} pool: unit {ui} takes {s.pos} {''.join(a[0][0] for a in s.acts)} value {s.value():.0f}")
                continue
        if P['OPP_SCAN'] and ctx['day'] < LAST_DAY:
            opp_scan(ui, pos, plans, ctx, hours_left)

def opp_scan(ui, pos, plans, ctx, hours_left):
    """lateexec OPP_SCAN: an idle unit with nothing to help or pool takes the best nearby inventory-free job the tile state still
    offers today (CARE a fed, uncared animal; COLLECT available fertilizer; HARVEST a full animal/crop lot), skipping tiles that
    any active route still visits; value per step (distance + 1) must reach OPP_MIN."""
    busy = set()
    for p in plans.values():
        if p and p['phase'] in ('load', 'work'):
            for st in p['stops'][p['idx']:]: busy.add(st.pos)
    pr = ctx['prices']; tiles = ctx['tiles']; best = None
    for y in range(10):
        for x in range(10):
            t = tiles[y][x]
            if not isinstance(t, dict) or (x, y) in busy or (x, y) in S.setdefault('opp_taken', set()): continue
            acts = []
            if 'animal' in t:
                prod = ANIMALS[t['animal']]['product']
                if t.get('fed_today') and not t.get('cared_today'): acts.append(('CARE', pr[prod] * P['CARE_W']))
                if t.get('fertilizer_available') and pr['FERTILIZER'] >= P['COLLECT_MIN_PRICE']: acts.append(('COLLECT_FERTILIZER', pr['FERTILIZER']))
                if t.get('yield_units', 0) > 0 and P['OPP_HARV']: acts.append(('HARVEST', 1.0))
            if not acts: continue
            c = dist(pos, (x, y)) + len(acts)
            if c > hours_left: continue
            v = sum(a[1] for a in acts)
            key = v / c
            if key >= P['OPP_MIN'] and (best is None or key > best[0]): best = (key, (x, y), acts)
    if best:
        _, q, acts = best; st = Stop(q)
        for op, v in acts: st.add(op, None, v, False)
        S['opp_taken'].add(q)
        plans[ui] = {'stops': [st], 'needs': {}, 'loaded': {}, 'ret': False, 'idx': 0, 'budget': 0, 'phase': 'work', 'unit': ui, 'pool': True}
        if P['DEBUG']: log(f"d{ctx['day']} h{ctx['hour']} opp: unit {ui} takes {q} {[a[0] for a in acts]} key {best[0]:.0f}")

# ---------------------------------------------------------------- price-floor guard
def opp_supplies(item, day):
    """HOLD_OPP_GATE: the opponent sold >= HOLD_OPP_MIN units/day of item over the last HOLD_OPP_DAYS days (observed)."""
    if not P['HOLD_OPP_GATE']: return False
    rec = S.get('opp_sold', {}).get(item, {}); n = P['HOLD_OPP_DAYS']
    tot = sum(rec.get(d, 0) for d in range(day - n, day))
    return tot >= P['HOLD_OPP_MIN'] * n

def hold_plan(ctx, incoming):
    """Units of premium goods to keep in the shed this step: the quote is under HOLD_FRAC x base (floor sales destroy the unit,
    shop demand pulls the inventory back), capped so that held + reserves + today's incoming produce fit the shed."""
    hold = {}
    day = ctx['day']
    if day >= LAST_DAY or not (P['HOLD'] or P['TOM_HOLD'] or P['CARROT_HOLD']): S['hold'] = hold; return hold
    shed = ctx['shed']; pr = ctx['prices']; inv_now = ctx['inv']
    if P['TOM_HOLD'] and day <= P['TOM_HOLD_LAST']:
        # meter tomatoes along the hinge: sell only the units quoted at >= TOM_FLOOR, keep the rest (up to TOM_HOLD_MAX)
        q = shed.get('TOMATO', 0) + ctx['dropping'].get('TOMATO', 0)
        if q > 0:
            inv = inv_now.get('TOMATO', 10000); k = 0; floor = P['TOM_FLOOR']
            if P['TOM_END_RULE'] and ctx.get('opp_tiles') is not None:
                n_t = sum(1 for sh in ctx.get('shops', ()) if 'TOMATO' in SHOPS[sh])
                dem_rem = (LAST_DAY - day) * (1.0 + 6.0 * n_t)
                opp_rem = sum(farm_supply(ctx['opp_tiles'], day, 0.0)['TOMATO'])
                if dem_rem - opp_rem <= P['TOM_HOLD_OPP_W'] * opp_rem: floor = 0
            if opp_supplies('TOMATO', day): floor = 0
            while k < q and market_price('TOMATO', inv + k) >= floor: k += 1
            h = min(q - k, P['TOM_HOLD_MAX'])
            if h > 0: hold['TOMATO'] = h
    taper = min(1.0, (LAST_DAY - day) / P['HOLD_TAPER'])
    frac = P['HOLD_FRAC'] * taper
    items = list(P['HOLD_ITEMS']) if P['HOLD'] else []
    if P['CARROT_HOLD'] and 'CARROT' not in items and not opp_supplies('CARROT', day): items.append('CARROT')
    for item in items:
        q = shed.get(item, 0) + ctx['dropping'].get(item, 0)
        if q <= 0: continue
        thresh = (P['CARROT_HOLD_PRICE'] * taper) if item == 'CARROT' else MP[item][0] * frac
        inv = inv_now.get(item, 10000); n = 0
        while n < q and market_price(item, inv + n) >= thresh: n += 1
        if q - n > 0: hold[item] = q - n
    keep_other = P['WHEAT_BUFFER'] + sum(v for k, v in shed.items() if k not in PRODUCTS) + (min(P['MT_CAP'], sum(S.get('mt_hold_now', {}).values())) if P['MT'] else 0)
    tom = hold.pop('TOMATO', 0) if P['TOM_HOLD'] else 0
    room = P['OVERFLOW_TARGET'] - keep_other - incoming - sum(hold.values())
    while room < 0 and hold:
        item = min(hold, key=lambda k: pr[k]); d = min(hold[item], -room); hold[item] -= d; room += d
        if hold[item] <= 0: del hold[item]
    if tom > 0:
        # the tomato hold is exempt from the produce room check (the planner's return-drop routes make room for it)
        tom = min(tom, P['OVERFLOW_TARGET'] - keep_other - 20 - sum(hold.values()))
        if tom > 0: hold['TOMATO'] = tom
    S['hold'] = hold; return hold

# ---------------------------------------------------------------- sell-queue timing (SQ)
def sq_cons(shops, item, step):
    """Town consumption of item applied after the market of `step` (shops every 4 steps, town centre once a day)."""
    c = 0
    if step % 4 == 0:
        for sname in shops:
            pr = SHOPS.get(sname, ())
            if item in pr: c += 2 if len(pr) == 1 else 1
    if step % 24 == 0 and item != 'FERTILIZER': c += 1
    return c

def sq_observe(ctx, obs):
    """Attribute the market inventory change since the previous step to the opponent's sales (our own sales and the town's
    consumption are known; floor sales are invisible and skipped)."""
    step = ctx['step']; inv = ctx['inv']; shops = list(obs['town']['unlocked_shops'])
    prev = S.get('sq_prev'); hist = S.setdefault('sq_hist', {}); days = S.setdefault('sq_days', {})
    if prev and prev['step'] == step - 1:
        h = prev['step'] % 24
        for item in P['SQ_ITEMS']:
            if prev['price'].get(item, 0) <= 2: continue
            theirs = inv.get(item, 10000) - prev['inv'].get(item, 10000) + sq_cons(prev['shops'], item, prev['step']) - prev['my_sold'].get(item, 0)
            if theirs <= 0: continue
            hist.setdefault(item, [0.0] * 24)[h] += theirs
            days.setdefault(item, set()).add(prev['step'] // 24)
            S.setdefault('sq_daily', {}).setdefault(item, {}).setdefault(prev['step'] // 24, [0.0] * 24)[h] += theirs
    if prev and prev['step'] == step - 1 and P['HOLD_OPP_GATE']:
        for item in ('TOMATO', 'CARROT'):
            if prev['price'].get(item, 0) <= 2: continue
            theirs = inv.get(item, 10000) - prev['inv'].get(item, 10000) + sq_cons(prev['shops'], item, prev['step']) - prev['my_sold'].get(item, 0)
            if theirs > 0: S.setdefault('opp_sold', {}).setdefault(item, {}); S['opp_sold'][item][prev['step'] // 24] = S['opp_sold'][item].get(prev['step'] // 24, 0) + theirs
    S['sq_prev'] = {'step': step, 'inv': dict(inv), 'shops': shops, 'price': dict(ctx['prices']), 'my_sold': {}}

def sq_profile(item, today=None):
    hist = S.get('sq_hist', {}); days = S.get('sq_days', {})
    if P['SQ_DECAY'] < 1.0 and today is not None:
        daily = S.get('sq_daily', {}); dec = P['SQ_DECAY']
        def wavg(items):
            prof = [0.0] * 24; wsum = 0.0
            alld = set()
            for it in items: alld |= set(daily.get(it, {}))
            for d in alld:
                w = dec ** max(0, today - 1 - d); wsum += w
                for it in items:
                    row = daily.get(it, {}).get(d)
                    if row:
                        for h in range(24): prof[h] += w * row[h] / len(items)
            return [x / wsum for x in prof] if wsum > 0 else None
        if item in daily and len(daily[item]) >= P['SQ_MIN_DAYS']:
            r = wavg([item])
            if r: return r
        pooled = set()
        for d in daily.values(): pooled |= set(d)
        if daily and len(pooled) >= P['SQ_MIN_DAYS']:
            r = wavg(list(daily))
            if r: return r
        return [0.0] * 24
    if item in hist and len(days.get(item, ())) >= P['SQ_MIN_DAYS']:
        n = len(days[item]); return [x / n for x in hist[item]]
    pooled_days = set()
    for d in days.values(): pooled_days |= d
    if hist and len(pooled_days) >= P['SQ_MIN_DAYS']:
        k = max(1, len(hist)); n = len(pooled_days)
        return [sum(hist[i][h] for i in hist) / (n * k) for h in range(24)]
    return [0.0] * 24

def sq_plan(ctx, obs):
    """Hour-0 choice of the sell hour per premium item: minimise the predicted inventory at our sale (their lots before it,
    minus consumption; a lot of theirs in the same step counts half, we interleave with it)."""
    S['sq_hour'] = {}; S['sq_hour2'] = {}
    day = ctx['day']
    if not P['SQ'] or day >= LAST_DAY or day < P['SQ_START_DAY']: return
    shops = list(obs['town']['unlocked_shops']); base = ctx['step']
    for item in P['SQ_ITEMS']:
        if item in P['SQ_NOHOLD']: continue
        if P['PS'] and item in P['PS_ITEMS'] and day >= P['PS_START_DAY']: continue
        if ctx['prices'].get(item, 0) < P['SQ_MIN_PRICE']: continue
        if P['SQ_FIXED_HOUR'] is not None: S['sq_hour'][item] = P['SQ_FIXED_HOUR']; continue
        prof = sq_profile(item, day); w = P['SQ_W']
        I = 0.0; v0 = w * prof[0] * P['SQ_HALF']; best_v, best_h = v0, 0; vals = [v0]
        for h in range(1, P['SQ_MAX_HOUR'] + 1):
            I += w * prof[h - 1] - sq_cons(shops, item, base + h - 1)
            v = I + w * prof[h] * P['SQ_HALF']; vals.append(v)
            if v < best_v - 1e-9: best_v, best_h = v, h
        rng = random.Random(day * 7919 + P['SQ_RAND_SEED'] * 104729 + sum(ord(c) for c in item) * 31 + int(ctx['me']['money']) % 1000)
        mode = P['SQ_MODE']
        if mode == 'undercut':
            # synthetic adversary: sell one step before the opponent's biggest lot of the day (h0 if it is at h0/h1 or unknown)
            hm = max(range(24), key=lambda h: prof[h])
            if prof[hm] >= 1.0 and hm >= 2: S['sq_hour'][item] = hm - 1
            continue
        if mode == 'random':
            S['sq_hour'][item] = rng.randrange(0, P['SQ_MAX_HOUR'] + 1); continue
        if mode == 'mixed':
            # exploit a concentrated (fixed-hour) opponent with the argmin; against a diffuse profile (random / same-day sellers) use a
            # random hour, which cannot be timed against
            tot = sum(prof)
            conc = max(sum(prof[(h + j) % 24] for j in range(P['SQ_CONC_WIN'])) for h in range(24)) / tot if tot > 0 else 0.0
            if conc < P['SQ_CONC_MIN']:
                S['sq_hour'][item] = rng.randrange(0, P['SQ_MAX_HOUR'] + 1); continue
        if v0 - best_v >= P['SQ_MIN_GAIN']:
            if P['SQ_JITTER'] > 0:
                cands = [h for h in range(len(vals)) if vals[h] <= best_v + P['SQ_JITTER']]
                best_h = rng.choice(cands)
            S['sq_hour'][item] = best_h
            if P['SQ_SPLIT'] > 0:
                alt = [h for h in range(len(vals)) if abs(h - best_h) >= P['SQ_SPLIT_GAP'] and vals[h] <= best_v + P['SQ_SPLIT_TOL']]
                if alt:
                    h2 = min(alt, key=lambda h: vals[h]); S.setdefault('sq_hour2', {})[item] = h2
        if P['DEBUG']: log(f"SQ d{day} {item[:5]} prof {[round(x, 1) for x in prof]} h* {best_h} gain {v0 - best_v:.1f}")

def sq_hold(ctx):
    """Units of premium goods to keep in the shed this step (hour before the item's sell hour)."""
    hold = {}
    if not P['SQ'] or ctx['day'] >= LAST_DAY: return hold
    shed = ctx['shed']; hour = ctx['hour']
    for item, hstar in S.get('sq_hour', {}).items():
        q = shed.get(item, 0) - ctx['reserved'].get(item, 0) + ctx['dropping'].get(item, 0)
        if q <= 0: continue
        h2 = S.get('sq_hour2', {}).get(item)
        if h2 is None:
            if hour < hstar: hold[item] = q
            continue
        # split: fraction SQ_SPLIT at the later of the two hours; the rest at the earlier
        he, hl = min(hstar, h2), max(hstar, h2)
        frac_late = P['SQ_SPLIT'] if hl == h2 else 1.0 - P['SQ_SPLIT']
        if hour < he: hold[item] = q
        elif hour == he:
            keep = int(round(q * frac_late))
            if keep > 0: hold[item] = keep
        elif hour < hl: hold[item] = q
    return hold

def mt_thresh(item, day, hour):
    frac = P['MT_FLOOR_ITEM'].get(item, P['MT_FLOOR'])
    if P['MT_TAPER'] > 0: frac *= min(1.0, (LAST_DAY - day) / P['MT_TAPER'])
    if day >= LAST_DAY: frac *= max(0.0, (22 - hour) / 22.0) if P['MT_LASTDAY'] else 0.0
    return frac * MP[item][0]

def mt_hold(ctx, sqh):
    """Units of premium goods to keep in the shed this step under the price floor: of the q units offered, only the first n whose
    lockstep quote (walked along the curve from the current inventory) stays >= the floor are sold; MT_LOT caps the lot."""
    hold = {}
    S['mt_offer'] = {}
    if not P['MT'] or ctx['day'] < P['MT_START_DAY']: return hold
    if ctx['day'] == LAST_DAY and ctx['hour'] >= 22: return hold
    shed = ctx['shed']; inv_now = ctx['inv']; day, hour = ctx['day'], ctx['hour']
    for item in P['MT_ITEMS']:
        q = shed.get(item, 0) - ctx['reserved'].get(item, 0) + ctx['dropping'].get(item, 0) - sqh.get(item, 0) - S.get('hold', {}).get(item, 0)
        if q <= 0: continue
        inv = inv_now.get(item, 10000); thresh = mt_thresh(item, day, hour)
        if item in P['MT_WALL'] and market_price(item, inv) <= 1: continue      # wall release: the units vanish at $1, no market impact
        n = 0
        while n < q and market_price(item, inv + n) >= thresh: n += 1
        if P['MT_LOT'] > 0: n = min(n, P['MT_LOT'])
        S['mt_offer'][item] = n
        if q - n > 0: hold[item] = q - n
    # carry only what fits: MT_CAP, or (MT_CAP_ROOM) the shed room left after tonight's day-end drop; the excess is sold now,
    # cheapest relative quote first
    cap = P['MT_CAP']
    if P['MT_CAP_ROOM'] and 'plan' in S and day < LAST_DAY:
        cap = max(0, min(cap, P['OVERFLOW_TARGET'] - S['plan'].get('shed_keep', P['WHEAT_BUFFER']) - S['plan'].get('nonret_load', 0)))
    S['mt_cap_today'] = cap
    excess = sum(hold.values()) - cap
    if excess > 0:
        pr = ctx['prices']
        for item in sorted(hold, key=lambda k: pr[k] / MP[k][0]):
            d = min(hold[item], excess); hold[item] -= d; excess -= d; S['mt_offer'][item] = S['mt_offer'].get(item, 0) + d
            if hold[item] <= 0: del hold[item]
            if excess <= 0: break
    return hold

def ps_par(item, k):
    return P['PS_ITEM_P'].get(item, {}).get(k, P[k])

def ps_hold(ctx, sqh, mth):
    """premium spread: units of PS items kept in the shed this step (see the PS params)."""
    hold = {}
    day, hour = ctx['day'], ctx['hour']
    if not P['PS'] or day >= LAST_DAY or day < P['PS_START_DAY']: return hold
    shed = ctx['shed']; inv_now = ctx['inv']; pr = ctx['prices']
    op = S.setdefault('ps_open', {})
    for item in P['PS_ITEMS']:
        if op.get(item, (None,))[0] != day: op[item] = (day, pr.get(item, 0))
        q = shed.get(item, 0) - ctx['reserved'].get(item, 0) + ctx['dropping'].get(item, 0) - S.get('hold', {}).get(item, 0) - sqh.get(item, 0) - mth.get(item, 0)
        if q <= 0: continue
        h0, hend = ps_par(item, 'PS_H0'), ps_par(item, 'PS_H_END')
        if hour > hend: continue
        if hour < h0: hold[item] = q; continue
        left = hend - hour + 1
        ref = op[item][1]; inv = inv_now.get(item, 10000)
        if left > 1 and market_price(item, inv) < ps_par(item, 'PS_LO') * ref: hold[item] = q; continue
        n = -(-q // left)
        thr = ps_par(item, 'PS_HI') * ref
        while n < q and market_price(item, inv + n) >= thr: n += 1
        if q - n > 0: hold[item] = q - n
    return hold

# ---------------------------------------------------------------- market
def market_orders(ctx):
    day, hour = ctx['day'], ctx['hour']; plan = S['plan']; shed = ctx['shed']; pr = ctx['prices']
    orders = []
    res_w = max(0, plan['wheat_need'] - ctx['reserved_total'].get('WHEAT', 0)) + (P['WHEAT_BUFFER'] if day < LAST_DAY else 0)
    res_f = max(0, plan['fert_need'] - ctx['reserved_total'].get('FERTILIZER', 0)) + (P['FERT_KEEP_EXTRA'] if day < LAST_DAY else 0)
    sqh = sq_hold(ctx); S['sq_hold_now'] = sqh
    mth = mt_hold(ctx, sqh); S['mt_hold_now'] = mth
    psh = ps_hold(ctx, sqh, mth)
    rpos = S.get('ride_pos', {}) if P['RIDE'] else {}
    if P['RIDE']: ride_observe(ctx)
    def sellable():
        out = []
        for item in PRODUCTS:
            q = shed.get(item, 0) - ctx['reserved'].get(item, 0) + ctx['dropping'].get(item, 0)   # units act before the market
            q -= S.get('hold', {}).get(item, 0)
            q -= sqh.get(item, 0)
            q -= mth.get(item, 0)
            q -= psh.get(item, 0)
            if hour < P['RIDE_H1']: q -= rpos.get(item, 0)
            keep = 0
            if item == 'WHEAT' and P['WHEAT_KEEP'] > 0 and day < LAST_DAY:
                keep = max(0, min(P['WHEAT_KEEP'], P['WHEAT_KEEP_ROOM'] - sum(shed.values())))
            if item == 'WHEAT': q -= res_w + keep
            if item == 'FERTILIZER': q -= res_f
            # Opening days 1-5: fertilizer is sold one unit at a time in front of a seed buy, not as a lot.
            if item == 'FERTILIZER' and P['OPEN_RANK4'] and 1 <= day <= 5:
                need = S.get('plan', {}).get('seeds_needed', {}); seeds = ctx['priv']['seeds']
                if any(need.get(c, 0) > seeds.get(c, 0) for c in ('MELON', 'STRAWBERRY')): q = 0
            if q > 0: out.append((q * pr[item], item, q))
        out.sort(reverse=True); return out
    def wool_qty(item, q):
        """Cap a wool sell and hold the remainder until WOOL_LOT_GAP hours later. Off when WOOL_LOT is 0.
        WOOL_CRASH (0 = off) shortens a lot that opens above the floor so the tail is not walked through it.
        A morning that already opens under the floor sells as v12."""
        if item == 'WOOL' and P['WOOL_SKIP'] > 0 and day < LAST_DAY and pr['WOOL'] < P['WOOL_SKIP'] and sum(shed.values()) < P['WOOL_SKIP_SHED']:
            return 0
        if item == 'WOOL' and P['WOOL_CRASH'] > 0 and day < LAST_DAY and pr['WOOL'] >= P['WOOL_CRASH']:
            inv = ctx['inv'].get('WOOL', 10000); n = 0
            while n < q and market_price('WOOL', inv + n) >= P['WOOL_CRASH']: n += 1
            q = n
        if item != 'WOOL' or P['WOOL_LOT'] <= 0 or day >= LAST_DAY or q <= 0: return q
        if hour < S.get('wool_release', -1): return 0
        if q > P['WOOL_LOT']:
            S['wool_release'] = hour + P['WOOL_LOT_GAP']
            return P['WOOL_LOT']
        return q
    if hour == 0: S['wool_release'] = -1
    if (hour == 0 or ctx.get('replan')) and day < LAST_DAY:
        # sell the biggest lots first so the purchases below find shed room (orders execute in index order)
        if hour == 0:
            sl = sellable()
            if P['H0H']:
                need = max(0, res_w - shed.get('WHEAT', 0)) + max(0, res_f - shed.get('FERTILIZER', 0)) + sum(S.get('buy_today', {}).values())
                free = 100 - sum(shed.values()); sl = sorted(sl, key=lambda z: -z[2]); k = 0
                while k < len(sl) and free < need + 1: free += sl[k][2]; k += 1
                keep = [z for z in sl[k:] if z[1] in P['H0H_KEEP']]
                sl = sorted(sl[:k] + keep, reverse=True)
            for _, item, q in sl[:P['SELL0_MAX']]:
                q = wool_qty(item, q)
                if q > 0: orders.append(['SELL', item, q])
        # (circ12 LAND_H0: on the hour-1 re-plan the morning purchases are issued again for the re-planned additions)
        for a, n in S.get('buy_today', {}).items():
            if n > 0: orders.append(['BUY_ANIMAL', a, n])
        short = res_w - shed.get('WHEAT', 0)
        if short > 0 and pr['WHEAT'] > P['WHEAT_BUY_MAXP']:
            must = sum(1 for row in ctx['tiles'] for t in row if isinstance(t, dict) and t.get('animal') and not t.get('fed_today') and t.get('consecutive_unfed', 0) >= 1)
            short = max(0, must - shed.get('WHEAT', 0))
        if P['OPEN_RANK4'] and day == 0: short = 0   # the $3000 budget is animals and seeds; feed wheat comes from day-1 fertilizer
        if short > 0: orders.append(['BUY_PRODUCT', 'WHEAT', short])
        shortf = res_f - shed.get('FERTILIZER', 0)
        if shortf > 0 and pr['FERTILIZER'] <= P['FERT_BUY_MAXP']: orders.append(['BUY_PRODUCT', 'FERTILIZER', shortf])
    if P['LOAD_BUY'] and S.get('load_buy'):
        for k, n in S['load_buy'].items():
            if n > 0 and len(orders) < 10 and pr[k] <= (P['FERT_BUY_MAXP'] if k == 'FERTILIZER' else 999): orders.append(['BUY_PRODUCT', k, n])
        S['load_buy'] = {}
    if P['RIDE'] and hour == P['RIDE_H0'] and P['RIDE_FROM_DAY'] <= day < LAST_DAY - 1:
        S['ride_pos'] = {}
        cash = ctx['me']['money'] - P['RIDE_CASH']; room = P['OVERFLOW_TARGET'] - sum(shed.values()) - P['RIDE_ROOM']
        if P['DEBUG']: log(f"d{day} RIDE obs {S.get('ride_obs')} cash {cash:.0f} room {room}")
        for item in P['RIDE_ITEMS']:
            obs = S.get('ride_obs', {}).get(item, {})
            days = [obs[d] for d in range(day - P['RIDE_DAYS'], day) if d in obs]
            if len(days) < P['RIDE_DAYS']: continue
            net_buy = -sum(days) / len(days)
            if net_buy < P['RIDE_MIN_NET'].get(item, 1e9): continue
            n = int(min(P['RIDE_N'], room, cash // max(1, pr[item] + 0.2 * P['RIDE_N'])))
            if n <= 0 or len(orders) >= 10: continue
            orders.append(['BUY_PRODUCT', item, n]); S['ride_pos'][item] = n; cash -= n * (pr[item] + 0.1 * n); room -= n
            if P['DEBUG']: log(f"d{day} RIDE buy {item} {n} (opp net buy/day {net_buy:.0f}) price {pr[item]}")
    if hour >= P['RIDE_H1'] and S.get('ride_pos'): S['ride_pos'] = {}
    if P['LAND'] and (hour == 1 or (P['LAND_H0'] and hour == 0)) and day < LAST_DAY - 6 and S.get('land_today') != day:   # land-retry fix (robustness): retry on later days while the quadrant is still locked
        locked = sum(1 for row in ctx['tiles'] for t in row if t == 'LOCKED'); n_extra = (100 - locked) // 25 - 1
        if 0 <= n_extra < P['LAND_MAX_EXTRA']:
            price = [1000, 2000, 4000][n_extra]
            if ctx['me']['money'] >= price + P['LAND_RESERVE'] + 10 * len(plan.get('seeds_needed', {})):
                if hour == 0:
                    # circ12 LAND_H0: atomic order at index 0 (the cash is already in hand), the day is re-planned at hour 1 with the new tiles
                    orders.insert(0, ['BUY_LAND']); S['replan_step'] = ctx['step'] + 1
                else: orders.append(['BUY_LAND'])
                S['land_today'] = day
    want = plan['hires_wanted'] - S.get('hired_today', 0)
    if P['OPEN_RANK4'] and day <= 4:
        want = min(want, max(0, (4 if day == 0 else 6) - S.get('hired_today', 0)))
    if hour <= 2:
        for _ in range(max(0, want)):
            if len(orders) >= 10: break
            orders.append(['HIRE']); S['hired_today'] = S.get('hired_today', 0) + 1
    if hour >= P['SEED_HOUR'] and not plan.get('seeds_bought'):
        seeds = ctx['priv']['seeds']; ok = True
        for crop, n in plan['seeds_needed'].items():
            short = n - seeds.get(crop, 0)
            # Melon and strawberry seeds after day 0 are funded by the fertilizer pair below.
            if P['OPEN_RANK4'] and 1 <= day <= 5 and crop in ('MELON', 'STRAWBERRY'): continue
            if short > 0:
                if len(orders) < 10: orders.append(['BUY_SEED', crop, short])
                else: ok = False
        plan['seeds_bought'] = ok
    if P['OPEN_RANK4'] and 1 <= day <= 5 and hour >= 1 and S.get('open_pair_hour') != hour:
        seeds = ctx['priv']['seeds']; need = plan['seeds_needed']; crop = None
        for c in ('MELON', 'STRAWBERRY'):
            if need.get(c, 0) > seeds.get(c, 0): crop = c; break
        fert_q = shed.get('FERTILIZER', 0) - ctx['reserved'].get('FERTILIZER', 0)
        if crop and fert_q >= 1 and len(orders) <= 8:
            orders.append(['SELL', 'FERTILIZER', 1]); orders.append(['BUY_SEED', crop, 1])
            S['open_pair_hour'] = hour
    if hour >= max(1, P['SELL_FROM_HOUR']) or day == LAST_DAY:
        sells = []
        for _, item, q in sellable():
            if len(orders) + len(sells) >= 10: break
            q = wool_qty(item, q)
            if q > 0: sells.append(['SELL', item, q])
        # SQ: at an item's sell hour put the premium lots in front of the list (index 0 pairs with the opponent's first order)
        if P['SELLS_FIRST'] and sells:
            # lateexec SELLS_FIRST: every sell lot goes in front of the hires / seed / land orders (the lockstep pairs order index i
            # of both farms: a lot at index 0 is sold before an opponent lot of the same item at index >= 1)
            orders = sells + orders
        elif P['SQ'] and P['SQ_FRONT'] and day < LAST_DAY and any((S.get('sq_hour', {}).get(o[1], 0) == hour or S.get('sq_hour2', {}).get(o[1], -1) == hour) and hour > 0 for o in sells) and len(orders) + len(sells) <= 10:
            orders = sells + orders
        else:
            orders = orders + sells
    held = dict(sqh)
    for k, v in mth.items(): held[k] = held.get(k, 0) + v
    for k, v in psh.items(): held[k] = held.get(k, 0) + v
    if held and day < LAST_DAY:
        # shed room: the held units must leave room for this step's purchases and for produce about to be dropped
        # (at hour 23 every unit's inventory drops at day end; MT_CAP bounds the premium stock carried overnight)
        total = sum(shed.values()) - sum(ctx['reserved'].values()) + sum(ctx['dropping'].values()) + ctx.get('near_inv', 0)
        for o in orders:
            if o[0] == 'SELL': total -= min(o[2], shed.get(o[1], 0) + ctx['dropping'].get(o[1], 0))
            elif o[0] == 'BUY_PRODUCT': total += o[2]
            elif o[0] == 'BUY_ANIMAL': total += o[2]
        excess = total - (P['MT_SHED_MAX'] if mth else P['SQ_SHED_MAX'])
        if mth and hour == 23: excess = max(excess, sum(mth.values()) - S.get('mt_cap_today', P['MT_CAP']))
        if excess > 0:
            rel = []
            for item in sorted(held, key=lambda k: pr[k] / MP[k][0]):
                d = min(held[item], excess)
                if d > 0: rel.append(['SELL', item, d]); excess -= d
                if excess <= 0: break
            if rel:
                # before the purchases at hour 0, after HIRE/BUY_SEED otherwise (those must not be truncated)
                pos = 0 if hour == 0 else len([o for o in orders if o[0] in ('HIRE', 'BUY_SEED', 'BUY_LAND')])
                orders = orders[:pos] + rel + orders[pos:]
    if P['SQ'] and 'sq_prev' in S:
        ms = S['sq_prev']['my_sold']
        for o in orders[:10]:
            if o[0] == 'SELL' and (o[1] in P['SQ_ITEMS'] or (P['HOLD_OPP_GATE'] and o[1] in ('TOMATO', 'CARROT'))): ms[o[1]] = ms.get(o[1], 0) + min(o[2], shed.get(o[1], 0) + ctx['dropping'].get(o[1], 0))
    if day == LAST_DAY and hour == 22:
        orders = [o for o in orders if o[0] != 'HIRE']
        have = set()
        for o in orders:
            if o[0] == 'SELL': o[2] = 100000; have.add(o[1])
        for item in PRODUCTS:
            if item not in have and len(orders) < 10: orders.append(['SELL', item, 100000])
    if P['RIDE']:
        my = {}
        for o in orders[:10]:
            if o[0] == 'SELL' and o[1] in P['RIDE_ITEMS'] and len(o) > 2: my[o[1]] = my.get(o[1], 0) + min(int(o[2]) if o[2] < 100000 else shed.get(o[1], 0) + ctx['dropping'].get(o[1], 0), shed.get(o[1], 0) + ctx['dropping'].get(o[1], 0))
            elif o[0] == 'BUY_PRODUCT' and o[1] in P['RIDE_ITEMS'] and len(o) > 2: my[o[1]] = my.get(o[1], 0) - int(o[2])
        S['ride_prev'] = {'step': ctx['step'], 'inv': {i: ctx['inv'].get(i, 10000) for i in P['RIDE_ITEMS']}, 'shops': list(ctx.get('shops', ())), 'my': my}
    if P['MPC_SELL'] and ctx['step'] >= P['MPC_FROM'] and day < LAST_DAY:
        _mo = mpc_orders(ctx, orders[:10])   # latemarket
        if not P['MPC_PLACEBO']: orders = _mo   # placebo: the DP runs, its orders are discarded
    return orders[:10]

# ---------------------------------------------------------------- latemarket MPC_SELL (default off)
# Receding-horizon sell DP for MPC_ITEMS from MPC_FROM: every step, for each item, the units to sell now maximise the item's
# margin (our revenue - MPC_W x the opponent's revenue) over the next MPC_H steps on a forecast of the opponent's lots built
# only from observations: its units' positions and the tile-yield drops they cause (harvests credited to the unit standing on
# the tile), shed drops (a loaded unit staying on a shed-access tile, or day end), its sales seen as market-inventory moves,
# and the harvest->drop / drop->sale lags it has shown in this game.  Our own arrivals are forecast from our past arrivals by
# hour; units left at the horizon are valued at MPC_TV x the forecast prices there.  Shed room is kept (MPC_SHED_MAX).
MPC_SHED_TILES = ((4, 4), (5, 4), (4, 5), (5, 5))
MPC_PROD = {'COW': 'MILK', 'SHEEP': 'WOOL', 'GOOSE': 'EGG'}
MPC_PRIOR_DS = [0, 1, 1, 2, 4, 5, 8, 12, 20]
MPC_PRIOR_HD = [2, 4, 6, 8, 10, 14]
def _mq(lags, k=10):
    s = sorted(lags)
    if len(s) <= k: return s
    return [s[int((i + 0.5) * len(s) / k)] for i in range(k)]
def _mdist(q): return min(abs(q[0] - a) + abs(q[1] - b) for a, b in MPC_SHED_TILES)
def mpc_observe(ctx, obs):
    """per step: the opponent's sales at t-1 (market moves), its harvests / drops at t-1 (tiles, unit positions), our arrivals."""
    M = S.setdefault('mpc', {'items': {}, 'prev': None})
    step = ctx['step']; opp = 1 - obs['player']; fo = obs['farms'][opp]
    pos_cur = [tuple(fo['farmer'])] + [tuple(h) for h in fo.get('hands', [])]
    prev = M['prev']
    for item in P['MPC_ITEMS']:
        st = M['items'].setdefault(item, {'carried': {}, 'shed': [], 'ds': [], 'hd': [], 'osold': {}, 'arr': {}})
        if prev is None or prev['step'] != step - 1: continue
        s = step - 1
        # opponent sales at s: inventory move + town consumption - our sold (sales at the $1 floor are invisible)
        if prev['price'].get(item, 0) > 1:
            theirs = ctx['inv'].get(item, 10000) - prev['inv'].get(item, 10000) + sq_cons(prev['shops'], item, s) - prev['my'].get(item, 0)
        else: theirs = 0
        theirs = max(0, int(round(theirs)))
        if theirs: st['osold'][s] = theirs
        if s % 24 == 23:
            for u, lst in st['carried'].items():
                for tau in lst: st['shed'].append((s, tau))
            st['carried'] = {}
        else:
            ptiles = prev['tiles']; ctiles = fo['tiles']
            for y in range(10):
                for x in range(10):
                    a, b = ptiles[y][x], ctiles[y][x]
                    if not isinstance(a, dict): continue
                    ua = a.get('yield_units', 0) or 0
                    if ua <= 0: continue
                    prod = MPC_PROD.get(a['animal']) if a.get('animal') else (a.get('crop') if a.get('kind') == 'PLANT' else None)
                    if prod != item: continue
                    same = isinstance(b, dict) and b.get('animal') == a.get('animal') and b.get('crop') == a.get('crop')
                    ub = (b.get('yield_units', 0) or 0) if same else 0
                    if ub < ua:
                        st.setdefault('pq', []).extend([s] * (ua - ub))
                        who = [i for i, q in enumerate(pos_cur) if q == (x, y)]
                        st['carried'].setdefault(who[0] if who else -1, []).extend([s] * (ua - ub))
            pp = prev['pos']
            for i, q in enumerate(pos_cur):
                if q in MPC_SHED_TILES and i < len(pp) and pp[i] == q and st['carried'].get(i):
                    for tau in st['carried'][i]: st['shed'].append((s, tau)); st['hd'].append(s - tau)
                    st['carried'][i] = []
            if st['carried'].get(-1):
                for tau in st['carried'][-1]:
                    if s - tau >= 6: st['shed'].append((s, tau))
                st['carried'][-1] = [tau for tau in st['carried'][-1] if s - tau < 6]
        pq = st.setdefault('pq', []); pl = st.setdefault('pl', [])
        for _ in range(theirs):
            if pq: pl.append(s - pq.pop(0))
        st['pl'] = pl[-60:]
        for _ in range(theirs):
            if st['shed']:
                d, tau = st['shed'].pop(0); st['ds'].append(s - d)
            else:
                best = None
                for i, lst in st['carried'].items():
                    if lst and (best is None or lst[0] < st['carried'][best][0]): best = i
                if best is not None: st['carried'][best].pop(0)
        st['ds'] = st['ds'][-80:]; st['hd'] = st['hd'][-80:]
        if P['MPC_STALE']:
            # sales at the $1 floor are invisible: forget tracked units older than MPC_STALE steps so they cannot pile up
            lim = s - P['MPC_STALE']
            st['shed'] = [x for x in st['shed'] if x[1] >= lim]
            for i in list(st['carried']): st['carried'][i] = [tau for tau in st['carried'][i] if tau >= lim]
            st['pq'] = [tau for tau in st.get('pq', []) if tau >= lim]
    if P['MPC_FC'] in ('rl', 'ens3', 'ens2'): mpc_rl_step(obs)
    M['pos'] = pos_cur
MPC_RL_DIR = None
MPC_RL_B64 = ""
def _mpc_rl_load():
    """the rl agent's learned opponent-lot forecaster (numpy MLP): embedded blob (built main.py) or the rlfc/ snapshot next to this file"""
    import sys as _sys, importlib.util as _iu
    if MPC_RL_B64:
        import base64 as _b, zlib as _z, types as _t, io as _io
        import numpy as _np
        blob = json.loads(_z.decompress(_b.b64decode(MPC_RL_B64)).decode())
        for name in ('fc_feat', 'fc_model'):
            if name not in _sys.modules:
                mod = _t.ModuleType(name); exec(compile(blob[name], name, 'exec'), mod.__dict__); _sys.modules[name] = mod
        W = dict(_np.load(_io.BytesIO(_b.b64decode(blob['npz']))))
        return _sys.modules['fc_model'].Forecaster(W)
    d = MPC_RL_DIR or os.path.join(os.path.dirname(os.path.abspath(globals().get('__file__', 'x'))), 'rlfc')
    if d not in _sys.path: _sys.path.insert(0, d)
    import fc_model as _fm
    return _fm.Forecaster(os.path.join(d, 'fc_mlp.npz'))
def mpc_rl_step(obs):
    """feed the learned forecaster one observation per step (our sold / bought units of the previous step from mpc_after)"""
    M = S.setdefault('mpc', {'items': {}, 'prev': None})
    if M.get('rlfc') is None: M['rlfc'] = _mpc_rl_load()
    prev = M.get('prev') or {}
    ms = prev.get('my', {}) if prev.get('step') == obs['step'] - 1 else {}
    mb = prev.get('bought', {}) if prev.get('step') == obs['step'] - 1 else {}
    M['rl'] = M['rlfc'].step(obs, ms, mb); M['rl_step'] = obs['step']
def _mpc_rl_fc(t, H, item):
    M = S.get('mpc', {}); y = (M.get('rl') or {}).get(item) if M.get('rl_step') == t else None
    out = [0.0] * H
    if not y: return out
    for k, v in enumerate(y):
        for j in range(4):
            i = 4 * k + j
            if i < H: out[i] += max(0.0, v) / 4.0
    return out
def mpc_forecast(st, t, H, item=None):
    if P['MPC_FC'] == 'rl': return _mpc_rl_fc(t, H, item)
    if P['MPC_FC'] == 'ens2':
        # mean of the unit tracker and the learned forecast
        P['MPC_FC'] = 'track'
        try: a = mpc_forecast(st, t, H, item)
        finally: P['MPC_FC'] = 'ens2'
        c = _mpc_rl_fc(t, H, item)
        return [(x + y) / 2.0 for x, y in zip(a, c)]
    if P['MPC_FC'] == 'ens3':
        P['MPC_FC'] = 'ens'
        try: a = mpc_forecast(st, t, H, item)
        finally: P['MPC_FC'] = 'ens3'
        c = _mpc_rl_fc(t, H, item)
        return [(2.0 * x + y) / 3.0 for x, y in zip(a, c)]   # mean of pipeline, tracker and the learned forecast
    if P['MPC_FC'] == 'ens':
        # ensemble: mean of the harvest-pipeline and the unit-tracker forecasts
        P['MPC_FC'] = 'pipe'
        try: a = mpc_forecast(st, t, H)
        finally: P['MPC_FC'] = 'track'
        try: b = mpc_forecast(st, t, H)
        finally: P['MPC_FC'] = 'ens'
        return [(x + y) / 2.0 for x, y in zip(a, b)]
    if P['MPC_FC'] == 'pipe':
        # harvested-not-yet-sold units sold after the harvest->sale lags the opponent showed (age-conditioned), plus
        # MPC_FRESH x its hour profile of sales (units it will harvest inside the horizon)
        out = [0.0] * H; lags = st.get('pl', [])
        for tau in st.get('pq', []):
            age = t - tau
            if lags:
                cand = [l for l in lags if l >= age] or [age]
                w = 1.0 / len(cand)
                for l in cand:
                    i = tau + l - t
                    if 0 <= i < H: out[i] += w
            else:
                out[0 if t % 4 == 1 else min(H - 1, (1 - t) % 4)] += 1.0
        d = t // 24; prof = [0.0] * 24; wsum = 0.0; os_ = st['osold']
        for dd in range(max(0, d - 6), d):
            w = 0.5 ** (d - 1 - dd); wsum += w
            for hh in range(24): prof[hh] += w * os_.get(dd * 24 + hh, 0)
        if wsum: prof = [v / wsum for v in prof]
        return [out[i] + P['MPC_FRESH'] * prof[(t + i) % 24] for i in range(H)]
    ds = st['ds'] if len(st['ds']) >= 6 else MPC_PRIOR_DS
    hd = st['hd'] if len(st['hd']) >= 6 else MPC_PRIOR_HD
    out = [0.0] * H
    def spread(o, start, age, lags, w0=1.0):
        cand = _mq([l for l in lags if l >= age]) or [age]
        w = w0 / len(cand)
        for l in cand:
            i = start + l - t
            if 0 <= i < H: o[i] += w
    for d, tau in st['shed']: spread(out, d, t - d, ds)
    eod = (t // 24) * 24 + 24
    for i, lst in st['carried'].items():
        for tau in lst:
            cand = _mq([l for l in hd if l >= t - tau], 6) or [eod - tau]
            w = 1.0 / len(cand)
            for l in cand: spread(out, min(tau + l, eod), 0, ds, w)
    return out
def mpc_plan(item, inv0, t, q, shops, opf, ownf, H, W, J, TV, lastT):
    """units of item to sell at step t (DP over our units sold in the horizon; see ana/mpc.py plan, identical)."""
    cache = {}
    def PR(v):
        if v not in cache: cache[v] = market_price(item, v)
        return cache[v]
    Hs = min(H, lastT - t + 1)
    arr = [0] + [int(ownf[i]) for i in range(1, Hs)]
    cumarr = [0]
    for a in arr: cumarr.append(cumarr[-1] + a)
    Q = q + cumarr[Hs] + 1
    base = [0.0] * Hs; x = float(inv0)
    for i in range(Hs):
        base[i] = x; x += opf[i] - sq_cons(shops, item, t + i)
    endinv = x; INF = -1e18
    V = [0.0] * (Q + 1)
    if t + Hs - 1 < lastT:
        for s in range(Q + 1):
            rem = q + cumarr[Hs] - s
            V[s] = TV * sum(PR(int(round(endinv + s + k))) for k in range(max(0, rem))) if rem > 0 else 0.0
    else:
        for s in range(Q + 1):
            rem = q + cumarr[Hs] - s; V[s] = 0.0 if rem <= 0 else -1e9 * rem
    first = 0
    for i in range(Hs - 1, -1, -1):
        Vn = [INF] * (Q + 1); b = float(opf[i]); bi = int(b); bf = b - bi
        for s in range(Q + 1):
            stock = q + cumarr[i + 1] - s
            if stock < 0: continue
            v0 = int(round(base[i] + s)); ru = 0.0; bestv = INF; bj = 0
            for j in range(0, min(J, stock) + 1):
                if j > 0: ru += PR(int(round(v0 + (j - 1) + min(j - 1, b))))
                ro = 0.0
                if W:
                    for m in range(bi): ro += PR(v0 + m + min(m, j))
                    if bf > 0: ro += bf * PR(v0 + bi + min(bi, j))
                val = ru - W * ro + V[min(s + j, Q)]
                if val > bestv: bestv, bj = val, j
            Vn[s] = bestv
            if i == 0 and s == 0: first = bj
        V = Vn
    return first
_MPC_ORA = {}
def _mpc_oracle_arr(item):
    if 'arr' not in _MPC_ORA:
        _MPC_ORA['arr'] = None
        ep, seat = os.environ.get('LM_EP'), os.environ.get('LM_SEAT')
        f = f'/Users/1littlecoder/kaggriculture/research/claude/2900/agents/latemarket/out/aut_b1/{ep}_{seat}.json'
        if ep and os.path.exists(f):
            r = json.loads(open(f).read().strip().splitlines()[-1]); s = r['seat']; sold = {}
            for st, pl, it, u, rev in r['sales']:
                if pl == s: sold[(it, st)] = sold.get((it, st), 0) + u
            arr = {}
            for it in ('MILK', 'WOOL', 'STRAWBERRY'):
                prev_left = None; a = {}
                for st in range(264, 719):
                    avail = r['shed_mkt'].get(str(st), {}).get(it, 0)
                    if prev_left is not None: a[st] = max(0, avail - prev_left)
                    prev_left = avail - sold.get((it, st), 0)
                arr[it] = a
            _MPC_ORA['arr'] = arr
    return (_MPC_ORA['arr'] or {}).get(item)
def mpc_orders(ctx, orders):
    """replace the executor's sell lots of MPC_ITEMS by the DP's units; keeps shed room."""
    day, hour, t = ctx['day'], ctx['hour'], ctx['step']
    M = S.get('mpc')
    if not M: return orders
    shed = ctx['shed']; shops = list(ctx['shops'])
    decide = {}
    for item in P['MPC_ITEMS']:
        st = M['items'].get(item)
        if st is None: continue
        q = shed.get(item, 0) - ctx['reserved'].get(item, 0) + ctx['dropping'].get(item, 0)
        # own arrivals: units available now minus what was left after the previous step
        avail = q; last = st.get('left')
        if last is not None and st.get('lstep') == t - 1: st['arr'][t] = max(0, avail - last)
        if q <= 0: decide[item] = 0; continue
        if ctx['prices'].get(item, 0) < P['MPC_MINP']: continue   # floor market: the executor's own lot stands
        prof = [0.0] * 24; wsum = 0.0
        for dd in range(max(0, day - 6), day):
            w = P['MPC_DEC'] ** (day - 1 - dd); wsum += w
            for hh in range(24): prof[hh] += w * st['arr'].get(dd * 24 + hh, 0)
        if wsum: prof = [v / wsum for v in prof]
        H = P['MPC_H']
        ownf = [int(round(prof[(t + i) % 24])) if P['MPC_OWN'] else 0 for i in range(H)]
        if P['MPC_ORACLE_ARR']:
            # diagnostic only (never in a submission): our future arrivals read from the base lx3 replay of this game
            oa = _mpc_oracle_arr(item)
            if oa is not None: ownf = [0] + [oa.get(t + i, 0) for i in range(1, H)]
        opf = mpc_forecast(st, t, H, item)
        decide[item] = mpc_plan(item, ctx['inv'].get(item, 10000), t, q, shops, opf, ownf, H, P['MPC_W'], P['MPC_J'], P['MPC_TV'], LAST_DAY * 24 + 22)
    if not decide: return orders
    if P['MPC_NOHOLD']:
        # never hold more than the executor would: sell at least its own lot of the item this step (the DP may only sell earlier)
        for item in decide:
            q = shed.get(item, 0) - ctx['reserved'].get(item, 0) + ctx['dropping'].get(item, 0)
            bl = min(q, sum(o[2] for o in orders if o[0] == 'SELL' and o[1] == item))
            decide[item] = max(decide[item], bl)
    room_f = P['MPC_ROOM_LATE'] if (P['MPC_ROOM_LATE'] is not None and day >= P['MPC_ROOM_LATE_DAY']) else P['MPC_ROOM']
    if room_f < 1.0:
        # hold beyond the executor's own lots only inside MPC_ROOM x the shed room its orders leave (today's produce still to drop counted)
        bl = {}
        for item in decide:
            q = shed.get(item, 0) - ctx['reserved'].get(item, 0) + ctx['dropping'].get(item, 0)
            bl[item] = min(q, sum(o[2] for o in orders if o[0] == 'SELL' and o[1] == item))
        load = sum(shed.values()) - sum(ctx['reserved'].values()) + sum(ctx['dropping'].values())
        load += max(ctx.get('near_inv', 0), S['plan'].get('produce', 0) - S.get('dropped_today', 0) if ctx['hour'] < 23 else 0)
        for o in orders:
            if o[0] == 'SELL': load -= min(o[2], shed.get(o[1], 0) + ctx['dropping'].get(o[1], 0))
            elif o[0] in ('BUY_PRODUCT', 'BUY_ANIMAL'): load += o[2]
        allow = int(room_f * max(0, P['MPC_SHED_MAX'] - load))
        if P['MPC_ROOMMODE'] in ('plan', 'plan+'):
            # latemarket cheaper hold: hold beyond the executor's lots only inside the spare room its own day plan projects at h23
            # (OVERFLOW_TARGET - planned keep - loads of the routes that do not return), so holding never forces a return trip;
            # 'plan+': the whole free room on days the plan has no return-drop route at all
            pl = S.get('plan', {})
            spare = max(0, P['OVERFLOW_TARGET'] - pl.get('shed_keep', P['WHEAT_BUFFER']) - pl.get('nonret_load', 0))
            allow = min(int(spare), max(0, P['MPC_SHED_MAX'] - int(load)))
            if P['MPC_ROOMMODE'] == 'plan+' and pl.get('n_returns', 1) == 0: allow = max(0, P['MPC_SHED_MAX'] - int(load))
        extra = sum(max(0, bl[k] - decide[k]) for k in decide) - allow
        for item in sorted(decide, key=lambda k: ctx['prices'].get(k, 1) / MP[k][0]):
            if extra <= 0: break
            add = min(max(0, bl[item] - decide[item]), extra)
            decide[item] += add; extra -= add
    # shed room: total after this step's orders must stay under MPC_SHED_MAX (release the cheapest-ratio held units)
    new = [o for o in orders if not (o[0] == 'SELL' and o[1] in decide)]
    total = sum(shed.values()) - sum(ctx['reserved'].values()) + sum(ctx['dropping'].values()) + ctx.get('near_inv', 0)
    for o in new:
        if o[0] == 'SELL': total -= min(o[2], shed.get(o[1], 0) + ctx['dropping'].get(o[1], 0))
        elif o[0] in ('BUY_PRODUCT', 'BUY_ANIMAL'): total += o[2]
    for item, j in decide.items(): total -= j
    excess = total - P['MPC_SHED_MAX']
    if excess > 0:
        for item in sorted(decide, key=lambda k: ctx['prices'].get(k, 1) / MP[k][0]):
            q = shed.get(item, 0) - ctx['reserved'].get(item, 0) + ctx['dropping'].get(item, 0)
            add = min(q - decide[item], excess)
            if add > 0: decide[item] += add; excess -= add
            if excess <= 0: break
    sells = [['SELL', item, j] for item, j in sorted(decide.items(), key=lambda kv: -kv[1] * ctx['prices'].get(kv[0], 0)) if j > 0]
    for item in P['MPC_ITEMS']:
        st = M['items'].get(item)
        if st is not None:
            q = shed.get(item, 0) - ctx['reserved'].get(item, 0) + ctx['dropping'].get(item, 0)
            st['left'] = q - decide.get(item, 0); st['lstep'] = t
    # never truncate the executor's own orders (hires, seeds, buys): drop our smallest extra lots instead
    while len(sells) + len(new) > 10 and sells: sells.pop()
    if len(sells) + len(new) > 10: return orders
    out = sells + new
    if P['SQ'] and 'sq_prev' in S and not P['MPC_PLACEBO']:
        ms = S['sq_prev']['my_sold']
        for item, j in decide.items():
            if item in P['SQ_ITEMS']: ms[item] = min(j, shed.get(item, 0) + ctx['dropping'].get(item, 0))
    if P['DEBUG'] and t == 690: log(f"MPCOSOLD {json.dumps({k: v['osold'] for k, v in M['items'].items()})}")
    if P['DEBUG']: log(f"MPC d{day} h{hour} {decide} fc {[(k, round(sum(mpc_forecast(M['items'][k], t, 8, k)), 1)) for k in decide]}")
    return out
def mpc_after(ctx, obs, orders):
    """remember the market state and our actual sells (units our shed can cover) for the next step's inference."""
    M = S.setdefault('mpc', {'items': {}, 'prev': None})
    my = {}
    for o in orders[:10]:
        if o[0] == 'SELL':
            my[o[1]] = my.get(o[1], 0) + min(int(o[2]), max(0, ctx['shed'].get(o[1], 0) + ctx['dropping'].get(o[1], 0) - my.get(o[1], 0)))
    fo = obs['farms'][1 - obs['player']]
    bought = {}
    for o in orders[:10]:
        if o[0] == 'BUY_PRODUCT': bought[o[1]] = bought.get(o[1], 0) + int(o[2])
    M['prev'] = {'step': ctx['step'], 'inv': dict(ctx['inv']), 'price': dict(ctx['prices']), 'shops': list(ctx['shops']), 'my': my, 'bought': bought,
                 'tiles': [list(r) for r in fo['tiles']], 'pos': [tuple(fo['farmer'])] + [tuple(h) for h in fo.get('hands', [])]}

def ride_observe(ctx):
    """Attribute the market inventory change of the ride items since the previous step to the opponent (our own orders and the
    town consumption are known); accumulate their net sells (negative = net buys) per day over the ride window."""
    prev = S.get('ride_prev'); step = ctx['step']
    if not prev or prev['step'] != step - 1: return
    h = prev['step'] % 24; d = prev['step'] // 24
    if not (P['RIDE_H0'] <= h < P['RIDE_H1']): return
    for item in P['RIDE_ITEMS']:
        theirs = ctx['inv'].get(item, 10000) - prev['inv'][item] + sq_cons(prev['shops'], item, prev['step']) - prev['my'].get(item, 0)
        S.setdefault('ride_obs', {}).setdefault(item, {}); S['ride_obs'][item][d] = S['ride_obs'][item].get(d, 0) + theirs


# ---------------------------------------------------------------- allocation layer (world-aware additions)
def demand_scenarios(shops, day0, product, optimistic=False):
    """[(prob, demand array)] over the number j of remaining shop draws that list `product` (binomial), the j shops
    assigned to the earliest remaining unlock days; other future draws contribute nothing for this product."""
    n = LAST_DAY + 1 - day0
    base = [1.0 if product != 'FERTILIZER' else 0.0] * n
    for sh in shops:
        if product in SHOPS[sh]:
            m = 2 if len(SHOPS[sh]) == 1 else 1
            for t in range(n): base[t] += 6 * m
    unlocks = [u for u in ((12, 15, 18, 21, 24) if P['UNLOCK12'] else (15, 18, 21, 24)) if u > day0][:max(0, 8 - len(shops))]
    k = len(unlocks); types = [sh for sh in SHOPS if product in SHOPS[sh]]
    if k == 0 or not types: return [(1.0, base)]
    pprob = min(1.0, len(types) / 8.0 * P['BET_PPROB']); mult = 6 * (2 if all(len(SHOPS[sh]) == 1 for sh in types) else 1) * P['FUTURE_SHOP_W']
    if optimistic:
        arr = list(base)
        for t in range(unlocks[0] - day0, n): arr[t] += mult
        return [(1.0, arr)]
    out = []
    for j in range(k + 1):
        prob = math.comb(k, j) * pprob ** j * (1 - pprob) ** (k - j)
        arr = list(base)
        for i in range(j):
            for t in range(unlocks[i] - day0, n): arr[t] += mult
        out.append((prob, arr))
    return out

def demand_by_day(shops, day0):
    """Expected market consumption per product per day (index = day - day0) from known shops, expected future draws and the town."""
    n = LAST_DAY + 1 - day0
    D = {p: [1.0 if p != 'FERTILIZER' else 0.0] * n for p in PRODUCTS}
    for sh in shops:
        m = 2 if len(SHOPS[sh]) == 1 else 1
        for p in SHOPS[sh]:
            for t in range(n): D[p][t] += 6 * m
    exp = {p: 0.0 for p in PRODUCTS}
    for sh, prods in SHOPS.items():
        m = 2 if len(prods) == 1 else 1
        for p in prods: exp[p] += 6 * m / 8.0
    for unlock in ((12, 15, 18, 21, 24) if P['UNLOCK12'] else (15, 18, 21, 24)):
        if unlock > day0 and len(shops) < 8:
            for p in PRODUCTS:
                for t in range(unlock - day0, n): D[p][t] += P['FUTURE_SHOP_W'] * exp[p]
    return D

def _lock_rev(product, u, v, inv):
    """Revenue for `u` units. The engine quotes both players on the same inventory, then commits both.
    INTERLEAVE off keeps the old path, where our whole lot sells before theirs."""
    only = P['INTERLEAVE_ONLY']
    use = P['INTERLEAVE'] and (not only or product in only)
    if u <= 0: return 0.0
    if not use or v <= 0: return u * market_price(product, inv + u / 2.0)
    shared = min(u, v); extra = u - shared
    rev = shared * market_price(product, inv + shared)
    if extra > 0: rev += extra * market_price(product, inv + 2 * shared + extra / 2.0)
    return rev

def proj_revenue(product, inv0, me, opp, demand):
    """My revenue along the inventory path. INTERLEAVE prices a same-day opponent lot in the same step."""
    inv = inv0; rev = 0.0
    for t in range(len(me)):
        u = me[t]; v = opp[t]
        rev += _lock_rev(product, u, v, inv)
        inv += u + v - demand[t]
    return rev

def proj_margin(product, inv0, me, opp, demand, w=None):
    """My revenue minus OPP_W x the opponent's revenue along the same inventory path."""
    if w is None: w = P['OPP_W']
    if product == 'TOMATO' and P['TOM_OPP_MARGIN']: w = max(w, P['TOM_OPP_MARGIN'])
    inv = inv0; rev = 0.0; orev = 0.0
    for t in range(len(me)):
        u = me[t]; v = opp[t]
        only = P['INTERLEAVE_ONLY']
        use = P['INTERLEAVE'] and (not only or product in only)
        rev += _lock_rev(product, u, v, inv)
        if w: orev += _lock_rev(product, v, u if use else 0.0, inv + (0 if use else u))
        inv += u + v - demand[t]
    return rev - w * orev

def addition_schedule(kind, d0, day0):
    """Units sold per day (index day-day0) for one addition made on day d0; None if it cannot pay before the end."""
    n = LAST_DAY + 1 - day0; sched = [0.0] * n; product = None
    # Ongoing crops are harvested the day yield appears and sold the next morning. The old calendar
    # booked the harvest day. Animals were already on the sale morning. CROP_LAG 1 lines crops up.
    lag = int(P['CROP_LAG']) if kind in ('STRAWBERRY', 'TOMATO', 'CARROT') else 0
    def put(day, u):
        day += lag
        if day <= LAST_DAY: sched[day - day0] += u
    if kind == 'STRAWBERRY':
        product = 'STRAWBERRY'
        for a in (9, 11, 13, 15): put(d0 + a + 1, 2)
    elif kind == 'TOMATO':
        product = 'TOMATO'
        for a in (7, 8, 9, 10): put(min(LAST_DAY, d0 + a + 1) if (P['TOM_SCHED_END'] and P['TOM_HOLD']) else d0 + a + 1, 2)
    elif kind == 'MELON':
        product = 'MELON'; put(d0 + (11 if P['MELON_EARLY'] else 13), 6)
    elif kind == 'CARROT':
        product = 'CARROT'; d = d0 + 3
        while d + 1 <= LAST_DAY: put(d + 1, 4); d += 3
    elif kind == 'SHEEP':
        product = 'WOOL'; put(d0 + 7, 6)
        for k in range(1, 8): put(d0 + 7 + 3 * k, 4)
    elif kind == 'COW':
        product = 'MILK'; put(d0 + 9, 6)
        for k in range(1, 12): put(d0 + 9 + 2 * k, 3)
    elif kind == 'GOOSE':
        product = 'EGG'; put(d0 + 5, 4)
        for k in range(1, 30): put(d0 + 5 + k, 2)
    if sum(sched) <= 0: return None, None
    return product, sched

def addition_cost(kind, d0, pr):
    days = LAST_DAY - d0
    if kind == 'STRAWBERRY': return 100 + 2 * pr['FERTILIZER'] + 37 * P['LABOUR_COST']
    if kind == 'TOMATO': return 50 + 2 * pr['FERTILIZER'] + 35 * P['LABOUR_COST']
    if kind == 'MELON': return 80 + 0.5 * pr['FERTILIZER'] + P['MELON_LABOUR'] * P['LABOUR_COST']
    if kind == 'CARROT':
        cycles = max(1, days // 3)
        return cycles * (20 + 0.7 * pr['FERTILIZER']) + days * 2.5 * P['LABOUR_COST']
    feed = days * pr['WHEAT']; labour = days * 4.2 * P['LABOUR_COST']; fert = -days * 0.5 * pr['FERTILIZER']
    return {'SHEEP': 500, 'COW': 400, 'GOOSE': 300}[kind] + 1 * P['LABOUR_COST'] + feed + labour + fert

def farm_supply(tiles, day0, wheat_rate, fert_ongoing=True, carrot_rate=0.0):
    """Projected units sold per product per day (index day-day0) from a farm's current tiles (steady cadence, daily care)."""
    n = LAST_DAY + 1 - day0
    out = {p: [0.0] * n for p in PRODUCTS}
    lag = int(P['CROP_LAG'])
    def put(p, day, u):
        if day0 <= day <= LAST_DAY: out[p][day - day0] += u
    for y, row in enumerate(tiles):
        for x, t in enumerate(row):
            if not isinstance(t, dict): continue
            if 'animal' in t:
                a = ANIMALS[t['animal']]; prod = a['product']
                bonus = {'COW': 2, 'SHEEP': 3, 'GOOSE': 1}[t['animal']]
                first = t['placed_day'] + a['first']
                d = first
                while d <= LAST_DAY - 1:
                    if d >= day0 - 1:
                        u = 1 + (min(t.get('pending_care_bonus', 0) + max(0, d - day0), 5) if d == first and first >= day0 else bonus)
                        put(prod, d + 1, min(a['max_held'], u))
                    d += a['interval']
                put('FERTILIZER', day0 + 1, 0)   # fertilizer ignored in the projection (no consumer)
            elif t.get('kind') == 'PLANT':
                crop = t['crop']; cd = CROPS[crop]
                if cd['ongoing']:
                    for k in range(cd['max_yield']):
                        age = cd['first'] - 1 + k * cd['interval']; d = t['planted_day'] + age
                        if d >= day0 - 1:
                            sale = LAST_DAY if (crop == 'TOMATO' and P['TOM_SCHED_END'] and P['TOM_HOLD'] and d + 1 <= LAST_DAY) else d + 1 + lag
                            put(crop, sale, 2 if fert_ongoing else 1)
                elif crop == 'WHEAT':
                    for d in range(day0, LAST_DAY + 1): put('WHEAT', d, wheat_rate)
                elif crop == 'CARROT' and carrot_rate:
                    for d in range(day0, LAST_DAY + 1): put('CARROT', d, carrot_rate)
                else:
                    put(crop, t['planted_day'] + cd['maxday'] + 1 + lag, cd['max_yield'] - 1)
    return out

def carrot_demand(shops, day):
    """Expected carrot consumption per day: town 1 + 12 per Pet Cafe known (+ CARROT_FUTURE x expected future Pet Cafe draws).
    CARROT_FARMERS adds that much daily demand per Farmers Market. 0 leaves the pet-cafe rule unchanged."""
    n_pet = sum(1 for sh in shops if sh == 'PET_CAFE')
    n_farm = sum(1 for sh in shops if sh == 'FARMERS_MARKET')
    draws = sum(1 for u in (15, 18, 21, 24) if u > day) if len(shops) < 8 else 0
    dem = 1 + 12 * n_pet + P['CARROT_FUTURE'] * draws * 12 / 8.0 + P['CARROT_FARMERS'] * n_farm
    gate = n_pet if P['CARROT_FARMERS'] <= 0 else n_pet + n_farm
    return dem, gate

def carrot_want(ctx, obs, shops):
    """Target size of the carrot block: (demand - opponent's visible carrot supply) / our rate, 0 when fewer than CARROT_MIN_PET
    Pet Cafes are known or the market sits CARROT_OVER units above I0."""
    day = ctx['day']; inv = ctx['inv']['CARROT'] - 10000
    demand, n_pet = carrot_demand(shops, day)
    opp_tiles = obs['farms'][1 - obs['player']]['tiles']
    opp_car = sum(1 for row in opp_tiles for t in row if isinstance(t, dict) and t.get('crop') == 'CARROT')
    opp_sup = P['CARROT_OPP_W'] * P['CARROT_OPP_RATE'] * opp_car
    rate = max(0.0, demand - opp_sup) * P['CARROT_FILL']
    want = int(round(rate / P['CARROT_RATE']))
    if n_pet < P['CARROT_MIN_PET'] or inv > P['CARROT_OVER']: want = 0
    first_cafe = next((3 * (i + 1) for i, sh in enumerate(shops) if sh == 'PET_CAFE'), None)
    if P['CARROT_OPP_TRIG'] > 0:
        # CARROT_PET_FREE plants for a Pet Cafe that opens on day 18 or later without waiting for the
        # opponent's tiles. A day-15 cafe still waits: planting then cut the close win's later carrot wave.
        soon = P['CARROT_PET_OPEN'] > 0 and first_cafe is not None and first_cafe <= P['CARROT_PET_OPEN']
        if soon and P['CARROT_PET_OPEN_MAX'] > 0: want = min(want, int(P['CARROT_PET_OPEN_MAX']))
        if not ((P['CARROT_PET_FREE'] and first_cafe is not None and first_cafe >= 18) or soon):
            if opp_car >= P['CARROT_OPP_TRIG'] and day <= P['CARROT_TRIG_LAST_DAY']: S['carrot_fight'] = day
            if not S.get('carrot_fight'): want = 0
    early_on = P['CARROT_PET_EARLY'] > 0 and first_cafe == 15 and 15 <= day <= 18 and not S.get('carrot_fight')
    S['carrot_early_on'] = early_on
    if early_on:
        early = int(round(rate / P['CARROT_RATE'])) if n_pet >= P['CARROT_MIN_PET'] and inv <= P['CARROT_OVER'] else 0
        want = max(want, min(int(P['CARROT_PET_EARLY']), early))
    want = min(want, P['CARROT_MAX'] + (S.get('carrot_early', 0) if early_on else 0))
    return want, (n_pet, opp_car, inv, round(demand, 1))

def carrot_late_quota(ctx, obs):
    """Tiles that may be swapped to carrots today under the LATE rule: market room over the rest of the game divided by the
    units one late tile yields (CARROT_LATE_UNITS); room = deficit + demand x days left - both farms' carrot tiles x rate x days."""
    day = ctx['day']; tiles = ctx['tiles']; shops = list(obs['town']['unlocked_shops'])
    inv = ctx['inv']['CARROT'] - 10000; days = max(0, LAST_DAY - day)
    demand, _ = carrot_demand(shops, day)
    my_car = sum(1 for row in tiles for t in row if isinstance(t, dict) and t.get('crop') == 'CARROT')
    opp_car = sum(1 for row in obs['farms'][1 - obs['player']]['tiles'] for t in row if isinstance(t, dict) and t.get('crop') == 'CARROT')
    shed_car = ctx['shed'].get('CARROT', 0)
    room = -inv - shed_car + demand * days - (my_car * P['CARROT_RATE'] + opp_car * P['CARROT_OPP_RATE']) * days
    return max(0, int(room / P['CARROT_LATE_UNITS']))

def allocate(ctx, obs):
    """Greedy: add the single best-paying tile conversion / animal purchase while it beats the wheat alternative."""
    day = ctx['day']; pr = ctx['prices']; tiles = ctx['tiles']; me = ctx['me']
    shops = list(obs['town']['unlocked_shops']); inv_now = obs['market']['inventory']
    S.setdefault('target', {}); S.setdefault('alloc_count', {})
    if P['STRAW_RETIRE_P'] > 0 and day >= P['STRAW_RETIRE_DAY'] and pr['STRAWBERRY'] < P['STRAW_RETIRE_P']:
        for y in range(10):
            for x in range(10):
                t = tiles[y][x]
                if isinstance(t, dict) and t.get('crop') == 'STRAWBERRY':
                    S['target'][(x, y)] = 'FILLER'
    if P['STRAW_LATE_SHOPS'] > 0 and day >= P['STRAW_LATE_DAY'] and sum(1 for sh in shops if 'STRAWBERRY' in SHOPS[sh]) < P['STRAW_LATE_SHOPS']:
        first = CROPS['STRAWBERRY']['first']
        for y in range(10):
            for x in range(10):
                t = tiles[y][x]
                if isinstance(t, dict) and t.get('crop') == 'STRAWBERRY' and day - t.get('planted_day', day) < first:
                    S['target'][(x, y)] = 'FILLER'
    if not ctx.get('replan'): S['alloc_added'] = {}     # re-derived: additions already on the farm are in the farm projection; only today's are added below
    else: S.setdefault('alloc_added', {})               # circ12 LAND_H0 re-plan: this morning's additions (animals still in the shed) stay in the projection
    D = demand_by_day(shops, day); n = LAST_DAY + 1 - day
    scen = {p: demand_scenarios(shops, day, p) for p in PRODUCTS}
    scen_opt = {p: demand_scenarios(shops, day, p, optimistic=True) for p in PRODUCTS} if P['BET_W'] > 0 else scen
    n_known = {p: sum(1 for sh in shops if p in SHOPS[sh]) for p in PRODUCTS}
    sup_me = farm_supply(tiles, day, 1.4, True, P['CARROT_RATE']); sup_opp = farm_supply(obs['farms'][1 - obs['player']]['tiles'], day, 1.0, True, P['CARROT_OPP_RATE'] * P['CARROT_OPP_W'])
    def base_me(product):
        arr = list(sup_me[product])
        for d, u in S['alloc_added'].get(product, {}).items():
            if d >= day: arr[d - day] += u
        # committed structures not yet visible (bought today) are in alloc_added; animals already placed are in sup_me
        return arr
    def base_opp(product): return [P['OPP_SCALE'] * (P['TOM_OPP_SUP'] if product == 'TOMATO' else 1.0) * u for u in sup_opp[product]]
    # convertible tiles: wheat tiles (beyond the floor) and empty tiles; nearest to the shed for structures, farthest for crops
    wheat_tiles = [(x, y) for y in range(10) for x in range(10) if isinstance(tiles[y][x], dict) and tiles[y][x].get('crop') == 'WHEAT' and (x, y) not in S['target']]
    empty_tiles = [(x, y) for y in range(10) for x in range(10) if tiles[y][x] is None and (x, y) not in S['target']]
    n_wheat_total = len(wheat_tiles) + sum(1 for v in S['target'].values() if v == 'WHEAT')
    pool = sorted(empty_tiles + wheat_tiles, key=lambda q: dist(q, nearest_shed(q)))
    convertible = max(0, len(empty_tiles) + max(0, len(wheat_tiles) - P['WHEAT_MIN_TILES']))
    cash = float(me['money']) - P['CASH_RESERVE'] - 400.0
    alt_per_day = 1.4 * pr['WHEAT'] - 0.25 * pr['FERTILIZER'] - 2.7 * P['LABOUR_COST']
    if P['ALT_PROJ']:
        # wheat price along the projected path: both farms' wheat tiles (1.4 / 1.0 units per tile-day) against the known wheat
        # shops' demand (+ expected future draws); the alternative tile sells 1.4 units each remaining day
        inv = inv_now['WHEAT']; mw = sup_me['WHEAT']; ow = sup_opp['WHEAT']; dw = D['WHEAT']; tot = 0.0
        for t in range(n):
            tot += market_price('WHEAT', inv + mw[t] / 2.0); inv += mw[t] + ow[t] - dw[t]
        p_proj = tot / max(1, n)
        p_alt = P['ALT_PROJ_W'] * p_proj + (1 - P['ALT_PROJ_W']) * pr['WHEAT']
        alt_per_day = 1.4 * p_alt - 0.25 * pr['FERTILIZER'] - 2.7 * P['LABOUR_COST']
        S['alt_proj'] = (round(p_proj, 1), pr['WHEAT'])
    if P['ALT_MULT'] != 1.0 and sum(1 for sh in shops if 'WHEAT' in SHOPS[sh]) >= P['ALT_MULT_SHOPS']: alt_per_day *= P['ALT_MULT']
    added = []; nets = {}
    # strawberry sizing: dig the youngest strawberry tiles while their projected output does not beat the wheat alternative
    if P['CUT'] and day <= P['CUT_LAST_DAY']:
        straw = sorted([(x, y) for y in range(10) for x in range(10) if isinstance(tiles[y][x], dict) and tiles[y][x].get('crop') == 'STRAWBERRY'
                        and (x, y) not in S['target'] and day - tiles[y][x]['planted_day'] <= P['CUT_MAX_AGE']], key=lambda q: -tiles[q[1]][q[0]]['planted_day'])
        ncut = 0
        for pos in straw:
            if S['alloc_count'].get('CUT', 0) >= P['CUT_MAX']: break
            t = tiles[pos[1]][pos[0]]; sched = [0.0] * n; nrem = 0
            for k in range(4):
                d = t['planted_day'] + 9 + 2 * k
                if d >= day and d + 1 <= LAST_DAY: sched[d + 1 - day] += 2; nrem += 1
            if nrem == 0: continue
            m = base_me('STRAWBERRY'); o = base_opp('STRAWBERRY'); loss = 0.0
            for prob, dem in scen['STRAWBERRY']:
                loss += prob * (proj_margin('STRAWBERRY', inv_now['STRAWBERRY'], m, o, dem) - proj_margin('STRAWBERRY', inv_now['STRAWBERRY'], [max(0.0, a - b) for a, b in zip(m, sched)], o, dem))
            saved = nrem / 4.0 * (2 * pr['FERTILIZER'] + 37 * P['LABOUR_COST'])
            net = alt_per_day * (LAST_DAY - day - 1) + saved - loss - 2 * P['LABOUR_COST'] - 10
            nets['CUT'] = round(net)
            if net <= P['CUT_MARGIN']: break
            S['target'][pos] = 'FILLER'; S['alloc_count']['CUT'] = S['alloc_count'].get('CUT', 0) + 1; ncut += 1
            S['alloc_added'].setdefault('STRAWBERRY', {})
            for tt, u in enumerate(sched):
                if u: S['alloc_added']['STRAWBERRY'][day + tt] = S['alloc_added']['STRAWBERRY'].get(day + tt, 0) - u
            added.append(('CUT', pos, round(net), round(-loss), round(saved)))
    # Take tomato tiles before strawberries fill the new quadrant. Off leaves v12.
    if P['TOM_EARLY'] and P['TOM_RULE'] and P['TOM_IF_NONE'] and day + CROPS['TOMATO']['first'] <= LAST_DAY - 1:
        have_tom = sum(1 for row in tiles for t in row if isinstance(t, dict) and t.get('crop') == 'TOMATO')
        have_tom += sum(1 for v in S['target'].values() if v == 'TOMATO')
        tom_days = {int(k): v for k, v in P['TOM_DAYS'].items()}
        n_t = sum(1 for sh in shops if sh == 'PIZZA_SHOP') if P['TOM_PIZZA'] else sum(1 for sh in shops if 'TOMATO' in SHOPS[sh])
        if have_tom == 0 and day in tom_days and n_t >= P['TOM_MIN_SHOPS']:
            dem_known = sum(1.0 + 6.0 * n_t for _ in range(n))
            dem_future = sum(D['TOMATO']) - dem_known
            opp_w = P['TOM_OPP_W'] if P['TOM_NONE_OPP'] is None else P['TOM_NONE_OPP']
            deficit_end = (10000 - inv_now['TOMATO']) + dem_known + P['TOM_FUTURE_W'] * dem_future - sum(base_me('TOMATO')) - opp_w * sum(base_opp('TOMATO'))
            want = int((deficit_end - P['TOM_TARGET']) / 8.0 * tom_days[day])
            want = max(0, min(want, P['TOM_MAX'], convertible, len(pool)))
            if want >= P['TOM_MIN_TILES'] and cash >= 50 * want:
                for _ in range(want):
                    pos = pool.pop(); S['target'][pos] = 'TOMATO'; convertible -= 1; cash -= 50
                    S['alloc_count']['TOM_RULE'] = S['alloc_count'].get('TOM_RULE', 0) + 1
                    product, sched = addition_schedule('TOMATO', day, day)
                    for t, u in enumerate(sched):
                        if u: S['alloc_added'].setdefault(product, {}); S['alloc_added'][product][day + t] = S['alloc_added'][product].get(day + t, 0) + u
                added.append(('TOM_EARLY', want, round(deficit_end), n_t))
    if P['STRAW_RULE'] and day <= P['STRAW_RULE_LAST_DAY'] and day + CROPS['STRAWBERRY']['first'] <= LAST_DAY - 1:
        # top teams' strawberry sizing (13 + 8.5 per strawberry-buying shop known): top up the tape's tiles on the farthest free tiles
        if P['STRAW_HAVE_FIX']:
            # circ12: a target already planted with strawberries is on the farm; do not count it twice (v11 under-plants from day 13)
            have = sum(1 for row in tiles for t in row if isinstance(t, dict) and t.get('crop') == 'STRAWBERRY') + sum(
                1 for q, v in S['target'].items() if v == 'STRAWBERRY' and not (isinstance(tiles[q[1]][q[0]], dict) and tiles[q[1]][q[0]].get('crop') == 'STRAWBERRY'))
        else:
            have = sum(1 for row in tiles for t in row if isinstance(t, dict) and t.get('crop') == 'STRAWBERRY') + sum(1 for v in S['target'].values() if v == 'STRAWBERRY')
        n_s = sum(1 for sh in shops if 'STRAWBERRY' in SHOPS[sh])
        n_eff = n_s
        ab = (13.0, 8.5) if P['STRAW_AB_NOYARN'] and any(sh == 'YARN_STORE' for sh in shops) else P['STRAW_AB']
        if P['STRAW_FUTURE_W'] and n_s <= P['STRAW_FUTURE_MAX_KNOWN'] and day < 24:
            # Four of eight shop types buy strawberries. The new quadrant is planted this morning, and a top-up
            # after day 13 harvests too late to beat the wheat it replaces.
            n_eff = n_s + P['STRAW_FUTURE_W'] * max(0, 8 - len(shops)) * 0.5
        opp_s = sum(1 for row in obs['farms'][1 - obs['player']]['tiles'] for t in row if isinstance(t, dict) and t.get('crop') == 'STRAWBERRY')
        want = int(round(ab[0] + ab[1] * n_eff - P['STRAW_OPP_W'] * (opp_s - P['STRAW_OPP_REF'])))
        if P['STRAW_FLOOR']: want = max(want, int(P['STRAW_FLOOR']))
        if P['STRAW_CAP'] > 0 and n_s < P['STRAW_CAP_SHOPS']: want = min(want, int(P['STRAW_CAP']))
        k = 0
        while have < want and pool and convertible > 0 and k < P['STRAW_ADD_MAX'] and S['alloc_count'].get('STRAWBERRY', 0) < P['ALLOC_MAX']['STRAWBERRY']:
            if _LOG or P['STRAW_NET'] is not None:
                product, sched = addition_schedule('STRAWBERRY', day, day)
                sn = None
                if sched is not None:
                    cost = addition_cost('STRAWBERRY', day, pr)
                    m = base_me(product); o = base_opp(product); gain = 0.0
                    w = P['OPP_W'] if P['OPP_W_LEAD'] > 0 and sum(o) > P['OPP_W_LEAD'] * sum(m) else (0.0 if P['OPP_W_LEAD'] > 0 else None)
                    for prob, dem in scen[product]:
                        gain += prob * (proj_margin(product, inv_now[product], [a + b for a, b in zip(m, sched)], o, dem, w) - proj_margin(product, inv_now[product], m, o, dem, w))
                    sn = gain - cost - alt_per_day * (LAST_DAY - day)
                if _LOG: log(f"d{day} STRAW_NET k {k} have {have} want {want} net {None if sn is None else round(sn)}")
                yarn_ok = (not P['STRAW_NET_YARN']) or any(sh == 'YARN_STORE' for sh in shops)
                if P['STRAW_NET'] is not None and yarn_ok and (sn is None or sn <= P['STRAW_NET']): break
            if P['STRAW_EMPTY_ONLY']:
                empties = [q for q in pool if tiles[q[1]][q[0]] is None]
                if not empties: break
                pos = empties[0] if P['STRAW_NEAR'] else empties[-1]
                pool.remove(pos)
            else:
                pos = pool.pop(0) if P['STRAW_NEAR'] else pool.pop()
            S['target'][pos] = 'STRAWBERRY'; have += 1; k += 1; convertible -= 1
            S['alloc_count']['STRAWBERRY'] = S['alloc_count'].get('STRAWBERRY', 0) + 1
            product, sched = addition_schedule('STRAWBERRY', day, day)
            for t, u in enumerate(sched):
                if u: S['alloc_added'].setdefault(product, {}); S['alloc_added'][product][day + t] = S['alloc_added'][product].get(day + t, 0) + u
            added.append(('STRAW_RULE', pos, want, n_s))
    cow_day_max = P['HERD_COW_DAY'] if P['HERD_COW_DAY'] is not None else P['HERD_DAY_MAX']
    catchup = P['HERD_SHEEP_CATCHUP'] and P['HERD_DAY_MAX'] < day <= 16
    if P['HERD_RULE'] and (day <= max(P['HERD_DAY_MAX'], cow_day_max) or catchup):
        # top teams' linear herd rules: sheep = a + b x Yarn stores, cows = a + b x milk shops (known now); buy the shortfall
        herd = {a: 0 for a in ANIMALS}
        for row in tiles:
            for t in row:
                if isinstance(t, dict) and 'animal' in t: herd[t['animal']] += 1
        for a in ANIMALS: herd[a] += ctx['shed_animals'].get(a, 0)
        n_yarn = sum(1 for sh in shops if sh == 'YARN_STORE'); n_milk = sum(1 for sh in shops if 'MILK' in SHOPS[sh])
        want = {'SHEEP': int(round(P['HERD_SHEEP'][0] + P['HERD_SHEEP'][1] * n_yarn)), 'COW': int(round(P['HERD_COW'][0] + P['HERD_COW'][1] * n_milk))}
        if n_yarn == 1 and P['HERD_SHEEP_Y1'] is not None: want['SHEEP'] = int(P['HERD_SHEEP_Y1'])
        if P['HERD_SHEEP_CATCHUP'] and day > P['HERD_DAY_MAX'] and n_yarn >= 1:
            cap = int(P['HERD_SHEEP_Y1']) if P['HERD_SHEEP_Y1'] is not None else 8
            want['SHEEP'] = min(want['SHEEP'], cap)
        if n_yarn < P['HERD_MIN_KNOWN']: want['SHEEP'] = 0
        if n_yarn == 0 and P['HERD_SHEEP_BASE'] > 0: want['SHEEP'] = max(want['SHEEP'], int(P['HERD_SHEEP_BASE']))
        if n_milk < P['HERD_MIN_KNOWN']: want['COW'] = 0
        if P['HERD_LEAD'] > 0:
            oherd = {a: 0 for a in ANIMALS}
            for row in obs['farms'][1 - obs['player']]['tiles']:
                for t in row:
                    if isinstance(t, dict) and 'animal' in t: oherd[t['animal']] += 1
            for kind in ('SHEEP', 'COW'):
                if oherd[kind] <= P['HERD_LEAD'] * herd[kind]: want[kind] = 0
            S['herd_lead'] = (dict(herd), oherd)
        for kind in ('SHEEP', 'COW'):
            if kind == 'SHEEP' and day > P['HERD_DAY_MAX'] and not (P['HERD_SHEEP_CATCHUP'] and n_yarn >= 1): continue
            if kind == 'COW' and day > cow_day_max: continue
            price = {'SHEEP': 500, 'COW': 400}[kind]
            while herd[kind] < want[kind] and pool and price <= cash and S['alloc_count'].get(kind, 0) < P['ALLOC_MAX'][kind]:
                floor = kind == 'COW' and P['HERD_COW_FLOOR'] > 0 and convertible <= 0 and S['alloc_count'].get('COW_FLOOR', 0) < P['HERD_COW_FLOOR']
                if convertible <= 0 and not floor: break
                pos = pool.pop(0); S['target'][pos] = ANIMALS[kind]['structure'] + ':' + kind
                S['buy_today'][kind] = S['buy_today'].get(kind, 0) + 1; cash -= price; herd[kind] += 1
                if floor: S['alloc_count']['COW_FLOOR'] = S['alloc_count'].get('COW_FLOOR', 0) + 1
                else: convertible -= 1
                S['alloc_count'][kind] = S['alloc_count'].get(kind, 0) + 1
                product, sched = addition_schedule(kind, day, day)
                for t, u in enumerate(sched):
                    if u: S['alloc_added'].setdefault(product, {}); S['alloc_added'][product][day + t] = S['alloc_added'][product].get(day + t, 0) + u
                added.append((kind + '_RULE', pos, want[kind], n_yarn, n_milk))
    if P['CARROT_BLOCK'] and day >= P['CARROT_FIRST_DAY']:
        want, info = carrot_want(ctx, obs, shops)
        have_tiles = [(x, y) for y in range(10) for x in range(10) if isinstance(tiles[y][x], dict) and tiles[y][x].get('crop') == 'CARROT']
        targeted = [q for q, v in S['target'].items() if v == 'CARROT']
        have = len(have_tiles) + sum(1 for q in targeted if q not in have_tiles)
        k = 0
        n_wheat_now = len(pool) + sum(1 for v in S['target'].values() if v == 'WHEAT')     # wheat tiles + empties that become wheat
        while have < want and day <= P['CARROT_LAST_DAY'] and pool and convertible > 0 and n_wheat_now > P['CARROT_WHEAT_MIN'] and S['alloc_count'].get('CARROT', 0) < P['CARROT_MAX'] + S.get('carrot_early', 0):
            pos = pool.pop(); S['target'][pos] = 'CARROT'; have += 1; k += 1; convertible -= 1; n_wheat_now -= 1
            S['alloc_count']['CARROT'] = S['alloc_count'].get('CARROT', 0) + 1
            if S.get('carrot_early_on'): S['carrot_early'] = S.get('carrot_early', 0) + 1
            product, sched = addition_schedule('CARROT', day, day)
            if sched:
                for t, u in enumerate(sched):
                    if u: S['alloc_added'].setdefault(product, {}); S['alloc_added'][product][day + t] = S['alloc_added'][product].get(day + t, 0) + u
        if P['CARROT_SHRINK'] and have > want:
            # release carrot targets (they replant wheat at their next harvest); untouched targets first, then growing tiles
            rel = [q for q in targeted if q not in have_tiles] + [q for q in have_tiles if q in targeted]
            for q in rel[:have - want]:
                S['target'][q] = 'FILLER'; k -= 1
                S['alloc_count']['CARROT'] = max(0, S['alloc_count'].get('CARROT', 0) - 1)
        added.append(('CARROT_BLOCK', want, have, k, info))
    if P['TOM_RULE'] and not P['TOM_IF_NONE'] and day + CROPS['TOMATO']['first'] <= LAST_DAY - 1:
        tom_days = {int(k): v for k, v in P['TOM_DAYS'].items()}
        n_t = sum(1 for sh in shops if sh == 'PIZZA_SHOP') if P['TOM_PIZZA'] else sum(1 for sh in shops if 'TOMATO' in SHOPS[sh])
        if day in tom_days and n_t >= P['TOM_MIN_SHOPS']:
            # cumulative consumption to the end (known shops + TOM_FUTURE_W x expected future draws) minus both farms' projected supply
            dem_known = sum(1.0 + 6.0 * n_t for _ in range(n))
            dem_future = sum(D['TOMATO']) - dem_known
            deficit_end = (10000 - inv_now['TOMATO']) + dem_known + P['TOM_FUTURE_W'] * dem_future - sum(base_me('TOMATO')) - P['TOM_OPP_W'] * sum(base_opp('TOMATO'))
            want = int((deficit_end - P['TOM_TARGET']) / 8.0 * tom_days[day])
            want = max(0, min(want, P['TOM_MAX'] - S['alloc_count'].get('TOM_RULE', 0), convertible, len(pool)))
            if want >= P['TOM_MIN_TILES'] and cash >= 50 * want:
                for _ in range(want):
                    pos = pool.pop(0) if P['TOM_NEAR'] else pool.pop(); S['target'][pos] = 'TOMATO'; convertible -= 1; cash -= 50
                    S['alloc_count']['TOM_RULE'] = S['alloc_count'].get('TOM_RULE', 0) + 1
                    product, sched = addition_schedule('TOMATO', day, day)
                    for t, u in enumerate(sched):
                        if u: S['alloc_added'].setdefault(product, {}); S['alloc_added'][product][day + t] = S['alloc_added'][product].get(day + t, 0) + u
                added.append(('TOM_RULE', want, round(deficit_end), n_t, round(sum(base_opp('TOMATO')))))
            else:
                added.append(('TOM_RULE_SKIP', want, round(deficit_end), n_t, round(sum(base_opp('TOMATO')))))
    n_yarn_now = sum(1 for sh in shops if sh == 'YARN_STORE')
    n_pizza_now = sum(1 for sh in shops if sh == 'PIZZA_SHOP')
    n_farm_now = sum(1 for sh in shops if sh == 'FARMERS_MARKET')
    hold_herd = P['HERD_HOLD_EMPTY'] > 0 and sum(1 for row in tiles for t in row if t is None) >= P['HERD_HOLD_EMPTY']
    for _ in range(40 if (not ctx.get('replan') or P['LAND_H0_GREEDY']) and day >= P['ALLOC_GREEDY_FROM_DAY'] else 0):
        # (circ12 LAND_H0: on the hour-1 re-plan the new quadrant takes the rule-based additions and wheat; the greedy additions wait
        # for the next morning, when one more shop draw is known - on day 11 the binomial over 5 draws overvalues single-shop products)
        if convertible <= 0 or not pool: break
        best = None
        for kind in ('STRAWBERRY', 'TOMATO', 'SHEEP', 'COW', 'GOOSE', 'CARROT', 'MELON'):
            if hold_herd and kind in ANIMALS: continue
            if kind == 'MELON' and (not P['MELON_ALLOC'] or day + (11 if P['MELON_EARLY'] else 13) > LAST_DAY): continue
            if kind == 'GOOSE' and P['GOOSE_HOLD_EMPTY'] > 0 and sum(1 for row in tiles for t in row if t is None) >= P['GOOSE_HOLD_EMPTY']: continue
            if kind == 'CARROT' and not P['CARROT_ALLOC']: continue
            _ld = P['BOEY_LAST_DAY'].get(kind, P['ALLOC_LAST_DAY'][kind]) if (P['BOEY_OPP'] and kind in ANIMALS) else P['ALLOC_LAST_DAY'][kind]
            _mx = P['BOEY_ALLOC_MAX'].get(kind, P['ALLOC_MAX'][kind]) if (P['BOEY_OPP'] and kind in ANIMALS) else P['ALLOC_MAX'][kind]
            if day > _ld or S['alloc_count'].get(kind, 0) >= _mx: continue
            if kind == 'TOMATO' and day < P['TOM_FIRST_DAY']: continue
            if kind == 'TOMATO' and S.get('tom_none_planted'): continue
            if kind == 'STRAWBERRY' and P['STRAW_CAP'] > 0 and sum(1 for sh in shops if 'STRAWBERRY' in SHOPS[sh]) < P['STRAW_CAP_SHOPS']:
                have_s = sum(1 for row in tiles for t in row if isinstance(t, dict) and t.get('crop') == 'STRAWBERRY') + sum(1 for v in S['target'].values() if v == 'STRAWBERRY')
                if have_s >= P['STRAW_CAP']: continue
            product, sched = addition_schedule(kind, day, day)
            if sched is None: continue
            cost = addition_cost(kind, day, pr)
            if kind in ANIMALS and {'SHEEP': 500, 'COW': 400, 'GOOSE': 300}[kind] > cash: continue
            m = base_me(product); o = base_opp(product); gain = 0.0
            w = None
            if P['OPP_W_LEAD'] > 0: w = P['OPP_W'] if sum(o) > P['OPP_W_LEAD'] * sum(m) else 0.0
            for prob, dem in scen[product]:
                gain += prob * (proj_margin(product, inv_now[product], [a + b for a, b in zip(m, sched)], o, dem, w) - proj_margin(product, inv_now[product], m, o, dem, w))
            if P['BET_W'] > 0 and kind in P['BET_KINDS'] and n_known[product] >= P['BET_MIN_KNOWN'] and scen_opt[product] is not scen[product]:
                gopt = 0.0
                for prob, dem in scen_opt[product]:
                    gopt += prob * (proj_margin(product, inv_now[product], [a + b for a, b in zip(m, sched)], o, dem) - proj_margin(product, inv_now[product], m, o, dem))
                gain = (1 - P['BET_W']) * gain + P['BET_W'] * gopt
            net = gain - cost - alt_per_day * (LAST_DAY - day); nets[kind] = round(net)
            margin = P['ALLOC_MARGIN']
            if P['BOEY_OPP'] and kind in ANIMALS: margin = P['BOEY_ANIMAL_MARGIN']
            if kind == 'SHEEP' and P['SHEEP_MARGIN'] is not None and n_yarn_now: margin = P['SHEEP_MARGIN']
            if P['SPEC_MARGIN'] is not None and kind in P['SPEC_KINDS'] and n_known[product] == 0: margin = P['SPEC_MARGIN']
            if kind == 'TOMATO' and P['TOM_MARGIN'] is not None and n_pizza_now: margin = P['TOM_MARGIN']
            if kind == 'TOMATO' and P['TOM_FARM_MARGIN'] is not None and n_farm_now >= 2: margin = P['TOM_FARM_MARGIN']
            if net > margin and (best is None or net > best[0]): best = (net, kind, product, sched, gain, cost)
        if best is None: break
        net, kind, product, sched, gain, cost = best
        if kind in ANIMALS:
            reuse = empty_struct_for(kind, tiles) if P['REUSE_STRUCT'] else []
            if reuse: pos = reuse[0]; convertible += 1        # an existing empty structure: no build, no tile converted
            else: pos = pool.pop(0)       # nearest to the shed
            S['target'][pos] = ANIMALS[kind]['structure'] + ':' + kind
            S['buy_today'][kind] = S['buy_today'].get(kind, 0) + 1; cash -= {'SHEEP': 500, 'COW': 400, 'GOOSE': 300}[kind]
        else:
            pos = pool.pop()        # farthest
            S['target'][pos] = kind
        convertible -= 1
        S['alloc_count'][kind] = S['alloc_count'].get(kind, 0) + 1
        for t, u in enumerate(sched):
            if u: S['alloc_added'].setdefault(product, {}); S['alloc_added'][product][day + t] = S['alloc_added'][product].get(day + t, 0) + u
        added.append((kind, pos, round(net), round(gain), round(cost)))
    # After the greedy pass: plant pizza tomatoes only when that pass left the farm with none.
    # Doing it earlier takes the tiles the greedy tomato plan was going to use.
    if P['TOM_RULE'] and P['TOM_IF_NONE'] and day + CROPS['TOMATO']['first'] <= LAST_DAY - 1:
        have_tom = sum(1 for row in tiles for t in row if isinstance(t, dict) and t.get('crop') == 'TOMATO')
        have_tom += sum(1 for v in S['target'].values() if v == 'TOMATO')
        tom_days = {int(k): v for k, v in P['TOM_DAYS'].items()}
        n_t = sum(1 for sh in shops if sh == 'PIZZA_SHOP') if P['TOM_PIZZA'] else sum(1 for sh in shops if 'TOMATO' in SHOPS[sh])
        if have_tom == 0 and day in tom_days and n_t >= P['TOM_MIN_SHOPS']:
            dem_known = sum(1.0 + 6.0 * n_t for _ in range(n))
            dem_future = sum(D['TOMATO']) - dem_known
            opp_w = P['TOM_OPP_W'] if P['TOM_NONE_OPP'] is None else P['TOM_NONE_OPP']
            deficit_end = (10000 - inv_now['TOMATO']) + dem_known + P['TOM_FUTURE_W'] * dem_future - sum(base_me('TOMATO')) - opp_w * sum(base_opp('TOMATO'))
            want = int((deficit_end - P['TOM_TARGET']) / 8.0 * tom_days[day])
            want = max(0, min(want, P['TOM_MAX'] - S['alloc_count'].get('TOM_RULE', 0), convertible, len(pool)))
            if want >= P['TOM_MIN_TILES'] and cash >= 50 * want:
                for _ in range(want):
                    pos = pool.pop(0) if P['TOM_NEAR'] else pool.pop(); S['target'][pos] = 'TOMATO'; convertible -= 1; cash -= 50
                    S['alloc_count']['TOM_RULE'] = S['alloc_count'].get('TOM_RULE', 0) + 1
                    product, sched = addition_schedule('TOMATO', day, day)
                    for t, u in enumerate(sched):
                        if u: S['alloc_added'].setdefault(product, {}); S['alloc_added'][product][day + t] = S['alloc_added'][product].get(day + t, 0) + u
                added.append(('TOM_IF_NONE', want, round(deficit_end), n_t))
                S['tom_none_planted'] = True
    if P['CULL'] and P['CULL_FROM'] <= day <= LAST_DAY - 4:
        # cull: stop feeding animals whose remaining production (priced along the projected path, worst first, re-priced after
        # each cull) plus fertilizer is worth less than feed + labour + the wheat alternative on the freed tile
        cull = S.setdefault('cull', set()); days = LAST_DAY - day
        animals = [(x, y) for y in range(10) for x in range(10) if isinstance(tiles[y][x], dict) and 'animal' in tiles[y][x] and (x, y) not in cull]
        n_cull = 0; culled_units = {}
        n_keep = {a: sum(1 for q in animals if tiles[q[1]][q[0]]['animal'] == a) for a in ANIMALS}
        while n_cull < P['CULL_MAX_PER_DAY'] and animals:
            worst = None
            for q in animals:
                t = tiles[q[1]][q[0]]; kind = t['animal']; product = ANIMALS[kind]['product']
                if n_keep[kind] <= P['CULL_KEEP']: continue
                sched = farm_supply([[t]], day, 0.0)[product]
                m = [a - culled_units.get(product, [0.0] * n)[i] for i, a in enumerate(base_me(product))]; o = base_opp(product)
                loss = 0.0
                for prob, dem in scen[product]:
                    loss += prob * (proj_margin(product, inv_now[product], m, o, dem, P['CULL_OPP_W']) - proj_margin(product, inv_now[product], [max(0.0, a - b) for a, b in zip(m, sched)], o, dem, P['CULL_OPP_W']))
                keep_val = loss + days * 0.5 * pr['FERTILIZER'] - days * (pr['WHEAT'] + 4.2 * P['LABOUR_COST'])
                cull_val = 2 * 0.5 * pr['FERTILIZER'] + alt_per_day * max(0, days - 3) - 10
                net = cull_val - keep_val
                if net > P['CULL_MARGIN'] and (worst is None or net > worst[0]): worst = (net, q, kind, product, sched, round(loss))
            if worst is None: break
            net, q, kind, product, sched, loss = worst
            cull.add(q); animals.remove(q); n_cull += 1; n_keep[kind] -= 1
            S['target'][q] = 'FILLER'
            cu = culled_units.setdefault(product, [0.0] * n)
            for i, u in enumerate(sched): cu[i] += u
            added.append(('CULL', q, kind, round(net), loss))
    if P['DEBUG']:
        log(f"d{day} ALLOC shops {shops} added {added} counts {S['alloc_count']} buy {S['buy_today']} cash {cash:.0f} last nets {nets} alt {alt_per_day:.1f} {S.get('alt_proj')}")
        for product in ('STRAWBERRY', 'MILK', 'WOOL', 'TOMATO', 'EGG'):
            m = base_me(product); o = base_opp(product); inv = inv_now[product]; path = []
            for t in range(n):
                path.append(market_price(product, inv + m[t] / 2.0)); inv += m[t] + o[t] - D[product][t]
            log(f"   {product[:5]} inv {inv_now[product]} me {sum(m):.0f} opp {sum(o):.0f} dem {sum(D[product]):.0f} price path {path}")

def rebuy_pending(ctx):
    """Structure targets whose animal has not arrived (purchase failed for cash / shed room, or the animal went to another empty
    structure): re-issue the purchase while the target is at most REBUY_DAYS old and the cash allows."""
    day = ctx['day']; tiles = ctx['tiles']; me = ctx['me']
    price = {'SHEEP': 500, 'COW': 400, 'GOOSE': 300}
    pending = {}
    for pos, tgt in S['target'].items():
        if ':' not in tgt: continue
        struct, animal = tgt.split(':'); t = tiles[pos[1]][pos[0]]
        if isinstance(t, dict) and 'animal' in t: continue
        age = day - S.get('target_day', {}).get(pos, day)
        if 1 <= age <= P['REBUY_DAYS'] and isinstance(t, dict) and t.get('kind') == struct: pending[animal] = pending.get(animal, 0) + 1
    cash = float(me['money']) - P['CASH_RESERVE'] - P['REBUY_RESERVE']
    for animal, n in pending.items():
        short = n - ctx['shed_animals'].get(animal, 0) - S['buy_today'].get(animal, 0)
        while short > 0 and cash >= price[animal]:
            S['buy_today'][animal] = S['buy_today'].get(animal, 0) + 1; cash -= price[animal]; short -= 1
            if P['DEBUG']: log(f"d{day} REBUY {animal} (pending {n})")

def open_rank4(ctx):
    """Prefix-free opening matched to the rank-4 cash schedule.
    Day 0: 6 melons, 10 wheat, 2 cows, 3 sheep. Days 1-2: fertilizer sales buy the other melons.
    Days 2-4: ripe wheat is marked STRAWBERRY (2, then 3, then 3) and cut at first yield."""
    day = ctx['day']; tiles = ctx['tiles']
    def empties():
        return [(x, y) for y in range(10) for x in range(10) if tiles[y][x] is None]
    if day == 0 and not S.get('open_done'):
        far = sorted(empties(), key=lambda q: -dist(q, nearest_shed(q)))
        S['target'] = {}
        for pos in far[:6]: S['target'][pos] = 'MELON'
        for pos in far[6:16]: S['target'][pos] = 'WHEAT'
        used = set(S['target'])
        rest = sorted((p for p in empties() if p not in used), key=lambda q: dist(q, nearest_shed(q)))
        for pos in rest[:2]: S['target'][pos] = 'PASTURE:COW'
        for pos in rest[2:5]: S['target'][pos] = 'PASTURE:SHEEP'
        for pos in rest[5:]: S['target'][pos] = 'HOLD'
        S['buy_today']['COW'] = 2
        S['buy_today']['SHEEP'] = 3
        S['open_done'] = True
        return
    tgt = S.setdefault('target', {})
    for pos in list(tgt):
        if tgt[pos] == 'HOLD': continue
        t = tiles[pos[1]][pos[0]]
        if isinstance(t, dict) and t.get('crop') == tgt[pos]: del tgt[pos]
    if day in (1, 2):
        for pos in list(tgt):
            if tgt[pos] == 'HOLD': del tgt[pos]
        have = sum(1 for row in tiles for t in row if isinstance(t, dict) and t.get('crop') == 'MELON')
        have += sum(1 for v in tgt.values() if v == 'MELON')
        need = min(12 - have, 4 if day == 1 else 2)
        far = sorted((p for p in empties() if p not in tgt), key=lambda q: -dist(q, nearest_shed(q)))
        for pos in far[:max(0, need)]: tgt[pos] = 'MELON'
    if day in (2, 3, 4) and S.get('open_straw_day') != day:
        quota = {2: 2, 3: 3, 4: 3}[day]
        wheats = [(x, y) for y in range(10) for x in range(10)
                  if isinstance(tiles[y][x], dict) and tiles[y][x].get('crop') == 'WHEAT' and day - tiles[y][x].get('planted_day', day) >= 2
                  and tgt.get((x, y)) != 'STRAWBERRY']
        for pos in wheats[:quota]: tgt[pos] = 'STRAWBERRY'
        S['open_straw_day'] = day

def _anticipate_grid(me):
    """(grid, spots) for the next quadrant we can already afford. None if the buy would not happen."""
    tiles = me['tiles']
    locked = sum(1 for row in tiles for t in row if t == 'LOCKED')
    n_extra = (100 - locked) // 25 - 1
    if not (0 <= n_extra < P['LAND_MAX_EXTRA']): return None
    price = [1000, 2000, 4000][n_extra]
    if me['money'] < price + P['LAND_RESERVE'] + 1500: return None
    quad = ['NE', 'SW', 'SE'][n_extra]
    def in_quad(x, y):
        if quad == 'NE': return x >= 5 and y < 5
        if quad == 'SW': return x < 5 and y >= 5
        return x >= 5 and y >= 5
    out = []; spots = []
    for y, row in enumerate(tiles):
        nrow = []
        for x, t in enumerate(row):
            if t == 'LOCKED' and (x, y) not in SHED and in_quad(x, y):
                nrow.append(None); spots.append((x, y))
            else: nrow.append(t)
        out.append(nrow)
    return (out, spots) if spots else None

def anticipate_land(me, day):
    """Copy of the farm with the next affordable quadrant shown as empty, so the hour-0 plan can plant it.
    None when the buy would not happen. Shed-access tiles stay locked. Live tiles are not touched."""
    if not P['LAND_SEE'] or day >= LAST_DAY - 6: return None
    got = _anticipate_grid(me)
    return got[0] if got else None

def empty_struct_for(kind, tiles):
    """Empty structures of the animal's kind that hold no animal and are not targeted, nearest to the shed first."""
    struct = ANIMALS[kind]['structure']; tg = S.get('target', {})
    out = [(x, y) for y in range(10) for x in range(10) if isinstance(tiles[y][x], dict) and tiles[y][x].get('kind') == struct
           and 'animal' not in tiles[y][x] and (x, y) not in tg]
    return sorted(out, key=lambda q: dist(q, nearest_shed(q)))

# ---------------------------------------------------------------- agent
# ---------------------------------------------------------------- microstructure (final30; default off)
MS_ITEMS = ('WHEAT', 'CARROT', 'TOMATO', 'STRAWBERRY', 'MELON', 'EGG', 'MILK', 'WOOL')
MS_ANIMAL = {'GOOSE': 'EGG', 'COW': 'MILK', 'SHEEP': 'WOOL'}
MS_ONGOING = ('TOMATO', 'STRAWBERRY')
def ms_on(): return P['MS_SLOT'] or P['MS_RACE'] or P['MS_OVERFLOW'] or P['MS_CAPHARV'] or P['MS_DRIP']
def ms_tiles(farm):
    out = {}
    for y, row in enumerate(farm['tiles']):
        for x, t in enumerate(row):
            if not isinstance(t, dict): continue
            if t.get('kind') == 'PLANT' and t.get('crop'): out[(x, y)] = ('P', t['crop'], t.get('planted_day', -1), t.get('yield_units', 0) or 0)
            elif t.get('animal') in MS_ANIMAL: out[(x, y)] = ('A', MS_ANIMAL[t['animal']], t.get('placed_day', -1), t.get('yield_units', 0) or 0)
    return out
def ms_observe(ctx, obs):
    """rival unsold stock per product: + visible harvests on its tiles, - its sales (market-inventory move + town draw - our sold
    + our bought; exact above the $1 floor)."""
    M = S.setdefault('ms', {'stock': {i: 0 for i in MS_ITEMS}, 'prev': None, 'rsold': {}, 'stat': {}})
    step = ctx['step']; rival = obs['farms'][1 - obs['player']]
    tiles = ms_tiles(rival); inv = ctx['inv']; prev = M['prev']; M['rsold'] = {}
    if prev and prev['step'] == step - 1:
        stock = M['stock']
        for pos, old in prev['tiles'].items():
            kind, item, born, y = old
            if y <= 0: continue
            new = tiles.get(pos); got = 0
            if kind == 'P' and item not in MS_ONGOING:
                if new is None or new[2] != born or new[1] != item:
                    t = rival['tiles'][pos[1]][pos[0]]
                    if not (isinstance(t, dict) and t.get('kind') == 'WEED'): got = y
            elif new is not None and new[:3] == old[:3] and new[3] < y:
                if step % 24 != 0: got = y - new[3]
                elif new[3] == 0: got = y
            if got > 0: stock[item] = stock.get(item, 0) + got
        for item in MS_ITEMS:
            if prev['price'].get(item, 0) <= 1: continue
            moved = inv.get(item, 10000) - prev['inv'].get(item, 10000) + sq_cons(prev['shops'], item, prev['step']) - prev['own'].get(item, 0) + prev['bought'].get(item, 0)
            if moved > 0:
                M['rsold'][item] = moved; stock[item] = max(0, stock.get(item, 0) - moved)
    M['cur'] = {'step': step, 'tiles': tiles, 'inv': dict(inv), 'price': dict(ctx['prices']), 'shops': list(ctx['shops'])}
def ms_after(ctx, orders):
    M = S.get('ms')
    if not M or 'cur' not in M: return
    shed = ctx['shed']; left = {k: shed.get(k, 0) - ctx['reserved'].get(k, 0) + ctx['dropping'].get(k, 0) for k in PRODUCTS}
    own = {}; bought = {}
    for o in orders[:10]:
        if o[0] == 'SELL' and len(o) > 2:
            g = min(int(o[2]), max(0, left.get(o[1], 0))); left[o[1]] = left.get(o[1], 0) - g; own[o[1]] = own.get(o[1], 0) + g
        elif o[0] == 'BUY_PRODUCT' and len(o) > 2: bought[o[1]] = bought.get(o[1], 0) + int(o[2])
    M['prev'] = dict(M.pop('cur'), own=own, bought=bought)
def ms_expo(item, q, b, inv):
    if q <= 0 or b <= 0 or item not in MP: return 0.0
    return float(sum(market_price(item, inv + j) - market_price(item, inv + b + j) for j in range(q)))
def ms_stat(k, v=1):
    st = S.setdefault('ms', {}).setdefault('stat', {}); st[k] = st.get(k, 0) + v
def ms_post(ctx, obs, orders, acts):
    day, hour, step = ctx['day'], ctx['hour'], ctx['step']
    M = S.get('ms')
    if not M: return orders
    shed = ctx['shed']; pr = ctx['prices']; invm = ctx['inv']
    def avail(it): return shed.get(it, 0) - ctx['reserved'].get(it, 0) + ctx['dropping'].get(it, 0)
    orders = [list(o) for o in orders]; stock = M['stock']; changed = set()
    def sold_of(it): return sum(int(o[2]) for o in orders if o[0] == 'SELL' and o[1] == it and len(o) > 2)
    def add_sell(it, n):
        for o in orders:
            if o[0] == 'SELL' and o[1] == it: o[2] = int(o[2]) + n; changed.add(it); return True
        if len(orders) < 10: orders.insert(0, ['SELL', it, n]); changed.add(it); return True
        # full list: swap out the weakest sell (lowest exposure, then lowest lot value)
        sells = [o for o in orders if o[0] == 'SELL' and o[1] != it]
        if not sells: return False
        w = min(sells, key=lambda o: (ms_expo(o[1], min(int(o[2]), max(0, avail(o[1]))), min(P['MS_CAP'], stock.get(o[1], 0)), invm.get(o[1], 10000)), min(int(o[2]), max(0, avail(o[1]))) * pr.get(o[1], 0)))
        orders.remove(w); changed.add(w[1]); orders.insert(0, ['SELL', it, n]); changed.add(it); ms_stat('swap'); return True
    capped = {}
    if P['MS_DRIP'] and not (day == LAST_DAY and hour >= P['MS_DRIP_END']):
        # market-side metering: at most K units per premium product per step (K on the step right after a shop tick that draws the
        # product, KOFF otherwise); free below MS_DRIP_FREE x base / at the floor, or when the rival sold the product last step
        shops = ctx['shops']
        for item in P['MS_DRIP_ITEMS']:
            tot = sold_of(item)
            if tot <= 0: continue
            p0 = pr.get(item, 0)
            if p0 <= 1 or p0 < P['MS_DRIP_FREE'] * MP[item][0] or M['rsold'].get(item, 0) > 0: continue
            tick = (step % 4 == 1 and any(item in SHOPS.get(sh, ()) for sh in shops)) or step % 24 == 1
            k = P['MS_DRIP_K'] if tick else P['MS_DRIP_KOFF']
            q = min(tot, max(0, avail(item)))
            if q <= k: continue
            cap = k; kept = []
            for o in orders:
                if o[0] == 'SELL' and o[1] == item:
                    g = min(int(o[2]), cap); cap -= g
                    if g > 0: o[2] = g; kept.append(o)
                    else: o[2] = 0
            orders = [o for o in orders if not (o[0] == 'SELL' and o[1] == item and int(o[2]) <= 0)]
            capped[item] = q - (k - cap); changed.add(item); ms_stat('drip_' + item[:4], q - (k - cap))
        if capped:
            # shed room: shed after this step's orders (+ carried produce near the shed / all carried at hour 23) <= MS_DRIP_SHED;
            # release capped units, largest stock first
            total = sum(shed.values()) - sum(ctx['reserved'].values()) + sum(ctx['dropping'].values()) + ctx.get('near_inv', 0)
            left = {k2: avail(k2) for k2 in PRODUCTS}
            for o in orders:
                if o[0] == 'SELL' and len(o) > 2: g = min(int(o[2]), max(0, left.get(o[1], 0))); left[o[1]] -= g; total -= g
                elif o[0] in ('BUY_PRODUCT', 'BUY_ANIMAL') and len(o) > 2: total += int(o[2])
            ex = total - P['MS_DRIP_SHED']
            for item in sorted(capped, key=lambda k2: -capped[k2]):
                if ex <= 0: break
                d = min(capped[item], ex)
                if d > 0 and add_sell(item, d): ex -= d; capped[item] -= d; ms_stat('driprel_' + item[:4], d)
    if P['MS_RACE'] and P['MS_RACE_FROM'] <= day < LAST_DAY:
        for item in P['MS_RACE_ITEMS']:
            if M['rsold'].get(item, 0) <= 0 or stock.get(item, 0) < P['MS_RACE_MINSTOCK']: continue
            gate = P['MS_RACE_GATE'] * MP[item][0]
            if pr.get(item, 0) < gate: continue
            q = avail(item); cur = min(q, sold_of(item))
            if q - cur <= 0: continue
            inv = invm.get(item, 10000); n = cur
            while n < q and market_price(item, inv + n) >= gate: n += 1
            if n - cur > 0 and add_sell(item, n - cur): ms_stat('race_' + item[:4], n - cur)
    if P['MS_OVERFLOW'] and hour == 23 and day < LAST_DAY:
        me = ctx['me']; invs = ctx['priv']['inventories']; tiles = ctx['tiles']
        pos = [tuple(me['farmer'])] + [tuple(h) for h in me['hands']]
        total = sum(shed.values()); tail = {}
        for ui in range(min(len(pos), len(invs))):
            held = dict((k, v) for k, v in invs[ui].items() if v > 0); a = acts[ui] if ui < len(acts) else ['PASS']
            t = tiles[pos[ui][1]][pos[ui][0]] if a else None
            if a and a[0] == 'HARVEST' and isinstance(t, dict) and (t.get('yield_units', 0) or 0) > 0:
                it = MS_ANIMAL.get(t.get('animal')) if t.get('animal') else t.get('crop')
                if it: held[it] = held.get(it, 0) + t['yield_units']
            elif a and a[0] == 'COLLECT_FERTILIZER' and isinstance(t, dict) and t.get('fertilizer_available'): held['FERTILIZER'] = held.get('FERTILIZER', 0) + 1
            elif a and a[0] == 'FEED' and held.get('WHEAT', 0) > 0: held['WHEAT'] -= 1
            elif a and a[0] == 'FERTILIZE' and held.get('FERTILIZER', 0) > 0: held['FERTILIZER'] -= 1
            total += sum(held.values())
            if not (a and a[0] == 'DROP' and pos[ui] in SHED):
                for k, v in held.items():
                    if v > 0: tail[k] = tail.get(k, 0) + v
        left = {k: avail(k) for k in PRODUCTS}
        for o in orders:
            if o[0] == 'SELL' and len(o) > 2: g = min(int(o[2]), max(0, left.get(o[1], 0))); left[o[1]] -= g; total -= g
            elif o[0] in ('BUY_PRODUCT', 'BUY_ANIMAL') and len(o) > 2: total += int(o[2])
        over = total - 100
        if over > 0:
            n_an = sum(1 for row in tiles for t in row if isinstance(t, dict) and t.get('animal'))
            keep = {'WHEAT': n_an + P['WHEAT_BUFFER'], 'FERTILIZER': 10 ** 6}
            cands = [(0, k) for k in tail if k in PRODUCTS] + [(1, k) for k in sorted(PRODUCTS, key=lambda k: pr.get(k, 1) / MP[k][0]) if k not in tail]
            for _, it in cands:
                if over <= 0: break
                sp = left.get(it, 0) - keep.get(it, 0)
                if sp <= 0 or pr.get(it, 0) < 2: continue
                d = min(sp, over)
                if add_sell(it, d): over -= d; left[it] -= d; ms_stat('ovf_' + it[:4], d)
    if P['MS_SLOT'] and orders:
        bought = set(); movable = []; fixed = []
        for idx, o in enumerate(orders):
            if o[0] in ('BUY_PRODUCT', 'BUY_ANIMAL'): bought.add(o[1])
            if o[0] == 'SELL' and len(o) > 2 and int(o[2]) > 0 and o[1] not in bought: movable.append((idx, o))
            else: fixed.append((idx, o))
        def sc(io):
            idx, o = io; it = o[1]; q = min(int(o[2]), max(0, avail(it)))
            return (-ms_expo(it, q, min(P['MS_CAP'], stock.get(it, 0)), invm.get(it, 10000)), idx)
        new = [o for _, o in sorted(movable, key=sc)] + [o for _, o in fixed]
        if [o[1] for o in new if o[0] == 'SELL'] != [o[1] for o in orders if o[0] == 'SELL']: ms_stat('slot_reorder')
        orders = new
    if changed:
        # keep the SQ / MPC own-sale bookkeeping consistent with the final list
        left = {k: avail(k) for k in PRODUCTS}; fin = {}
        for o in orders[:10]:
            if o[0] == 'SELL' and len(o) > 2: g = min(int(o[2]), max(0, left.get(o[1], 0))); left[o[1]] -= g; fin[o[1]] = fin.get(o[1], 0) + g
        if P['SQ'] and 'sq_prev' in S:
            ms_ = S['sq_prev']['my_sold']
            for it in changed:
                if it in P['SQ_ITEMS'] or (P['HOLD_OPP_GATE'] and it in ('TOMATO', 'CARROT')): ms_[it] = fin.get(it, 0)
        Mp = S.get('mpc')
        if Mp:
            for it in changed:
                st = Mp['items'].get(it)
                if st is not None and st.get('lstep') == step: st['left'] = avail(it) - fin.get(it, 0)
    return orders[:10]
def ms_capharv(ctx, acts):
    """CARE / COLLECT_FERTILIZER on an animal whose stored yield overflows max_held at tonight's production, with no HARVEST left
    on that unit's current stop -> HARVEST now."""
    day = ctx['day']
    if day >= LAST_DAY: return acts
    me = ctx['me']; tiles = ctx['tiles']; pr = ctx['prices']
    pos = [tuple(me['farmer'])] + [tuple(h) for h in me['hands']]
    for ui, a in enumerate(acts):
        if not a or a[0] not in ('CARE', 'COLLECT_FERTILIZER') or ui >= len(pos): continue
        x, y = pos[ui]; t = tiles[y][x]
        if not (isinstance(t, dict) and t.get('animal') in ANIMALS): continue
        an = ANIMALS[t['animal']]; ds = day + 1 - t.get('placed_day', 99) - an['first']
        if ds < 0 or ds % an['interval'] != 0: continue
        yu = t.get('yield_units', 0) or 0
        if yu <= 0: continue
        p = S['unit_plans'].get(ui)
        later = False
        if p is not None and p.get('idx', 0) < len(p.get('stops', [])):
            stp = p['stops'][p['idx']]
            later = stp.pos == (x, y) and any(q[0] == 'HARVEST' for q in stp.acts)
        if later: continue
        fed = bool(t.get('fed_today')) or (p is not None and p.get('idx', 0) < len(p.get('stops', [])) and p['stops'][p['idx']].pos == (x, y) and any(q[0] == 'FEED' for q in p['stops'][p['idx']].acts))
        overflow = yu + 1 + (t.get('pending_care_bonus', 0) if fed else 0) - an['max_held']
        if overflow <= 0: continue
        if a[0] == 'COLLECT_FERTILIZER' and overflow * pr.get(an['product'], 0) <= pr.get('FERTILIZER', 0): continue
        if a[0] == 'CARE' and overflow <= 1: continue
        acts[ui] = ['HARVEST']; ms_stat('cap_' + a[0][:4], overflow)
    return acts

def agent(obs, config=None):
    step = int(obs.get('step', obs.get('day', 0) * 24 + obs.get('hour', 0)))
    day, hour = step // 24, step % 24
    me = obs['farms'][obs['player']]; priv = obs['private']
    ctx = {'day': day, 'hour': hour, 'step': step, 'me': me, 'priv': priv, 'tiles': me['tiles'], 'prices': obs['market']['prices'],
           'shed': dict(priv['shed']), 'reserved': {}, 't0': time.perf_counter(), 'inv': obs['market']['inventory'], 'dropping': {},
           'opp_tiles': obs['farms'][1 - obs['player']]['tiles'], 'shops': list(obs['town']['unlocked_shops'])}
    if P['SQ']: sq_observe(ctx, obs)
    if P['MPC_SELL'] and step >= 200: mpc_observe(ctx, obs)   # latemarket
    if ms_on(): ms_observe(ctx, obs)
    replan = S.get('replan_step') == step and S.get('day') == day and hour > 0
    ctx['replan'] = replan
    if S.get('day') != day or replan:
        S['day'] = day; S['opp_taken'] = set(); S['hired_today'] = len(me['hands']) if hour > 0 else 0; S['shed_log'] = []; S['unit_plans'] = {}; S['reserved_total'] = {}
        S['dropped_today'] = 0
        n_animals = sum(1 for row in me['tiles'] for t in row if isinstance(t, dict) and 'animal' in t)
        ctx['need_wheat_buy'] = priv['shed'].get('WHEAT', 0) < n_animals + P['WHEAT_BUFFER']
        ctx['need_fert_buy'] = priv['shed'].get('FERTILIZER', 0) < 4
        ctx['shed_keep'] = P['WHEAT_BUFFER']
        ctx['shed_animals'] = {a: priv['shed'].get(a, 0) for a in ANIMALS}
        S['buy_today'] = {}
        n_ws = sum(1 for sh in obs['town']['unlocked_shops'] if 'WHEAT' in SHOPS[sh])
        ctx['fert_wheat_maxp'] = P['FERT_WHEAT_MAXP2'] if n_ws >= P['FERT_WHEAT_SHOPS'] else P['FERT_WHEAT_MAXP']
        seen = anticipate_land(me, day) if hour == 0 and not replan and P['LAND'] and S.get('land_today') != day else None
        if seen is not None: ctx['tiles'] = seen
        defer_alloc = False
        if P['LAND_H0'] and P['LAND_H0_DEFER_ALLOC'] and hour == 0 and P['LAND'] and day < LAST_DAY - 6 and S.get('land_today') != day:
            locked = sum(1 for row in me['tiles'] for t in row if t == 'LOCKED'); n_extra = (100 - locked) // 25 - 1
            if 0 <= n_extra < P['LAND_MAX_EXTRA']:
                price = [1000, 2000, 4000][n_extra]
                if me['money'] >= price + P['LAND_RESERVE'] + 400: defer_alloc = True
        if P['OPEN_RANK4'] and day < 6:
            open_rank4(ctx)
        elif P['ALLOC'] and not defer_alloc and (day <= max(P['ALLOC_LAST_DAY'].values()) or (P['CULL'] and day <= LAST_DAY - 4)): allocate(ctx, obs)
        elif P['CARROT_BLOCK'] and P['CARROT_SHRINK'] and S.get('target'):
            want, info = carrot_want(ctx, obs, list(obs['town']['unlocked_shops']))
            car = [q for q, v in S['target'].items() if v == 'CARROT']
            if P['CARROT_AFTER'] and day >= P['CARROT_FIRST_DAY'] and day <= P['CARROT_LAST_DAY'] and want > len(car):
                tiles = ctx['tiles']
                wheat_tiles = [(x, y) for y in range(10) for x in range(10) if isinstance(tiles[y][x], dict) and tiles[y][x].get('crop') == 'WHEAT' and (x, y) not in S['target']]
                empty_tiles = [(x, y) for y in range(10) for x in range(10) if tiles[y][x] is None and (x, y) not in S['target']]
                pool = sorted(empty_tiles + wheat_tiles, key=lambda q: dist(q, nearest_shed(q)))
                n_wheat_now = len(pool) + sum(1 for v in S['target'].values() if v == 'WHEAT')
                convertible = max(0, len(empty_tiles) + max(0, len(wheat_tiles) - P['WHEAT_MIN_TILES']))
                have = len(car)
                while have < want and pool and convertible > 0 and n_wheat_now > P['CARROT_WHEAT_MIN'] and S['alloc_count'].get('CARROT', 0) < P['CARROT_MAX'] + S.get('carrot_early', 0):
                    pos = pool.pop(); S['target'][pos] = 'CARROT'; have += 1; convertible -= 1; n_wheat_now -= 1
                    S['alloc_count']['CARROT'] = S['alloc_count'].get('CARROT', 0) + 1
                car = [q for q, v in S['target'].items() if v == 'CARROT']
            for q in car[:max(0, len(car) - want)]: S['target'][q] = 'FILLER'
            if P['DEBUG']: log(f"d{day} CARROT shrink want {want} targets {len(car)} info {info}")
        S['late_quota'] = carrot_late_quota(ctx, obs) if P['CARROT_LATE_CAP'] and day >= P['LATE_START'] else 0
        # The spot ratio misses a charged carrot deficit when wheat is equally expensive. Force the late swap
        # only when the market-room quota is already large. 0 leaves the tape rule unchanged.
        if P['LATE_ON_QUOTA'] and S['late_quota'] >= P['LATE_ON_QUOTA']: S['late_enabled'] = True
        if P['DEBUG'] and day >= P['LATE_START']: log(f"d{day} late_quota {S['late_quota']} enabled {S.get('late_enabled')} c {ctx['prices']['CARROT']:.0f} w {ctx['prices']['WHEAT']:.0f} inv {ctx['inv']['CARROT'] - 10000} shed carrots {ctx['shed'].get('CARROT', 0)}")
        td = S.setdefault('target_day', {})
        for pos in S.get('target', {}):
            if pos not in td: td[pos] = day
        if P['REBUY'] and S.get('target'): rebuy_pending(ctx)
        for a, n in S['buy_today'].items(): ctx['shed_animals'][a] = ctx['shed_animals'].get(a, 0) + n
        if P['LAND_SEE_N'] > 0 and seen is None and hour == 0 and not replan and P['LAND'] and S.get('land_today') != day and day < LAST_DAY - 6:
            # Strawberries only. Holding the rest of the quadrant keeps geese and wheat off those tiles.
            got = _anticipate_grid(me)
            if got:
                grid, spots = got
                spots.sort(key=lambda q: dist(q, nearest_shed(q)))
                for pos in spots: S['target'][pos] = 'HOLD'
                for pos in spots[:int(P['LAND_SEE_N'])]: S['target'][pos] = 'STRAWBERRY'
                ctx['tiles'] = grid
                seen = grid
        plan_day(ctx)
        if seen is not None: ctx['tiles'] = me['tiles']
        S['unit_plans'][0] = S['plan']['farmer']
        if P['SQ'] and not replan: sq_plan(ctx, obs)
        if replan and P['DEBUG']: log(f"d{day} h{hour} REPLAN (LAND_H0) hands now {len(me['hands'])} plan hands {S['plan']['hires_wanted']}")
    plan = S['plan']
    ctx['reserved_total'] = S['reserved_total']
    positions = [tuple(me['farmer'])] + [tuple(h) for h in me['hands']]
    invs = priv['inventories']
    n_units = len(positions)
    if P['OPT_ASSIGN']:
        # micro OPT_ASSIGN: hands appearing this hour (all with the same hours left) take the free plans that fill those hours
        # best (longest first, capped at the hours left; less overrun on ties), each plan going to the new hand that reaches its
        # route soonest from its spawn tile; later (shorter-time) hands get the shorter plans
        newu = [ui for ui in range(1, n_units) if ui not in S['unit_plans']]
        free = plan['hands_free']
        if newu and free:
            H = (24 - hour) if day < LAST_DAY else max(0, 23 - hour)
            rc = {id(q): remaining_cost(q, q['start']) for q in free}
            chosen = sorted(free, key=lambda q: (-min(rc[id(q)], H), rc[id(q)]))[:len(newu)]
            left = list(newu)
            for q in chosen:
                uj = min(left, key=lambda z: (remaining_cost(q, positions[z]), z))
                left.remove(uj); free.remove(q); q['unit'] = uj; S['unit_plans'][uj] = q
    for ui in range(1, n_units):
        if ui not in S['unit_plans']:
            free = plan['hands_free']
            if free and P['ASSIGN3']:
                # lateexec ASSIGN3: all units that appear this step are matched to plans together (least overrun first)
                hl = (24 - hour) if day < LAST_DAY else max(0, 23 - hour)
                new_u = [u for u in range(ui, n_units) if u not in S['unit_plans']]
                pairs = []
                for u in new_u:
                    for qi, q in enumerate(free):
                        rc = remaining_cost(q, positions[u]); pairs.append((max(0, rc - hl), -q['budget'], rc - q['budget'], u, qi))
                pairs.sort(); used_u = set(); used_q = set()
                for ov, nb, ex, u, qi in pairs:
                    if u in used_u or qi in used_q: continue
                    used_u.add(u); used_q.add(qi); q = free[qi]; q['unit'] = u; S['unit_plans'][u] = q
                for qi in sorted(used_q, reverse=True): free.pop(qi)
                for u in new_u:
                    if u not in S['unit_plans']: S['unit_plans'][u] = None
                continue
            if free and P['ASSIGN2']:
                # lateexec ASSIGN2: the new unit takes the plan it can finish from where it actually spawned (least overrun of the
                # hours it has left), tightest plan first, then least extra walking vs the plan's own estimate
                hl = (24 - hour) if day < LAST_DAY else max(0, 23 - hour)
                def k_(q):
                    rc = remaining_cost(q, positions[ui]); return (max(0, rc - hl), -q['budget'], rc - q['budget'])
                p = min(free, key=k_)
                free.remove(p); p['unit'] = ui; S['unit_plans'][ui] = p
            elif free:
                p = min(free, key=lambda q: dist(positions[ui], q['stops'][0].pos))
                free.remove(p); p['unit'] = ui; S['unit_plans'][ui] = p
            else: S['unit_plans'][ui] = None
    plans = S['unit_plans']
    hours_left = (24 - hour) if day < LAST_DAY else max(0, 23 - hour)
    if P['REORDER']:
        # lateexec REORDER: a unit that spawned on another shed tile than its plan's start re-orders its stops from where it stands
        for ui in range(n_units):
            p = plans.get(ui)
            if p is None or p.get('_ro') or p['idx'] > 0 or not p['stops']: continue
            p['_ro'] = True; pos = positions[ui]
            if tuple(pos) == tuple(p.get('start') or pos) or any(a[0] == 'PLACE_PROD' for st in p['stops'] for a in st.acts): continue
            end = tuple(pos) if p['ret'] and tuple(pos) in SHED else None
            o = two_opt(nn_order(p['stops'], tuple(pos), end), tuple(pos), end)
            def _pl(order): return path_len([st.pos for st in order], tuple(pos)) + (dist(order[-1].pos, end) if end else 0)
            if P['CREDIT'] and any(credit_short(o, k) > p['needs'].get(k, 0) for k in ('WHEAT', 'FERTILIZER')): continue   # keep feeds after the credited harvests
            if _pl(o) < _pl(p['stops']): p['stops'] = o
    if P['DEBUG']:
        for ui in range(n_units):
            p = plans.get(ui)
            if p is not None and not p.get('_chk'):
                p['_chk'] = True; log(f"ASG d{day} h{hour} u{ui} pos {positions[ui]} start {p.get('start')} budget {p['budget']} rc {remaining_cost(p, positions[ui])} hl {hours_left}")
    idle = [ui for ui in range(n_units) if plans.get(ui) is None or plans[ui]['phase'] == 'done']
    if idle and hour >= 2: help_assign(idle, plans, positions, ctx, hours_left)
    seeds_left = dict(priv['seeds'])
    acts = []; ctx['dropping'] = {}
    for ui in range(n_units):
        p = plans.get(ui); pos = positions[ui]; inv = dict(invs[ui]) if ui < len(invs) else {}
        if p is None or p['phase'] == 'done':
            carrying = sum(inv.values())
            if carrying >= 1 and (P['HOME_IDLE'] or day == LAST_DAY) and not (p and p.get('dropped')):
                if tuple(pos) in SHED:
                    if p is not None: p['dropped'] = True
                    acts.append(['DROP']); continue
                if dist(pos, nearest_shed(pos)) <= hours_left:
                    acts.append(step_toward(pos, nearest_shed(pos))); continue
            acts.append(['PASS']); continue
        acts.append(exec_unit(p, pos, inv, ctx, seeds_left, hours_left) or ['PASS'])
    for ui, a in enumerate(acts):
        if a and a[0] == 'DROP' and ui < len(invs):
            for k, v in invs[ui].items(): ctx['dropping'][k] = ctx['dropping'].get(k, 0) + v
    for k, v in ctx['reserved'].items(): S['reserved_total'][k] = S['reserved_total'].get(k, 0) + v
    if P['SQ'] or P['MT']:
        ctx['near_inv'] = sum(sum(invs[ui].values()) for ui in range(min(n_units, len(invs)))
                              if not (acts[ui] and acts[ui][0] == 'DROP') and (hour == 23 or dist(positions[ui], nearest_shed(positions[ui])) <= P['SQ_NEAR']))
    if hour > 0:
        carried = sum(sum(inv.values()) for inv in invs)
        hold_plan(ctx, max(carried, plan.get('produce', 0) - S.get('dropped_today', 0)))
    S['dropped_today'] = S.get('dropped_today', 0) + sum(ctx['dropping'].values())
    if P['MS_CAPHARV']: acts = ms_capharv(ctx, acts)
    orders = market_orders(ctx)
    if ms_on():
        orders = ms_post(ctx, obs, orders, acts); ms_after(ctx, orders)
    if P['MPC_SELL'] and step >= 199: mpc_after(ctx, obs, orders)   # latemarket
    if P['DEBUG'] and os.environ.get('CIRCUIT_TRACE'):
        for ui in range(n_units):
            p = plans.get(ui)
            log(f"T d{day} h{hour} u{ui} pos {positions[ui]} act {acts[ui]} inv {dict(invs[ui]) if ui < len(invs) else {}} phase {p['phase'] if p else None} idx {p['idx'] if p else None}/{len(p['stops']) if p else None} next {p['stops'][p['idx']].pos if p and p['idx'] < len(p['stops']) else None}")
    if P['DEBUG'] and hour == 23 and S.get('exd'):
        log(f"EXD d{day} {sorted(S['exd'].items())}"); S['exd'] = {}
    if P['DEBUG'] and hour == 23:
        kc = {}
        for hh, pp, op in S['shed_log']: kc[(hh, op)] = kc.get((hh, op), 0) + 1
        log(f"SHED d{day} n {len(S['shed_log'])} {sorted(kc.items())}")
    if P['DEBUG'] and P['MT'] and hour == 23: log(f"MT d{day} held {S.get('mt_hold_now')} offer {S.get('mt_offer')} sqh {S.get('sq_hold_now')} shed_total {sum(priv['shed'].values())} carried {sum(sum(i.values()) for i in invs)}")
    if P['DEBUG'] and (hour in (0, 1, 23) or os.environ.get('CIRCUIT_LOG_ALL')):
        log(f"d{day} h{hour} money {me['money']:.0f} shed {dict((k, v) for k, v in priv['shed'].items() if v)} units {n_units} orders {orders} shed_log {S['shed_log'][-6:]}")
    return {'farmer': acts[0], 'hands': acts[1:], 'market': orders}

def safe_agent(obs, config=None):
    """Never let an exception end the episode: on error return a PASS step, re-plan at the next step (at most twice a day)."""
    try:
        return agent(obs, config)
    except Exception as e:      # noqa
        try:
            step = int(obs.get('step', 0)); day = step // 24
            f = S.setdefault('fail', {}); f[day] = f.get(day, 0) + 1
            if f[day] <= 2: S['day'] = None
            if P['DEBUG']:
                import traceback; log(f"EXC step {step}: {e!r}\n{traceback.format_exc()}")
            n = len(obs['farms'][obs['player']].get('hands', []))
        except Exception:
            n = 0
        return {'farmer': ['PASS'], 'hands': [['PASS']] * n, 'market': []}
